GRAVITY = 9.8
HIGH_ALTITUDE_THRESHOLD = 100.0


def validate_velocity(velocity):
    """Return the velocity as a float, rejecting non-numeric or negative input."""
    if isinstance(velocity, bool):
        raise TypeError("velocity must be a number, not a boolean")
    if not isinstance(velocity, (int, float)):
        raise TypeError("velocity must be a number")
    speed = float(velocity)
    if speed < 0:
        raise ValueError("velocity must not be negative")
    return speed


def time_to_apex(velocity):
    """Time in seconds until the upward speed is cancelled by gravity."""
    return velocity / GRAVITY


def half(value):
    return value / 2


def max_height(velocity):
    """Peak height reached by a projectile launched straight up."""
    rise_time = time_to_apex(velocity)
    average_speed = half(velocity)
    return average_speed * rise_time


def is_high_altitude(height):
    return height > HIGH_ALTITUDE_THRESHOLD


def simulate(velocities):
    """Return (time, height, high_altitude) for each initial vertical speed."""
    results = []
    for velocity in velocities:
        speed = validate_velocity(velocity)
        rise_time = time_to_apex(speed)
        height = max_height(speed)
        results.append((rise_time, height, is_high_altitude(height)))
    return results


def mean(values):
    if not values:
        return 0.0
    return sum(values) / len(values)


def format_row(velocity, result):
    rise_time, height, high = result
    label = "HIGH" if high else "normal"
    return "{:>8.2f} {:>8.2f} {:>10.2f}  {}".format(velocity, rise_time, height, label)


def build_report(velocities):
    """Produce a printable table plus a summary of the high-altitude launches."""
    results = simulate(velocities)
    lines = ["{:>8} {:>8} {:>10}  {}".format("v0", "t_apex", "h_max", "class")]
    for velocity, result in zip(velocities, results):
        lines.append(format_row(velocity, result))
    heights = [result[1] for result in results]
    high_count = sum(1 for result in results if result[2])
    lines.append("launches: {}, high altitude: {}".format(len(results), high_count))
    lines.append("average peak height: {:.2f} m".format(mean(heights)))
    return "\n".join(lines)


def main():
    velocities = [20, 5.5, 45, 60, 0, 31.3]
    print(build_report(velocities))
    fastest = max(velocities)
    slowest = min(velocities)
    print("speed spread: {:.2f} m/s".format(fastest - slowest))
    apex_of_fastest = time_to_apex(validate_velocity(fastest))
    print("fastest launch peaks after {:.2f} s".format(apex_of_fastest))


if __name__ == "__main__":
    main()

