def monthly_rate(annual_rate):
    """Convert an annual rate given as a decimal into a monthly rate."""
    return annual_rate / 12


def month_interest(balance, annual_rate):
    """Interest charged on a balance for one month."""
    rate = monthly_rate(annual_rate)
    return balance * rate


def principal_reduction(payment, interest):
    """The part of a payment that actually reduces the debt."""
    return payment - interest


def remaining_balance(principal, reduction):
    """Balance left after the principal reduction is applied."""
    return principal - reduction


def validate_loan(loan):
    """Reject loans that cannot be amortized."""
    if len(loan) != 3:
        raise ValueError("a loan needs a principal, a rate and a payment")
    principal, annual_rate, payment = loan
    if principal <= 0:
        raise ValueError("principal must be positive")
    if annual_rate < 0:
        raise ValueError("annual rate cannot be negative")
    interest = month_interest(principal, annual_rate)
    if payment <= interest:
        raise ValueError("payment must exceed the first month interest")


def amortize(loan):
    """Return (first month interest, principal paid, remaining balance)."""
    validate_loan(loan)
    principal, annual_rate, payment = loan
    interest = month_interest(principal, annual_rate)
    paid = principal_reduction(payment, interest)
    balance = remaining_balance(principal, paid)
    return (interest, paid, balance)


def build_schedule(loan):
    """Walk the loan month by month until the balance is cleared."""
    principal, annual_rate, payment = loan
    balance = principal
    month = 0
    rows = []
    while balance > 0:
        month += 1
        start = balance
        interest, paid, balance = amortize([start, annual_rate, payment])
        if balance < 0:
            paid = start
            balance = 0.0
        rows.append((month, interest, paid, balance))
    return rows


def format_row(row):
    month, interest, paid, balance = row
    return "{:5} {:12.2f} {:12.2f} {:12.2f}".format(month, interest, paid, balance)


def report(rows):
    lines = ["Month     Interest    Principal      Balance"]
    for row in rows:
        lines.append(format_row(row))
    return "\n".join(lines)


def main():
    loan = [1000.0, 0.12, 100.0]
    interest, paid, balance = amortize(loan)
    print("First month interest: {:.2f}".format(interest))
    print("Principal paid: {:.2f}".format(paid))
    print("Remaining balance: {:.2f}".format(balance))
    rows = build_schedule(loan)
    print(report(rows))
    total_interest = sum(row[1] for row in rows)
    print("Total interest: {:.2f}".format(total_interest))
    print("Paid off in {} months".format(len(rows)))


if __name__ == "__main__":
    main()

