import math

def mean(values):
    return sum(values) / len(values)

def deviation(value, average):
    return value - average

def squared(number):
    return number * number

def variance(values):
    average = mean(values)
    squares = [squared(deviation(value, average)) for value in values]
    return mean(squares)

def std_dev(values):
    return math.sqrt(variance(values))

def normalize(values):
    if len(values) == 0:
        raise ValueError("normalize requires at least one value")
    average = mean(values)
    spread = std_dev(values)
    if spread == 0.0:
        raise ValueError("normalize requires values that are not all equal")
    scores = []
    for value in values:
        offset = deviation(value, average)
        scores.append(offset / spread)
    return scores

def format_row(label, values):
    cells = [format(value, "8.2f") for value in values]
    body = " ".join(cells)
    return "{0}: {1}".format(label, body)

def report(name, values):
    scores = normalize(values)
    lines = [format_row(name, values)]
    lines.append(format_row("z-scores", scores))
    total = sum(scores)
    if abs(total) < 1e-9:
        total = 0.0
    summary = "mean {0:.4f} sd {1:.4f} sum {2:.4f}"
    lines.append(summary.format(mean(values), std_dev(values), total))
    return "\n".join(lines)

def main():
    datasets = [
        ("small", [2, 4, 6]),
        ("grades", [55, 68, 72, 90, 91, 100]),
        ("temps", [-3.5, 0.0, 4.25, 12.75]),
    ]
    for name, values in datasets:
        print(report(name, values))
        print("-" * 40)
    widest = datasets[0]
    for name, values in datasets:
        if std_dev(values) > std_dev(widest[1]):
            widest = (name, values)
    print("widest spread: " + widest[0])

if __name__ == "__main__":
    main()

