REGULAR_RATE = 20
OVERTIME_RATE = 30
STANDARD_WEEK = 40
HOURS_IN_WEEK = 168


def validate_hours(hours):
    """Check that the input is a list of sane weekly hour values."""
    if not isinstance(hours, (list, tuple)):
        raise TypeError("hours must be a list of numbers")
    for index, value in enumerate(hours):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("hour value at position {} is not numeric".format(index))
        if value < 0:
            raise ValueError("hour value at position {} is negative".format(index))
        if value > HOURS_IN_WEEK:
            raise ValueError("hour value at position {} exceeds a week".format(index))
    return list(hours)


def regular_pay(worked):
    """Pay earned for the hours that fall inside the standard week."""
    if worked > STANDARD_WEEK:
        return STANDARD_WEEK * REGULAR_RATE
    return worked * REGULAR_RATE


def overtime_hours(worked):
    """Hours worked beyond the standard week."""
    if worked > STANDARD_WEEK:
        return worked - STANDARD_WEEK
    return 0


def overtime_pay(worked):
    """Pay earned for the overtime hours."""
    return overtime_hours(worked) * OVERTIME_RATE


def pay_for_hours(worked):
    """Total weekly pay for a single employee."""
    return regular_pay(worked) + overtime_pay(worked)


def payroll(hours):
    """Return a list with the total weekly pay of each employee."""
    clean = validate_hours(hours)
    return [pay_for_hours(worked) for worked in clean]


def payroll_report(hours):
    """Build a printable payroll report for the given hours."""
    pays = payroll(hours)
    lines = ["  # | hours | overtime |    pay"]
    for number, (worked, pay) in enumerate(zip(hours, pays), 1):
        row = "{:3d} | {:5} | {:8} | {:6.2f}".format(number, worked, overtime_hours(worked), pay)
        lines.append(row)
    lines.append("total pay: {:.2f}".format(sum(pays)))
    return "\n".join(lines)


def main():
    week = [30, 45, 40, 52.5, 0]
    print(payroll(week))
    print(payroll_report(week))


if __name__ == "__main__":
    main()

