TAX_RATE = 0.08
HIGH_PRICE_THRESHOLD = 50
HIGH_DISCOUNT = 0.20
LOW_DISCOUNT = 0.10


def discount_rate(price):
    """Return the fraction taken off a single item's cost."""
    if price > HIGH_PRICE_THRESHOLD:
        return HIGH_DISCOUNT
    return LOW_DISCOUNT


def discounted_price(price):
    """Apply the appropriate discount to one item cost."""
    rate = discount_rate(price)
    return price * (1 - rate)


def validate_prices(prices):
    """Return the prices as floats, rejecting anything that is not a cost."""
    clean = []
    for index, price in enumerate(prices):
        if isinstance(price, bool) or not isinstance(price, (int, float)):
            raise TypeError("price at position %d is not a number" % index)
        if price < 0:
            raise ValueError("price at position %d is negative" % index)
        clean.append(float(price))
    return clean


def checkout(prices):
    """Return (subtotal, tax, total) for a list of item costs."""
    items = validate_prices(prices)
    subtotal = 0.0
    for price in items:
        subtotal = subtotal + discounted_price(price)
    subtotal = round(subtotal, 2)
    tax = round(subtotal * TAX_RATE, 2)
    total = round(subtotal + tax, 2)
    return (subtotal, tax, total)


def format_receipt(prices):
    """Build a printable receipt for the given basket."""
    lines = []
    for price in validate_prices(prices):
        percent = int(discount_rate(price) * 100)
        net = discounted_price(price)
        lines.append("  %8.2f  -%d%%  ->  %8.2f" % (price, percent, net))
    subtotal, tax, total = checkout(prices)
    lines.append("  subtotal          %8.2f" % subtotal)
    lines.append("  tax (8%%)          %8.2f" % tax)
    lines.append("  total             %8.2f" % total)
    return "\n".join(lines)


def main():
    baskets = [[40, 60], [50, 50.01, 12.5], []]
    for basket in baskets:
        label = ", ".join(str(price) for price in basket)
        if label == "":
            label = "empty basket"
        print("Basket: " + label)
        print(format_receipt(basket))
        print()


if __name__ == "__main__":
    main()

