def validate_entry(entry):
    if len(entry) != 3:
        raise ValueError("each stat entry needs attack, defense and multiplier")
    for value in entry:
        if not isinstance(value, (int, float)):
            raise TypeError("stat values must be numeric")
    attack, defense, multiplier = entry
    if attack < 0:
        raise ValueError("attack power cannot be negative")
    if defense < 0:
        raise ValueError("target defense cannot be negative")
    if multiplier < 0:
        raise ValueError("base multiplier cannot be negative")
    return attack, defense, multiplier


def net_power(attack, defense):
    if attack < defense:
        return 0
    return attack - defense


def scale(power, multiplier):
    return power * multiplier


def cap(damage):
    if damage > 100:
        return 100
    return damage


def combat(stats):
    results = []
    for entry in stats:
        attack, defense, multiplier = validate_entry(entry)
        power = net_power(attack, defense)
        raw = scale(power, multiplier)
        results.append(cap(raw))
    return results


def is_capped(damage):
    return damage >= 100


def count_capped(damages):
    return len(list(filter(is_capped, damages)))


def average_damage(damages):
    if not damages:
        return 0
    return sum(damages) / len(damages)


def format_round(index, entry, damage):
    attack, defense, multiplier = entry
    label = "attacker {0}".format(index)
    detail = "atk {0} def {1} x{2}".format(attack, defense, multiplier)
    return "{0:<12}{1:>22}  damage {2}".format(label, detail, damage)


def battle_report(stats):
    damages = combat(stats)
    lines = []
    for index, pair in enumerate(zip(stats, damages), start=1):
        lines.append(format_round(index, pair[0], pair[1]))
    lines.append("total damage: {0}".format(sum(damages)))
    lines.append("average damage: {0:.2f}".format(average_damage(damages)))
    lines.append("capped attacks: {0}".format(count_capped(damages)))
