def to_celsius(fahrenheit):
    """Convert a single Fahrenheit reading to Celsius."""
    shifted = (
        fahrenheit - 32
    )
    scaled = (
        shifted * 5
    )
    return scaled / 9


def validate(temperatures):
    """Return the readings as a list of floats, rejecting unusable input."""
    if temperatures is None:
        raise ValueError("no temperature data supplied")
    readings = list(temperatures)
    if len(readings) == 0:
        raise ValueError("temperature list is empty")
    checked = []
    for value in readings:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("temperatures must be numbers, got %r" % (value,))
        checked.append(float(value))
    return checked


def climate(temperatures):
    """Convert to Celsius, then report the peak, the range and volatility."""
    readings = validate(temperatures)
    celsius = [to_celsius(reading) for reading in readings]
    highest = max(celsius)
    lowest = min(celsius)
    spread = (
        highest - lowest
    )
    volatile = (
        spread > 15
    )
    return highest, spread, volatile


def average_celsius(temperatures):
    """Mean Celsius temperature of the series."""
    celsius = [to_celsius(reading) for reading in validate(temperatures)]
    total = sum(celsius)
    return total / len(celsius)


def format_report(label, temperatures):
    """Build a one-line human readable summary for a named series."""
    highest, spread, volatile = climate(temperatures)
    mood = "volatile" if volatile else "steady"
    days = len(temperatures)
    return "%s (%d days): peak %.1fC, range %.1fC, %s" % (
        label,
        days,
        highest,
        spread,
        mood,
    )


def main():
    series = {
        "Coastal": [32, 50],
        "Desert": [55, 68, 104, 99, 71],
        "Alpine": [40, 41, 38, 44],
    }
    for label in sorted(series):
        readings = series[label]
        print(format_report(label, readings))
        mean = average_celsius(readings)
        print("    mean %.2fC" % mean)
    hottest = max(series, key=lambda name: climate(series[name])[0])
    print("Hottest peak recorded in: " + hottest)
    volatile_count = sum(1 for name in series if climate(series[name])[2])
    print("Volatile series: %d of %d" % (volatile_count, len(series)))


if __name__ == "__main__":
    main()

