BASE_COST = 5.0
FREE_WEIGHT_LIMIT = 10.0
SURCHARGE_PER_POUND = 2.0
HEAVY_WEIGHT_LIMIT = 50.0
HEAVY_FEE = 20.0


def validate_weight(weight):
    """Convert a package weight to a float, rejecting bad input."""
    if isinstance(weight, bool):
        raise TypeError("package weight must be a number, not a boolean")
    try:
        value = float(weight)
    except (TypeError, ValueError):
        raise TypeError("package weight must be a number: {0!r}".format(weight))
    if value < 0:
        raise ValueError("package weight must not be negative")
    return value


def excess_weight(weight):
    """Pounds above the free allowance."""
    return weight - FREE_WEIGHT_LIMIT


def weight_surcharge(weight):
    """Per-pound charge for the pounds above the free allowance."""
    return excess_weight(weight) * SURCHARGE_PER_POUND


def heavy_fee(weight):
    """Flat fee charged once a package passes the heavy threshold."""
    if weight > HEAVY_WEIGHT_LIMIT:
        return HEAVY_FEE
    return 0.0


def surcharge(weight):
    """Cost above the base cost for a single package of the given weight."""
    if weight <= FREE_WEIGHT_LIMIT:
        return 0.0
    return weight_surcharge(weight) + heavy_fee(weight)


def package_cost(weight):
    """Total shipping cost for one package."""
    return BASE_COST + surcharge(weight)


def freight(packages):
    """Return the list of total shipping costs for the given package weights."""
    costs = []
    for weight in packages:
        clean = validate_weight(weight)
        costs.append(package_cost(clean))
    return costs


def format_number(value):
    """Render a cost or weight without a trailing '.0' when it is whole."""
    rounded = round(value, 2)
    if rounded == int(rounded):
        return str(int(rounded))
    return "{0:.2f}".format(rounded)


def shipping_report(packages):
    """Build a human readable per-package report plus a total line."""
    costs = freight(packages)
    lines = []
    for index, (weight, cost) in enumerate(zip(packages, costs), start=1):
        weight_text = format_number(float(weight))
        cost_text = format_number(cost)
        lines.append("Package {0}: {1} lb -> ${2}".format(index, weight_text, cost_text))
    grand_total = sum(costs)
    lines.append("Total for {0} package(s): ${1}".format(len(costs), format_number(grand_total)))
    return "\n".join(lines)


def main():
    shipment = [5, 12, 60, 10.5, 50, 51]
    print(shipping_report(shipment))
    heaviest = max(shipment)
    print("Heaviest package: {0} lb".format(format_number(heaviest)))
    print(freight([5, 12, 60]))


if __name__ == "__main__":
    main()

