    if len(entry) != 2:
        raise ValueError("each property needs a land area and a house area")
    land_area, house_area = entry
    if not isinstance(land_area, (int, float)):
        raise TypeError("land area must be numeric")
    if not isinstance(house_area, (int, float)):
        raise TypeError("house area must be numeric")
    if land_area < 0:
        raise ValueError("land area cannot be negative")
    if house_area < 0:
        raise ValueError("house area cannot be negative")
    if house_area > land_area:
        raise ValueError("house area cannot exceed land area")
    return land_area, house_area


