        raise ValueError("grade below zero: " + str(grade))
    if grade > 100:
        raise ValueError("grade above a hundred point scale: " + str(grade))
    if grade >= 90:
        return 4
    if grade >= 80:
        return 3
    return 2


def student_gpa(grades):
    if len(grades) == 0:
        raise ValueError("a student record must contain at least one course grade")
    total = sum(grade_points(grade) for grade in grades)
    return total / len(grades)


def academics(students):
