    if rejected>total:
        raise ValueError("rejected units cannot exceed units started")


def production(batches):
    results=[]
    for total, rejected in batches:
        validate_batch(total, rejected)
        good=good_units(total, rejected)
        percentage=yield_percentage(good, total)
        results.append((good, percentage, is_defective(percentage)))
    return results


def summarize(results):
    percentages=[percentage for _, percentage, _ in results]
    summary={}
    summary["good_units"]=sum(good for good, _, _ in results)
    summary["defective"]=sum(1 for _, _, flag in results if flag)
    summary["average_yield"]=mean(percentages)
    summary["worst_yield"]=min(percentages)
    return summary


def report(batches):
    results=production(batches)
    lines=["batch  good   yield  status"]
    for number, (good, percentage, defective) in enumerate(results, start=1):
        status="DEFECTIVE" if defective else "OK"
        lines.append(f"{number:>5}  {good:>4}  {percentage:6.2f}  {status}")
    stats=summarize(results)
    lines.append(f"good units total : {stats['good_units']}")
    lines.append(f"average yield    : {stats['average_yield']:.2f}%")
    lines.append(f"worst yield      : {stats['worst_yield']:.2f}%")
    if stats["defective"]>0:
        lines.append(f"batches flagged  : {stats['defective']}")
    else:
        lines.append("batches flagged  : none")
    return "\n".join(lines)


def main():
    batches=[(100, 5), (200, 12), (50, 1), (500, 40)]
    print(report(batches))
    print(production([(100, 5)]))


if __name__=="__main__":
    main()

