CONVERSION_RATE = 1.25
TRANSACTION_FEE = 2.5


def validate_amount(amount):
    """Return the amount as a float, rejecting anything that is not a number."""
    if isinstance(amount, bool):
        raise TypeError("boolean values are not valid transaction amounts")
    if not isinstance(amount, (int, float)):
        raise TypeError("transaction amounts must be numeric, got %r" % (amount,))
    value = float(amount)
    if value < 0:
        raise ValueError("transaction amounts cannot be negative: %r" % (amount,))
    return value


def raw_dollars(amount):
    """Dollar value of one foreign amount before the transaction fee."""
    return validate_amount(amount) * CONVERSION_RATE


def net_dollars(amount):
    """Convert one foreign amount to net dollars, floored at zero."""
    raw = raw_dollars(amount)
    if raw < TRANSACTION_FEE:
        return 0.0
    return raw - TRANSACTION_FEE


def exchange(transactions):
    """Convert a list of foreign-currency amounts into net dollar amounts."""
    return [net_dollars(amount) for amount in transactions]


def total_fees(transactions):
    """Total fees actually charged, capped by the raw value of each exchange."""
    return sum(min(raw_dollars(a), TRANSACTION_FEE) for a in transactions)


def breakeven_amount():
    """Smallest foreign amount whose raw value covers the transaction fee."""
    return TRANSACTION_FEE / CONVERSION_RATE


def amounts_with_net(transactions, nets, target):
    """All input amounts whose net payout equals the given target."""
    return [amount for amount, net in zip(transactions, nets) if net == target]


def format_report(transactions):
    """Build a human readable line for every transaction plus a summary."""
    nets = exchange(transactions)
    lines = []
    for amount, net in zip(transactions, nets):
        raw = raw_dollars(amount)
        status = "cleared"
        if net <= 0:
            status = "absorbed by fee"
        lines.append(
            "%8.2f units: raw $%7.2f, net $%7.2f (%s)" % (amount, raw, net, status)
        )
    payout = sum(nets)
    lines.append("=" * 56)
    lines.append("transactions: %d" % len(nets))
    lines.append("total payout: $%.2f" % payout)
    lines.append("fees charged: $%.2f" % total_fees(transactions))
    return "\n".join(lines)


def main():
    batch = [10, 1, 0, 2, 40.5, 100]
    print(format_report(batch))
    nets = exchange(batch)
    best = max(nets)
    winners = amounts_with_net(batch, nets, best)
    print("largest net payout: $%.2f from %s units" % (best, winners[0]))
    losers = amounts_with_net(batch, nets, 0.0)
    if losers:
        print("unprofitable amounts: %s" % (losers,))
    print("break-even amount: %.2f foreign units" % breakeven_amount())


if __name__ == "__main__":
    main()

