FLAT_RATE = 30
INCLUDED_GIGABYTES = 5
OVERAGE_RATE = 10


def overage(gigabytes):
    """Return the gigabytes billed as overage for one account."""
    if gigabytes > INCLUDED_GIGABYTES:
        return gigabytes - INCLUDED_GIGABYTES
    return 0


def overage_fee(gigabytes):
    """Return the extra dollars charged beyond the flat rate."""
    return overage(gigabytes) * OVERAGE_RATE


def account_bill(gigabytes):
    """Return the monthly bill in dollars for a single account."""
    fee = overage_fee(gigabytes)
    return FLAT_RATE + fee


def parse_usage(raw):
    """Turn one raw usage entry into a non-negative number of gigabytes."""
    if isinstance(raw, str):
        value = float(raw.strip())
    else:
        value = float(raw)
    if value < 0:
        raise ValueError("usage cannot be negative: {0!r}".format(raw))
    whole = int(value)
    if value == whole:
        return whole
    return value


def billing(accounts):
    """Return the list of total bills for the given list of gigabyte usages."""
    bills = []
    for raw in accounts:
        usage = parse_usage(raw)
        bills.append(account_bill(usage))
    return bills


def average_bill(bills):
    """Return the mean bill, or zero when there are no accounts."""
    if not bills:
        return 0
    return sum(bills) / len(bills)


def format_report(accounts, bills):
    """Build a per-account report plus a summary line."""
    lines = []
    for number, pair in enumerate(zip(accounts, bills), 1):
        raw, bill = pair
        usage = parse_usage(raw)
        extra = overage(usage)
        note = "included"
        if extra > 0:
            note = "{0} GB over".format(extra)
        lines.append("Account {0}: {1} GB costs ${2} ({3})".format(number, usage, bill, note))
    total = sum(bills)
    average = average_bill(bills)
    lines.append("Accounts: {0}  Total: ${1}  Average: ${2:.2f}".format(len(bills), total, average))
    return "\n".join(lines)


def main():
    usages = [4, 7, 5, 0, "12", 8.5]
    bills = billing(usages)
    print(format_report(usages, bills))
    biggest = max(bills)
    for raw, bill in zip(usages, bills):
        if bill == biggest:
            print("Highest bill: {0} GB costing ${1}".format(parse_usage(raw), bill))
            break


if __name__ == "__main__":
    main()

