def total_distance(perihelion, aphelion):
    return perihelion + aphelion


def distance_span(perihelion, aphelion):
    return aphelion - perihelion


def semi_major_axis(perihelion, aphelion):
    total = total_distance(perihelion, aphelion)
    return total / 2


def eccentricity(perihelion, aphelion):
    difference = distance_span(perihelion, aphelion)
    total = total_distance(perihelion, aphelion)
    return difference / total


def validate(perihelion, aphelion):
    if perihelion <= 0:
        raise ValueError("perihelion must be positive")
    if aphelion < perihelion:
        raise ValueError("aphelion must not be smaller than perihelion")


def orbit(planets):
    results = []
    for perihelion, aphelion in planets:
        validate(perihelion, aphelion)
        axis = semi_major_axis(perihelion, aphelion)
        ecc = eccentricity(perihelion, aphelion)
        results.append((axis, ecc))
    return results


def classify(ecc):
    if ecc < 0.01:
        return "nearly circular"
    if ecc < 0.1:
        return "slightly elliptical"
    return "markedly elliptical"


def format_row(name, axis, ecc):
    shape = classify(ecc)
    return "{:<10}{:>12.2f}{:>10.4f}   {}".format(name, axis, ecc, shape)


def report(names, planets):
    orbits = orbit(planets)
    header = "{:<10}{:>12}{:>10}   {}".format("planet", "semi-major", "ecc", "shape")
    lines = [header]
    for name, (axis, ecc) in zip(names, orbits):
        lines.append(format_row(name, axis, ecc))
    return lines


def most_eccentric(names, planets):
    orbits = orbit(planets)
    best_name = names[0]
    best_ecc = orbits[0][1]
    for name, (_axis, ecc) in zip(names[1:], orbits[1:]):
        if ecc > best_ecc:
            best_ecc = ecc
            best_name = name
    return best_name, best_ecc


def main():
    names = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Neptune"]
    distances = [
        (46.0, 69.8),
        (107.5, 108.9),
        (147.1, 152.1),
        (206.7, 249.2),
        (740.5, 816.6),
        (4459.0, 4537.0),
    ]
    for line in report(names, distances):
        print(line)
    name, ecc = most_eccentric(names, distances)
    print("Most eccentric orbit: {} ({:.4f})".format(name, ecc))


if __name__ == "__main__":
    main()

