TARGET_VOLUME = 5.0
WEAK_THRESHOLD = 0.1


def total_moles(volume, concentration):
    """Moles of solute held by a volume at a given concentration."""
    return volume * concentration


def dilute_one(volume, concentration):
    """Concentration after topping the solution up to the target volume."""
    moles = total_moles(volume, concentration)
    return moles / TARGET_VOLUME


def is_weak(concentration):
    return concentration < WEAK_THRESHOLD


def dilution_factor(volume):
    return TARGET_VOLUME / volume


def validate_solution(index, entry):
    """Check one (volume, concentration) pair and return it as floats."""
    if len(entry) != 2:
        raise ValueError("solution %d must be a (volume, concentration) pair" % index)
    volume, concentration = entry
    if volume <= 0:
        raise ValueError("solution %d has a non-positive volume" % index)
    if concentration < 0:
        raise ValueError("solution %d has a negative concentration" % index)
    if volume > TARGET_VOLUME:
        raise ValueError("solution %d already exceeds the target volume" % index)
    return float(volume), float(concentration)


def dilution(solutions):
    """New concentrations once every solution is diluted to five liters."""
    concentrations = []
    for index, entry in enumerate(solutions, start=1):
        volume, concentration = validate_solution(index, entry)
        concentrations.append(dilute_one(volume, concentration))
    return concentrations


def format_row(index, entry, concentration):
    volume, initial = entry
    factor = dilution_factor(volume)
    moles = total_moles(volume, initial)
    strength = "weak" if is_weak(concentration) else "usable"
    return "%d: %.2f L @ %.3f M -> %.3f M (x%.2f, %.3f mol, %s)" % (
        index, volume, initial, concentration, factor, moles, strength)


def summarize(solutions):
    concentrations = dilution(solutions)
    rows = []
    for index, entry in enumerate(solutions):
        rows.append(format_row(index + 1, entry, concentrations[index]))
    weak_count = sum(1 for value in concentrations if is_weak(value))
    strongest = max(concentrations)
    rows.append("weak solutions: %d of %d" % (weak_count, len(concentrations)))
    rows.append("strongest result: %.3f M" % strongest)
    return rows


def main():
    samples = [(2.0, 1.0), (0.5, 0.8), (4.0, 0.05), (1.0, 12.0)]
    for line in summarize(samples):
        print(line)


if __name__ == "__main__":
    main()

