NETWORK_SPEED_MBPS = 20
BITS_PER_MEGABYTE = 8
SECONDS_PER_MINUTE = 60


def validate_sizes(files):
    """Return the file sizes as floats, rejecting anything unusable."""
    cleaned = []
    for index, size in enumerate(files):
        if isinstance(size, bool) or not isinstance(size, (int, float)):
            raise TypeError("file %d is not a number: %r" % (index, size))
        value = float(size)
        if value < 0:
            raise ValueError("file %d has a negative size: %r" % (index, size))
        cleaned.append(value)
    return cleaned


def megabits(megabytes):
    """Convert a size in megabytes to megabits."""
    return megabytes * BITS_PER_MEGABYTE


def seconds_for(megabytes):
    """Time in seconds needed to push one file over the link."""
    bits = megabits(megabytes)
    return bits / NETWORK_SPEED_MBPS


def split_minutes(seconds):
    """Split a duration into whole minutes and the remaining seconds."""
    minutes, rest = divmod(seconds, SECONDS_PER_MINUTE)
    return int(minutes), rest


def format_duration(seconds):
    """Describe a duration, using minutes once it passes a minute."""
    if seconds > SECONDS_PER_MINUTE:
        minutes, rest = split_minutes(seconds)
        if rest > 0:
            return "%d min %.1f s" % (minutes, rest)
        return "%d min" % minutes
    return "%.1f s" % seconds


def transfer(files):
    """Return the transfer time in seconds for every file size given."""
    sizes = validate_sizes(files)
    times = []
    for size in sizes:
        times.append(seconds_for(size))
    return times


def report(files):
    """Build a human readable line for each file and a total line."""
    times = transfer(files)
    lines = []
    for size, seconds in zip(files, times):
        lines.append("%g MB: %s" % (size, format_duration(seconds)))
    total = sum(times)
    lines.append("total: %s" % format_duration(total))
    return lines


def main():
    batch = [50, 100, 12.5, 400]
    for line in report(batch):
        print(line)
    small = transfer([50, 100])
    print("seconds:", small)


if __name__ == "__main__":
    main()

