from statistics import fmean


def validate_record(record):
    """Check that a salary record is usable and return its three parts."""
    if len(record) != 3:
        raise ValueError("each record needs a start, an end and an inflation rate")
    start, end, inflation = record
    if start <= 0:
        raise ValueError("starting salary must be positive")
    if end < 0:
        raise ValueError("ending salary cannot be negative")
    if inflation < -1:
        raise ValueError("inflation rate is out of range")
    return float(start), float(end), float(inflation)


def nominal_growth(start, end):
    """Absolute change in pay between the two salaries."""
    return end - start


def nominal_rate(start, end):
    """Nominal growth expressed as a fraction of the starting salary."""
    growth = nominal_growth(start, end)
    return growth / start


def real_rate(start, end, inflation):
    """Nominal percentage increase less the inflation rate."""
    return nominal_rate(start, end) - inflation


def wages(salaries):
    """Return the real wage growth rate for every (start, end, inflation) record."""
    rates = []
    for record in salaries:
        start, end, inflation = validate_record(record)
        rates.append(real_rate(start, end, inflation))
    return rates


def lost_ground(rates):
    """Count the records whose real wage growth is negative."""
    return len([rate for rate in rates if rate < 0])


def describe(record, rate):
    """One human readable line about a single record's purchasing power."""
    start, end, inflation = validate_record(record)
    verdict = "decreased"
    if rate > 0:
        verdict = "increased"
    elif rate == 0:
        verdict = "held steady"
    return (
        "{:,.0f} -> {:,.0f} with {:.1%} inflation: real growth {:+.2f}% "
        "(purchasing power {})".format(start, end, inflation, rate * 100, verdict)
    )


def report(salaries):
    """Build a report of every record plus the average real growth."""
    rates = wages(salaries)
    lines = [describe(record, rate) for record, rate in zip(salaries, rates)]
    average = fmean(rates)
    lines.append("average real growth: {:+.2f}%".format(average * 100))
    lines.append("records losing purchasing power: {} of {}".format(lost_ground(rates), len(rates)))
    return lines


def main():
    salaries = [
        (50000, 55000, 0.05),
        (40000, 41000, 0.03),
        (72000, 79200, 0.10),
        (60000, 60000, 0.02),
    ]
    for line in report(salaries):
        print(line)


if __name__ == "__main__":
    main()

