import math

REFERENCE_PRESSURE = 20.0
HARMFUL_THRESHOLD = 85.0


def validate_pressure(value):
    """Return the pressure as a float, rejecting values that cannot be measured."""
    if isinstance(value, bool):
        raise TypeError("sound pressure must be a number, not a boolean")
    if not isinstance(value, (int, float)):
        raise TypeError("sound pressure must be a number")
    pressure = float(value)
    if pressure <= 0.0:
        raise ValueError("sound pressure must be greater than zero micropascals")
    return pressure


def pressure_ratio(pressure):
    """Return how many times louder the pressure is than the reference."""
    return validate_pressure(pressure) / REFERENCE_PRESSURE


def decibel_level(pressure):
    """Convert a single pressure in micropascals to a sound pressure level in dB."""
    ratio = pressure_ratio(pressure)
    return 20.0 * math.log10(ratio)


def acoustics(pressures):
    """Return the decibel level of every pressure given in micropascals."""
    return [decibel_level(pressure) for pressure in pressures]


def is_harmful(level):
    """A level above eighty five decibels damages hearing over time."""
    return level > HARMFUL_THRESHOLD


def safety_margin(level):
    """Return how far a level sits above the harmful threshold."""
    return level - HARMFUL_THRESHOLD


def describe(level):
    """Give a short verbal label for a decibel level."""
    if is_harmful(level):
        return "harmful"
    if level >= 60.0:
        return "loud"
    if level >= 30.0:
        return "moderate"
    return "quiet"


def report(pressures):
    """Build printable lines pairing each pressure with its level and label."""
    levels = acoustics(pressures)
    lines = []
    for pressure, level in zip(pressures, levels):
        label = describe(level)
        lines.append("{:>12.1f} uPa -> {:6.2f} dB  ({})".format(pressure, level, label))
    harmful_count = sum(1 for level in levels if is_harmful(level))
    lines.append("harmful readings: {} of {}".format(harmful_count, len(levels)))
    return lines


def loudest(pressures):
    """Return the highest decibel level in the batch."""
    levels = acoustics(pressures)
    if not levels:
        raise ValueError("no pressures were supplied")
    best = levels[0]
    for level in levels[1:]:
        if level > best:
            best = level
    return best


def main():
    samples = [200.0, 20.0, 2000.0, 632455.0, 2000000.0]
    for line in report(samples):
        print(line)
    peak = loudest(samples)
    print("peak level: {:.2f} dB".format(peak))
    margin = safety_margin(peak)
    if margin > 0.0:
        print("peak exceeds the safe limit by {:.2f} dB".format(margin))
    else:
        print("all readings stay within the safe limit")


if __name__ == "__main__":
    main()

