def validate_region(region):
    if len(region) != 3:
        raise ValueError("each region needs population, birth rate, death rate")
    initial, birth, death = region
    if initial < 0:
        raise ValueError("initial population cannot be negative")
    if birth < 0:
        raise ValueError("birth rate cannot be negative")
    if death < 0:
        raise ValueError("death rate cannot be negative")
    return float(initial), float(birth), float(death)


def net_growth_rate(birth, death):
    return birth - death


def population_change(initial, rate):
    return initial * rate


def as_percent(rate):
    return rate * 100.0


def final_population(initial, birth, death):
    rate = net_growth_rate(birth, death)
    change = population_change(initial, rate)
    return initial + change


def population(regions):
    finals = []
    for region in regions:
        initial, birth, death = validate_region(region)
        finals.append(final_population(initial, birth, death))
    return finals


def is_declining(initial, final):
    return final < initial


def classify(initial, final):
    if is_declining(initial, final):
        return "decline"
    if final > initial:
        return "growth"
    return "stable"


def describe_region(index, region, final):
    initial, birth, death = validate_region(region)
    rate = net_growth_rate(birth, death)
    change = population_change(initial, rate)
    percent = as_percent(rate)
    status = classify(initial, final)
    return "Region {0}: {1:.1f} -> {2:.1f} ({3:+.1f}, {4:+.2f}%) {5}".format(
        index, initial, final, change, percent, status)


def report(regions):
    finals = population(regions)
    lines = []
    for index, (region, final) in enumerate(zip(regions, finals), 1):
        lines.append(describe_region(index, region, final))
    declining = sum(1 for r, f in zip(regions, finals) if is_declining(float(r[0]), f))
    total_initial = sum(float(r[0]) for r in regions)
    total_final = sum(finals)
    lines.append("Totals: {0:.1f} -> {1:.1f}".format(total_initial, total_final))
    lines.append("Regions in decline: {0} of {1}".format(declining, len(regions)))
    return lines


def main():
    regions = [
        (100, 0.1, 0.05),
        (2500, 0.02, 0.09),
        (18000, 0.045, 0.045),
        (640, 0.15, 0.011),
    ]
    for line in report(regions):
        print(line)


if __name__ == "__main__":
    main()

