DAYS_PER_YEAR = 365
LOSS_FACTOR = 1.2
PANEL_RATING_W = 400
ROOF_PANEL_LIMIT = 20


def validate_inputs(consumption, peak):
    """Reject values that cannot describe a real installation."""
    if consumption <= 0:
        raise ValueError("yearly consumption must be positive")
    if peak <= 0:
        raise ValueError("peak sun hours must be positive")
    if peak > 12:
        raise ValueError("peak sun hours above 12 are not realistic")


def daily_energy(consumption):
    """Average energy used per day, in the same unit as consumption."""
    return consumption / DAYS_PER_YEAR


def adjust_for_losses(energy):
    """Inflate the daily need to cover wiring, inverter and heat losses."""
    return energy * LOSS_FACTOR


def array_wattage(adjusted, peak):
    """Array size needed to harvest the adjusted energy in `peak` hours."""
    return adjusted / peak


def panel_count(wattage):
    """Number of standard panels, kept fractional for reporting."""
    return wattage / PANEL_RATING_W


def panels_to_buy(panels):
    """Whole panels actually installed, rounding any fraction upwards."""
    whole = int(panels)
    if panels > whole:
        return whole + 1
    return whole


def solar(consumption, peak):
    validate_inputs(consumption, peak)
    daily = daily_energy(consumption)
    adjusted = adjust_for_losses(daily)
    wattage = array_wattage(adjusted, peak)
    panels = panel_count(wattage)
    return (daily, adjusted, wattage, panels, panels < ROOF_PANEL_LIMIT)


def format_report(consumption, peak):
    """Human readable summary of one sizing run."""
    daily, adjusted, wattage, panels, fits_roof = solar(consumption, peak)
    verdict = "fits the roof" if fits_roof else "exceeds the roof limit"
    lines = [
        "Yearly consumption: {:.0f} Wh at {:.1f} peak sun hours".format(consumption, peak),
        "Daily energy: {:.1f} Wh".format(daily),
        "Adjusted daily energy: {:.1f} Wh".format(adjusted),
        "Array wattage: {:.1f} W".format(wattage),
        "Panels needed: {:.2f} ({:d} bought) - {:s}".format(panels, panels_to_buy(panels), verdict),
    ]
    return "\n".join(lines)


def main():
    cases = [(4_000_000, 5.0), (9_500_000, 4.2), (1_200_000, 6.5)]
    for consumption, peak in cases:
        print(format_report(consumption, peak))
        print("-" * 40)
    oversized = [c for c, p in cases if not solar(c, p)[4]]
    print("Installations over the {:d} panel limit: {:d}".format(ROOF_PANEL_LIMIT, len(oversized)))


if __name__ == "__main__":
    main()

