    adjusted=adjust_for_losses(daily)
    wattage=array_wattage(adjusted, peak)
    panels=panel_count(wattage)
    return (daily, adjusted, wattage, panels, panels<ROOF_PANEL_LIMIT)


def format_report(consumption, peak):
    """Human readable summary of one sizing run."""
    daily, adjusted, wattage, panels, fits_roof=solar(consumption, peak)
    verdict="fits the roof" if fits_roof else "exceeds the roof limit"
    lines=[
        "Yearly consumption: {:.0f} Wh at {:.1f} peak sun hours".format(consumption, peak),
        "Daily energy: {:.1f} Wh".format(daily),
        "Adjusted daily energy: {:.1f} Wh".format(adjusted),
        "Array wattage: {:.1f} W".format(wattage),
        "Panels needed: {:.2f} ({:d} bought) - {:s}".format(panels, panels_to_buy(panels), verdict),
    ]
    return "\n".join(lines)


def main():
    cases=[(4_000_000, 5.0), (9_500_000, 4.2), (1_200_000, 6.5)]
    for consumption, peak in cases:
        print(format_report(consumption, peak))
        print("-"*40)
    oversized=[c for c, p in cases if not solar(c, p)[4]]
    print("Installations over the {:d} panel limit: {:d}".format(ROOF_PANEL_LIMIT, len(oversized)))


