RETENTION_FACTOR = 2.0
CONCENTRATION = 0.014
MIN_YIELD = 0.18
MAX_YIELD = 0.22

def retained_water(dose):
    return dose * RETENTION_FACTOR

def beverage_weight(water, retained):
    return water - retained

def dissolved_solids(beverage):
    return beverage * CONCENTRATION

def extraction_yield(solids, dose):
    return solids / dose

def above_minimum(ratio):
    return ratio > MIN_YIELD

def below_maximum(ratio):
    return ratio < MAX_YIELD

def validate(dose, water):
    if dose <= 0:
        raise ValueError("coffee dose must be positive")
    if water <= 0:
        raise ValueError("brewing water must be positive")
    if water <= retained_water(dose):
        raise ValueError("brewing water is fully absorbed by the grounds")

def extraction(dose, water):
    """Return (beverage, solids, yield, above_min, below_max) for one brew."""
    validate(dose, water)
    retained = retained_water(dose)
    beverage = beverage_weight(water, retained)
    solids = dissolved_solids(beverage)
    ratio = extraction_yield(solids, dose)
    above_min = above_minimum(ratio)
    below_max = below_maximum(ratio)
    return beverage, solids, ratio, above_min, below_max

def brew_ratio(dose, water):
    return water / dose

def as_percent(fraction):
    return fraction * 100

def classify(above_min, below_max):
    if above_min and below_max:
        return "balanced"
    if not above_min:
        return "under-extracted"
    return "over-extracted"

def balanced_share(labels):
    return labels.count("balanced") / len(labels)

def report(dose, water):
    beverage, solids, ratio, above_min, below_max = extraction(dose, water)
    label = classify(above_min, below_max)
    lines = ["Dose: {0:.1f} g   Water: {1:.1f} g   Ratio 1:{2:.1f}".format(
        dose, water, brew_ratio(dose, water))]
    lines.append("Beverage weight: {0:.2f} g".format(beverage))
    lines.append("Dissolved solids: {0:.3f} g".format(solids))
    lines.append("Extraction yield: {0:.2f}%  ({1})".format(
        as_percent(ratio), label))
    return "\n".join(lines), label

def main():
    brews = [(18.0, 300.0), (20.0, 320.0), (15.0, 250.0), (22.0, 500.0)]
    labels = []
    for dose, water in brews:
        text, label = report(dose, water)
        print(text)
        labels.append(label)
        print("-" * 40)
    print("Balanced brews: {0}/{1} ({2:.0f}%)".format(
        labels.count("balanced"), len(labels), as_percent(balanced_share(labels))))

if __name__ == "__main__":
    main()

