TANK_CAPACITY = 2000.0
PLANNED_TIME = 45.0
ASCENT_FACTOR = 5.0


def validate_plan(depth, rate):
    if depth < 0:
        raise ValueError("depth must not be negative")
    if rate <= 0:
        raise ValueError("surface air consumption rate must be positive")


def atmospheres(depth):
    return depth / 10.0


def ambient_pressure(depth):
    return atmospheres(depth) + 1.0


def depth_consumption(rate, pressure):
    return rate * pressure


def bottom_gas(consumption_rate):
    return consumption_rate * PLANNED_TIME


def reserve_gas(rate, pressure):
    return depth_consumption(rate, pressure) * ASCENT_FACTOR


def total_gas(bottom, reserve):
    return bottom + reserve


def fits_standard_tank(total):
    return total < TANK_CAPACITY


def spare_capacity(total):
    return TANK_CAPACITY - total


def shortfall(total):
    return total - TANK_CAPACITY


def dive(depth, rate):
    validate_plan(depth, rate)
    pressure = ambient_pressure(depth)
    consumption_rate = depth_consumption(rate, pressure)
    bottom = bottom_gas(consumption_rate)
    reserve = reserve_gas(rate, pressure)
    total = total_gas(bottom, reserve)
    within_capacity = fits_standard_tank(total)
    return (pressure, consumption_rate, bottom, reserve, total, within_capacity)


def format_report(depth, rate, result):
    pressure, consumption_rate, bottom, reserve, total, within_capacity = result
    if within_capacity:
        verdict = "one standard tank is enough, spare %.1f L" % spare_capacity(total)
    else:
        verdict = "short by %.1f L, plan a bigger cylinder" % shortfall(total)
    lines = ["Dive to %.1f m with a surface rate of %.1f L/min" % (depth, rate)]
    lines.append("  ambient pressure      : %.2f bar" % pressure)
    lines.append("  depth consumption     : %.2f L/min" % consumption_rate)
    lines.append("  bottom gas (%.0f min)  : %.1f L" % (PLANNED_TIME, bottom))
    lines.append("  reserve gas           : %.1f L" % reserve)
    lines.append("  total required gas    : %.1f L" % total)
    lines.append("  verdict: " + verdict)
    return "\n".join(lines)


def main():
    plans = [(18.0, 20.0), (30.0, 18.0), (40.0, 22.0)]
    results = [dive(depth, rate) for depth, rate in plans]
    for plan, result in zip(plans, results):
        print(format_report(plan[0], plan[1], result))
        print("")
    fitting = sum(1 for result in results if result[5])
    print("%d of %d planned dives fit a %.0f L tank" % (fitting, len(plans), TANK_CAPACITY))


if __name__ == "__main__":
    main()

