STANDARD_DEPTH_FT = 0.5
CUBIC_FEET_PER_YARD = 27
WASTE_FACTOR = 1.1
BAGS_PER_CUBIC_YARD = 45
BULK_THRESHOLD_BAGS = 100
BAGS_PER_PALLET = 42


def validate_dimension(name, value):
    if not isinstance(value, (int, float)):
        raise TypeError(name + " must be a number")
    if value <= 0:
        raise ValueError(name + " must be greater than zero")
    return float(value)


def surface_area(length, width):
    return length * width


def cubic_feet(area, depth = STANDARD_DEPTH_FT):
    return area * depth


def cubic_yards(volume_ft3):
    return volume_ft3 / CUBIC_FEET_PER_YARD


def adjusted_yards(yards):
    return yards * WASTE_FACTOR


def bags_needed(yards):
    return yards * BAGS_PER_CUBIC_YARD


def is_under_threshold(bags):
    return bags < BULK_THRESHOLD_BAGS


def concrete(length, width):
    safe_length = validate_dimension("length", length)
    safe_width = validate_dimension("width", width)
    area = surface_area(safe_length, safe_width)
    volume_ft3 = cubic_feet(area)
    yards = cubic_yards(volume_ft3)
    padded = adjusted_yards(yards)
    bags = bags_needed(padded)
    under_threshold = is_under_threshold(bags)
    return (area, volume_ft3, yards, bags, under_threshold)


def format_report(length, width):
    area, volume_ft3, yards, bags, under_threshold = concrete(length, width)
    lines = []
    lines.append("Slab: {0:.1f} ft x {1:.1f} ft".format(length, width))
    lines.append("Surface area: {0:.2f} sq ft".format(area))
    lines.append("Volume: {0:.2f} cu ft".format(volume_ft3))
    lines.append("Volume: {0:.3f} cu yd".format(yards))
    lines.append("Bags of cement: {0:.1f}".format(bags))
    if under_threshold:
        delivery = "pickup order (under bulk threshold)"
    else:
        delivery = "bulk delivery recommended"
    lines.append("Delivery: " + delivery)
    return "\n".join(lines)


def pallets_for(bags):
    return bags / BAGS_PER_PALLET


def main():
    jobs = [(10, 12), (40, 60)]
    bag_counts = []
    for length, width in jobs:
        print(format_report(length, width))
        bag_counts.append(concrete(length, width)[3])
        print("-" * 40)
    total_bags = sum(bag_counts)
    print("Total bags for all jobs: {0:.1f}".format(total_bags))
    print("Approximate pallets: {0:.2f}".format(pallets_for(total_bags)))


if __name__ == "__main__":
    main()

