WHEEL_DIAMETER = 27
DEVELOPMENT_FACTOR = 0.08
CADENCE = 90
CRUISING_SPEED = 30
COMPACT_INNER_RING = 34


def validate_teeth(label, teeth):
    if not isinstance(teeth, int):
        raise TypeError(label + " tooth count must be an integer")
    if teeth <= 0:
        raise ValueError(label + " tooth count must be positive")
    return teeth


def gear_ratio(front, rear):
    return front / rear


def gear_inches(ratio):
    return ratio * WHEEL_DIAMETER


def development_meters(inches):
    return inches * DEVELOPMENT_FACTOR


def meters_per_minute(development):
    return development * CADENCE


def meters_per_hour(per_minute):
    return per_minute * 60


def kilometers(meters):
    return meters / 1000


def is_cruising(speed):
    return speed > CRUISING_SPEED


def gearing(chainring, cog):
    front = validate_teeth("chainring", chainring)
    rear = validate_teeth("cog", cog)
    ratio = gear_ratio(front, rear)
    inches = gear_inches(ratio)
    development = development_meters(inches)
    speed = kilometers(meters_per_hour(meters_per_minute(development)))
    return (ratio, inches, development, speed, is_cruising(speed))


def format_gearing(chainring, cog):
    ratio, inches, development, speed, cruising = gearing(chainring, cog)
    verdict = "cruising" if cruising else "spinning"
    return "{}x{}: ratio {:.2f}, {:.1f} gear inches, {:.2f} m/rev, {:.1f} km/h ({})".format(
        chainring, cog, ratio, inches, development, speed, verdict
    )


def build_cassette_report(chainring, cogs):
    return [format_gearing(chainring, cog) for cog in cogs]


def find_cruising_cogs(chainring, cogs):
    return [cog for cog in cogs if gearing(chainring, cog)[4]]


def gap_size(pair):
    small, large = pair
    return large - small


def cog_pairs(cogs):
    ordered = sorted(cogs)
    return list(zip(ordered, ordered[1:]))


def widest_gap(cogs):
    pairs = cog_pairs(cogs)
    if not pairs:
        return 0, None
    pair = max(pairs, key=gap_size)
    return gap_size(pair), pair


def main():
    chainring = 50
    cassette = [11, 13, 15, 17, 19, 21, 24, 28]
    for line in build_cassette_report(chainring, cassette):
        print(line)
    print("Cogs above cruising speed:", find_cruising_cogs(chainring, cassette))
    gap, pair = widest_gap(cassette)
    if pair is not None:
        print("Widest jump is {} teeth between {} and {}".format(gap, pair[0], pair[1]))
    print(format_gearing(COMPACT_INNER_RING, cassette[-1]))


if __name__ == "__main__":
    main()

