text_nat:
TARGET_TEMP_F = 78.0
LITERS_PER_GALLON = 3.78
SPECIFIC_HEAT = 0.2
LOSS_BUFFER = 1.25
SINGLE_HEATER_MAX = 300.0
MIN_AMBIENT = 32.0
MAX_AMBIENT = 110.0


def validate_inputs(gallons, ambient):
    if gallons <= 0:
        raise ValueError("tank volume in gallons must be positive")
    if ambient < MIN_AMBIENT:
        raise ValueError("ambient temperature is below the supported range")
    if ambient > MAX_AMBIENT:
        raise ValueError("ambient temperature is above the supported range")


def liters_from_gallons(gallons):
    return gallons * LITERS_PER_GALLON


def temperature_deficit(ambient):
    return TARGET_TEMP_F - ambient


def specific_load(liters):
    return liters * SPECIFIC_HEAT


def baseline_watts(liters, delta):
    per_degree = specific_load(liters)
    return per_degree * delta


def buffered_watts(baseline):
    return baseline * LOSS_BUFFER


def needs_secondary(buffered):
    return buffered > SINGLE_HEATER_MAX


def watts_per_heater(buffered, count):
    return buffered / count


def aquarium(gallons, ambient):
    validate_inputs(gallons, ambient)
    liters = liters_from_gallons(gallons)
    delta = temperature_deficit(ambient)
    baseline = baseline_watts(liters, delta)
    buffered = buffered_watts(baseline)
    secondary = needs_secondary(buffered)
    return (liters, delta, baseline, buffered, secondary)


def format_report(name, gallons, result):
    liters, delta, baseline, buffered, secondary = result
    count = 2 if secondary else 1
    each = watts_per_heater(buffered, count)
    lines = [f"{name}: {gallons:.0f} gal / {liters:.1f} L"]
    lines.append(f"  temperature deficit: {delta:.1f} F")
    lines.append(f"  baseline demand: {baseline:.1f} W")
    lines.append(f"  with heat-loss buffer: {buffered:.1f} W")
