def total_seconds(minutes):
    return int(round(minutes * 60))


def fractional_part(value):
    return value - int(value)


def format_minutes(minutes):
    whole, seconds = divmod(total_seconds(minutes), 60)
    return "{0}:{1:02d}".format(whole, seconds)


def validate_inputs(distance, goal):
    if distance <= 0:
        raise ValueError("distance must be a positive number of miles")
    if goal <= 0:
        raise ValueError("goal time must be a positive number of minutes")


def minutes_per_mile(goal, distance):
    return goal / distance


def halfway_split(goal):
    return goal / 2


def negative_split_target(half):
    return half - 1.5


def speed_for_pace(per_mile):
    return 60 / per_mile


def beats_threshold(speed):
    return speed > 8.0


def pace(distance, goal):
    validate_inputs(distance, goal)
    per_mile = minutes_per_mile(goal, distance)
    half = halfway_split(goal)
    second_half = negative_split_target(half)
    speed = speed_for_pace(per_mile)
    qualifies = beats_threshold(speed)
    return (per_mile, half, second_half, speed, qualifies)


def split_schedule(distance, goal):
    per_mile = pace(distance, goal)[0]
    schedule = []
    for mile in range(1, int(distance) + 1):
        schedule.append((mile, per_mile * mile))
    if fractional_part(distance) > 0:
        schedule.append((distance, per_mile * distance))
    return schedule


def report(distance, goal):
    per_mile, half, second_half, speed, qualifies = pace(distance, goal)
    lines = []
    lines.append("Race: {0} miles in {1}".format(distance, format_minutes(goal)))
    lines.append("Average pace: {0} per mile".format(format_minutes(per_mile)))
    lines.append("Halfway split: {0}".format(format_minutes(half)))
    lines.append("Negative split target: {0}".format(format_minutes(second_half)))
    lines.append("Required speed: {0:.2f} mph".format(speed))
    if qualifies:
        verdict = "above the 8 mph qualifying threshold"
    else:
        verdict = "below the 8 mph qualifying threshold"
    lines.append("Status: {0}".format(verdict))
    for mile, elapsed in split_schedule(distance, goal):
        lines.append("  mile {0}: {1}".format(mile, format_minutes(elapsed)))
    return "\n".join(lines)


def main():
    races = [(5.0, 35.0), (13.1, 100.0), (26.2, 240.0)]
    fastest = None
    for distance, goal in races:
        print(report(distance, goal))
        print("")
        speed = pace(distance, goal)[3]
        if fastest is None or speed > fastest[1]:
            fastest = (distance, speed)
    print("Fastest planned effort: {0} miles at {1:.2f} mph".format(fastest[0], fastest[1]))


if __name__ == "__main__":
    main()

