CROP_COEFFICIENT = 1.2
AVERAGE_RAINFALL = 0.1
GALLONS_PER_ACRE_INCH = 27154
PUMP_FLOW_GPH = 500.0
DAYLIGHT_LIMIT_HOURS = 12.0


def validate_inputs(area, loss):
    if area <= 0:
        raise ValueError("area must be a positive number of acres")
    if loss < 0:
        raise ValueError("daily water loss cannot be negative")
    return float(area), float(loss)


def gross_requirement(loss):
    return loss * CROP_COEFFICIENT


def net_depth(loss):
    return gross_requirement(loss) - AVERAGE_RAINFALL


def acre_inches(area, depth):
    return area * depth


def to_gallons(volume):
    return volume * GALLONS_PER_ACRE_INCH


def run_time_hours(gallons):
    return gallons / PUMP_FLOW_GPH


def fits_daylight(hours):
    return hours < DAYLIGHT_LIMIT_HOURS


def daylight_overrun(hours):
    return hours - DAYLIGHT_LIMIT_HOURS


def irrigation(area, loss):
    acres, daily_loss = validate_inputs(area, loss)
    depth = net_depth(daily_loss)
    volume = acre_inches(acres, depth)
    gallons = to_gallons(volume)
    hours = run_time_hours(gallons)
    within_daylight = fits_daylight(hours)
    return (depth, volume, gallons, hours, within_daylight)


