MM_PER_INCH = 25.4
WHEEL_DIAMETER = 18
PI = 3.1415
INCHES_PER_MILE = 63360
FACTORY_LIMIT = 800


def validate(width, aspect):
    if width <= 0:
        raise ValueError("width must be a positive number of millimeters")
    if aspect <= 0:
        raise ValueError("aspect ratio must be a positive percentage")
    if aspect > 100:
        raise ValueError("aspect ratio above 100 percent is not a tire size")


def scale_percent(value, percent):
    return value * percent


def sidewall_mm(width, aspect):
    return scale_percent(width, aspect) / 100


def to_inches(millimeters):
    return millimeters / MM_PER_INCH


def stacked_sidewalls(sidewall):
    return sidewall * 2


def diameter_inches(sidewall):
    return stacked_sidewalls(sidewall) + WHEEL_DIAMETER


def circumference_inches(diameter):
    return diameter * PI


def revolutions_per_mile(circumference):
    return INCHES_PER_MILE / circumference


def within_factory_limit(revolutions):
    return revolutions < FACTORY_LIMIT


def tires(width, aspect):
    validate(width, aspect)
    sidewall = to_inches(sidewall_mm(width, aspect))
    diameter = diameter_inches(sidewall)
    circumference = circumference_inches(diameter)
    revolutions = revolutions_per_mile(circumference)
    legal = within_factory_limit(revolutions)
    return (sidewall, diameter, circumference, revolutions, legal)


def diameter_delta(diameter, reference):
    return diameter - reference


def fraction_of(part, whole):
    return part / whole


def format_report(width, aspect, result):
    sidewall, diameter, circumference, revolutions, legal = result
    if legal:
        status = "within factory limit"
    else:
        status = "over factory limit"
    lines = [f"Tire {width}/{aspect}R{WHEEL_DIAMETER}"]
    lines.append(f"  sidewall:      {sidewall:.3f} in")
    lines.append(f"  diameter:      {diameter:.3f} in")
    lines.append(f"  circumference: {circumference:.3f} in")
    lines.append(f"  revs/mile:     {revolutions:.1f} ({status})")
    return "\n".join(lines)


def main():
    sizes = [(275, 60), (285, 55), (305, 30), (235, 75)]
    reference = tires(*sizes[0])[1]
    for width, aspect in sizes:
        result = tires(width, aspect)
        print(format_report(width, aspect, result))
        delta = diameter_delta(result[1], reference)
        drift = fraction_of(delta, reference)
        print(f"  speedometer drift vs {sizes[0][0]}/{sizes[0][1]}: {drift * 100:+.2f}%")


if __name__ == "__main__":
    main()

