import math

SALT_GRAMS = 10
YEAST_GRAMS = 5
TARGET_DOUGH = 2000
BOWL_CAPACITY = 1200


def validate(flour, hydration):
    if flour <= 0:
        raise ValueError("flour weight must be a positive number of grams")
    if hydration <= 0:
        raise ValueError("hydration must be a positive percentage")
    if int(hydration) != hydration:
        raise ValueError("hydration must be given as a whole number")


def hydration_fraction(hydration):
    return hydration / 100


def water_weight(flour, hydration):
    return flour * hydration_fraction(hydration)


def extras_weight():
    return SALT_GRAMS + YEAST_GRAMS


def dough_weight(flour, water):
    return flour + water


def total_weight(flour, water):
    return dough_weight(flour, water) + extras_weight()


def scaling_factor(total):
    return TARGET_DOUGH / total


def scaled(weight, factor):
    return weight * factor


def exceeds_bowl(new_flour):
    return new_flour > BOWL_CAPACITY


def excess_over_bowl(new_flour):
    return new_flour - BOWL_CAPACITY


def bowl_headroom(new_flour):
    return BOWL_CAPACITY - new_flour


def batches_needed(new_flour):
    return math.ceil(new_flour / BOWL_CAPACITY)


def scale(flour, hydration):
    validate(flour, hydration)
    water = water_weight(flour, hydration)
    total = total_weight(flour, water)
    factor = scaling_factor(total)
    new_flour = scaled(flour, factor)
    new_water = scaled(water, factor)
