LOW_THRESHOLD = 50000.0
LOW_RATE = 0.1
HIGH_RATE = 0.2
TARGET_RATE = 0.15


def validate(income, deduction):
    """Reject inputs that would make the tax arithmetic meaningless."""
    if income <= 0:
        raise ValueError("gross income must be positive")
    if deduction < 0:
        raise ValueError("deduction cannot be negative")
    if deduction > income:
        raise ValueError("deduction cannot exceed gross income")


def taxable_amount(income, deduction):
    return income - deduction


def base_tax():
    return LOW_THRESHOLD * LOW_RATE


def remaining_amount(taxable):
    return taxable - LOW_THRESHOLD


def excess_tax(remaining):
    return remaining * HIGH_RATE


def total_tax(base, excess):
    return base + excess


def effective_rate(total, income):
    return total / income


def below_target(rate):
    return rate < TARGET_RATE


def as_percent(rate):
    return rate * 100


def rate_spread(rates):
    return max(rates) - min(rates)


def taxes(income, deduction):
    validate(income, deduction)
    taxable = taxable_amount(income, deduction)
    remaining = remaining_amount(taxable)
    total = total_tax(base_tax(), excess_tax(remaining))
    effective = effective_rate(total, income)
    under_target = below_target(effective)
    return (taxable, remaining, total, effective, under_target)


def format_report(income, deduction, result):
    taxable, remaining, total, effective, under_target = result
    verdict = "below" if under_target else "at or above"
    lines = [
        "Gross income:      {:>12,.2f}".format(income),
        "Deduction:         {:>12,.2f}".format(deduction),
        "Taxable income:    {:>12,.2f}".format(taxable),
        "Above threshold:   {:>12,.2f}".format(remaining),
        "Total tax:         {:>12,.2f}".format(total),
        "Effective rate:    {:>11,.2f}%".format(as_percent(effective)),
        "Rate is {} the {:.0f}% target".format(verdict, as_percent(TARGET_RATE)),
    ]
    return "\n".join(lines)


def main():
    cases = [(120000.0, 13850.0), (75000.0, 13850.0), (250000.0, 27700.0)]
    burdens = []
    for income, deduction in cases:
        result = taxes(income, deduction)
        print(format_report(income, deduction, result))
        print("-" * 40)
        burdens.append(result[3])
    spread = rate_spread(burdens)
    print("Effective rate spread: {:.2f} points".format(as_percent(spread)))


if __name__ == "__main__":
    main()

