BASE_BTU_PER_SQFT = 30
BTU_PER_OCCUPANT = 400
WINDOW_AREA = 50
SOLAR_FACTOR = 20
PORTABLE_UNIT_RATING = 8000


def validate_inputs(area, occupants):
    if area <= 0:
        raise ValueError("area must be a positive number of square feet")
    if occupants < 0:
        raise ValueError("occupants must not be negative")
    return float(area), int(occupants)


def base_cooling_load(area):
    return area * BASE_BTU_PER_SQFT


def occupant_cooling_load(occupants):
    return occupants * BTU_PER_OCCUPANT


def solar_heat_gain():
    return WINDOW_AREA * SOLAR_FACTOR


def hvac(area, occupants):
    area, occupants = validate_inputs(area, occupants)
    base_load = base_cooling_load(area)
    occupant_load = occupant_cooling_load(occupants)
    subtotal = base_load + occupant_load
    solar_gain = solar_heat_gain()
    total_required = subtotal + solar_gain
    portable_is_enough = total_required < PORTABLE_UNIT_RATING
    return (base_load, occupant_load, subtotal, total_required, portable_is_enough)


def format_report(area, occupants, result):
    base_load, occupant_load, subtotal, total_required, portable_is_enough = result
    lines = []
    lines.append("Room: {:.0f} sq ft, {} occupants".format(area, occupants))
    lines.append("  Base cooling load:   {:>8.0f} BTU".format(base_load))
    lines.append("  Occupant load:       {:>8.0f} BTU".format(occupant_load))
    lines.append("  Subtotal:            {:>8.0f} BTU".format(subtotal))
    lines.append("  Solar heat gain:     {:>8.0f} BTU".format(solar_heat_gain()))
    lines.append("  Total required:      {:>8.0f} BTU".format(total_required))
    if portable_is_enough:
        headroom = PORTABLE_UNIT_RATING - total_required
        verdict = "portable unit suffices ({:.0f} BTU spare)".format(headroom)
    else:
        shortfall = total_required - PORTABLE_UNIT_RATING
        verdict = "needs {:.0f} BTU more than a portable unit".format(shortfall)
    lines.append("  Verdict: " + verdict)
    return "\n".join(lines)


def main():
    rooms = [(150, 2), (220, 3), (400, 6)]
    undersized = 0
    for area, occupants in rooms:
        result = hvac(area, occupants)
        print(format_report(area, occupants, result))
        if not result[4]:
            undersized = undersized + 1
        print()
    print("Rooms needing more than a portable unit: {} of {}".format(undersized, len(rooms)))


if __name__ == "__main__":
    main()

