PI = 3.14
AIR_DENSITY = 1.2
TURBINE_EFFICIENCY = 0.4
GENERATOR_EFFICIENCY = 0.9
GRID_THRESHOLD = 5000.0


def validate(speed, radius):
    if speed < 0:
        raise ValueError("wind speed cannot be negative")
    if radius <= 0:
        raise ValueError("blade radius must be positive")


def square_of(value):
    return value * value


def cube_of(value):
    square = square_of(value)
    return square * value


def half(value):
    return value / 2


def swept_area(radius):
    square = square_of(radius)
    return PI * square


def kinetic_flux(speed):
    cubed = cube_of(speed)
    return AIR_DENSITY * cubed


def power_potential(area, speed):
    flux = kinetic_flux(speed)
    return half(area * flux)


def mechanical_power(potential):
    return potential * TURBINE_EFFICIENCY


def electrical_power(mechanical):
    return mechanical * GENERATOR_EFFICIENCY


def above_threshold(electrical):
    return electrical > GRID_THRESHOLD


def turbine(speed, radius):
    validate(speed, radius)
    area = swept_area(radius)
    potential = power_potential(area, speed)
    mechanical = mechanical_power(potential)
    electrical = electrical_power(mechanical)
    grid_ready = above_threshold(electrical)
    return (area, potential, mechanical, electrical, grid_ready)


def format_report(speed, radius, result):
    area, potential, mechanical, electrical, grid_ready = result
    status = "connectable" if grid_ready else "below threshold"
    lines = ["{0:.1f} m/s wind on {1:.1f} m blades".format(speed, radius)]
    lines.append("  swept area        : {0:.2f} m2".format(area))
    lines.append("  wind potential    : {0:.1f} W".format(potential))
    lines.append("  mechanical power  : {0:.1f} W".format(mechanical))
    lines.append("  electrical output : {0:.1f} W".format(electrical))
    lines.append("  grid status       : {0}".format(status))
    lines.append("  threshold ratio   : {0:.2f}".format(electrical / GRID_THRESHOLD))
    return "\n".join(lines)


def main():
    farm = [(4.0, 3.0), (8.5, 10.0), (12.0, 25.0)]
    connected = 0
    total_output = 0.0
    for speed, radius in farm:
        result = turbine(speed, radius)
        print(format_report(speed, radius, result))
        total_output += result[3]
        if result[4]:
            connected += 1
    print("turbines above threshold: {0} of {1}".format(connected, len(farm)))
    print("average output: {0:.1f} W".format(total_output / len(farm)))


if __name__ == "__main__":
    main()

