NEAR_LIMIT_FACTOR = 0.3
RECHARGE_FACTOR = 0.5
RAPID_FIRE_LIMIT = 2.0


def validate_inputs(guide, aperture):
    if guide <= 0:
        raise ValueError("guide number must be positive")
    if aperture <= 0:
        raise ValueError("aperture must be positive")


def max_distance(guide, aperture):
    return guide / aperture


def near_limit(maximum):
    return maximum * NEAR_LIMIT_FACTOR


def flash_depth(maximum, near):
    return maximum - near


def recycle_time(maximum):
    return maximum * RECHARGE_FACTOR


def is_rapid_fire(recycle):
    return recycle < RAPID_FIRE_LIMIT


def flash(guide, aperture):
    validate_inputs(guide, aperture)
    maximum = max_distance(guide, aperture)
    near = near_limit(maximum)
    depth = flash_depth(maximum, near)
    recycle = recycle_time(maximum)
    rapid = is_rapid_fire(recycle)
    return (maximum, near, depth, recycle, rapid)


def format_report(guide, aperture, result):
    maximum, near, depth, recycle, rapid = result
    mode = "rapid fire" if rapid else "slow recharge"
    lines = []
    lines.append("Guide number {0} at f/{1}".format(guide, aperture))
    lines.append("  maximum subject distance : {0:.2f} m".format(maximum))
    lines.append("  near distance limit      : {0:.2f} m".format(near))
    lines.append("  depth of flash range     : {0:.2f} m".format(depth))
    lines.append("  recycle time             : {0:.2f} s".format(recycle))
    lines.append("  shooting mode            : " + mode)
    return "\n".join(lines)


def main():
    setups = [(32, 8), (45, 5.6), (11, 2.8), (56, 11)]
    results = []
    for guide, aperture in setups:
        result = flash(guide, aperture)
        print(format_report(guide, aperture, result))
        results.append(result)
    rapid_count = sum(1 for item in results if item[4])
    widest = max(results, key=lambda item: item[2])
    print("Setups usable for rapid fire: {0}/{1}".format(rapid_count, len(setups)))
    print("Widest flash range depth: {0:.2f} m".format(widest[2]))


if __name__ == "__main__":
    main()

