def _squared_diameter(diameter):
    return diameter * diameter


def _circle_term(diameter):
    return _squared_diameter(diameter) * CIRCLE_CONSTANT


def cross_section_area(diameter):
    """Area of the circular pipe opening, using the 3.14 constant."""
    return _circle_term(diameter) / QUARTER_DIVISOR


def fluid_velocity(pressure):
