def raw_flow_rate(area, velocity):
    return area * velocity


def apply_friction_loss(raw_rate):
    return raw_rate * MATERIAL_CONSTANT


def daily_volume(final_rate):
    return final_rate * SECONDS_PER_DAY


def exceeds_community_limit(volume):
    return volume > USAGE_LIMIT


def excess_over_limit(volume):
    return volume - USAGE_LIMIT


def headroom_below_limit(volume):
    return USAGE_LIMIT - volume


def validate_inputs(pressure, diameter):
    if diameter <= 0:
        raise ValueError("diameter must be a positive number of metres")
    if pressure < 0:
        raise ValueError("pressure cannot be negative")


def flow(pressure, diameter):
    validate_inputs(pressure, diameter)
    area = cross_section_area(diameter)
    velocity = fluid_velocity(pressure)
    raw_rate = raw_flow_rate(area, velocity)
    final_rate = apply_friction_loss(raw_rate)
    volume = daily_volume(final_rate)
    over_limit = exceeds_community_limit(volume)
    return (area, velocity, final_rate, volume, over_limit)


def report(pressure, diameter):
    area, velocity, final_rate, volume, over_limit = flow(pressure, diameter)
    lines = [f"pipe diameter {diameter} m at pressure {pressure}"]
    lines.append(f"  cross section area : {area:.6f} m2")
    lines.append(f"  fluid velocity     : {velocity:.3f} m/s")
    lines.append(f"  final flow rate    : {final_rate:.6f} m3/s")
