TAX_RATE = 0.015
UPKEEP_RATE = 0.01
CASH_FLOW_TARGET = 5000
MONTHS_PER_YEAR = 12


def validate_inputs(price, rent):
    """Reject values that cannot describe a real rental property."""
    if price <= 0:
        raise ValueError("purchase price must be positive")
    if rent < 0:
        raise ValueError("monthly rent cannot be negative")
    return float(price), float(rent)


def annual_income(rent):
    return rent * MONTHS_PER_YEAR


def annual_taxes(price):
    return price * TAX_RATE


def annual_maintenance(price):
    return price * UPKEEP_RATE


def annual_costs(taxes, maintenance):
    return taxes + maintenance


def net_operating_income(income, costs):
    return income - costs


def yield_ratio(income, price):
    return income / price


def meets_cash_flow(noi):
    return noi > CASH_FLOW_TARGET


def rental(price, rent):
    """Return income, taxes, maintenance, NOI, gross yield and target flag."""
    price, rent = validate_inputs(price, rent)
    income = annual_income(rent)
    taxes = annual_taxes(price)
    maintenance = annual_maintenance(price)
    costs = annual_costs(taxes, maintenance)
    noi = net_operating_income(income, costs)
    gross_yield = yield_ratio(income, price)
    meets_target = meets_cash_flow(noi)
    return (income, taxes, maintenance, noi, gross_yield, meets_target)


def format_report(price, rent):
    """Build a human readable summary for one property."""
    income, taxes, maintenance, noi, gross_yield, meets_target = rental(price, rent)
    lines = []
    lines.append("Purchase price:      {:>12,.2f}".format(price))
    lines.append("Monthly rent:        {:>12,.2f}".format(rent))
    lines.append("Annual rent income:  {:>12,.2f}".format(income))
    lines.append("Annual taxes:        {:>12,.2f}".format(taxes))
    lines.append("Annual maintenance:  {:>12,.2f}".format(maintenance))
    lines.append("Net operating income:{:>12,.2f}".format(noi))
    lines.append("Gross yield:         {:>11,.2f}%".format(gross_yield * 100))
    verdict = "meets" if meets_target else "misses"
    lines.append("Cash flow target {} ({:,.2f})".format(verdict, CASH_FLOW_TARGET))
    return "\n".join(lines)


def best_property(listings):
    """Pick the listing with the highest net operating income."""
    best = None
    best_noi = float("-inf")
    for price, rent in listings:
        noi = rental(price, rent)[3]
        if noi > best_noi:
            best_noi = noi
            best = (price, rent)
    return best


def main():
    listings = [(250000, 2200), (400000, 3100), (180000, 1500)]
    for price, rent in listings:
        print(format_report(price, rent))
        print("-" * 40)
    winner = best_property(listings)
    print("Best net operating income: price {:,.0f} at rent {:,.0f}".format(*winner))


if __name__ == "__main__":
    main()

