import math

BAG_NITROGEN = 10
BAG_PHOSPHORUS = 5
BAG_POTASSIUM = 5
BAG_WEIGHT = 50
PAYLOAD_LIMIT = 2000


def validate_inputs(nitrogen, area):
    if nitrogen < 0:
        raise ValueError("target nitrogen rate cannot be negative")
    if area <= 0:
        raise ValueError("field area must be positive")
    return float(nitrogen), float(area)


def fertilizer(nitrogen, area):
    rate, acres = validate_inputs(nitrogen, area)
    total_nitrogen = (
        rate * acres
    )
    bags_needed = (
        total_nitrogen / BAG_NITROGEN
    )
    phosphorus = (
        bags_needed * BAG_PHOSPHORUS
    )
    potassium = (
        bags_needed * BAG_POTASSIUM
    )
    total_weight = (
        bags_needed * BAG_WEIGHT
    )
    within_payload = (
        total_weight < PAYLOAD_LIMIT
    )
    return (total_nitrogen, bags_needed, phosphorus, potassium,
            total_weight, within_payload)


def trips_required(total_weight):
    return math.ceil(
        total_weight / PAYLOAD_LIMIT
    )


def format_report(nitrogen, area):
    total_n, bags, phos, potash, weight, ok = fertilizer(nitrogen, area)
    lines = [
        "Total nitrogen: {:.1f} lb".format(total_n),
        "Bags needed: {:.2f}".format(bags),
        "Phosphorus applied: {:.1f} lb".format(phos),
        "Potassium applied: {:.1f} lb".format(potash),
        "Total product weight: {:.1f} lb".format(weight),
    ]
    if ok:
        lines.append("Fits tractor payload: yes (1 trip)")
    else:
        trips = trips_required(weight)
        lines.append("Fits tractor payload: no ({} trips)".format(trips))
    return "\n".join(lines)


def main():
    plans = [(120.0, 2.5), (150.0, 8.0), (80.0, 40.0)]
    grand_total = 0.0
    for target, acres in plans:
        print("Plan: {:.1f} lb N/acre on {:.1f} acres".format(target, acres))
        print(format_report(target, acres))
        weight = fertilizer(target, acres)[4]
        grand_total = (
            grand_total + weight
        )
        print("-" * 34)
    print("Combined product weight: {:.1f} lb".format(grand_total))


if __name__ == "__main__":
    main()

