def reciprocal(value):
    return 1.0 / value


def refractivity(index):
    return index - 1.0


def curvature(front, back):
    return reciprocal(front) - reciprocal(back)


def inverse_focal_length(front, back, index):
    return refractivity(index) * curvature(front, back)


def diopters(focal):
    return 1000.0 / focal


def validate(parameters):
    if len(parameters) != 3:
        raise ValueError("expected three values: front radius, back radius, index")
    front = float(parameters[0])
    back = float(parameters[1])
    index = float(parameters[2])
    if front == 0.0:
        raise ValueError("front radius of curvature must be non-zero")
    if back == 0.0:
        raise ValueError("back radius of curvature must be non-zero")
    if index <= 1.0:
        raise ValueError("refractive index must be greater than one")
    return front, back, index


def optics(parameters):
    front, back, index = validate(parameters)
    inverse = inverse_focal_length(front, back, index)
    if inverse == 0.0:
        raise ValueError("lens has no optical effect")
    focal = reciprocal(inverse)
    power = diopters(focal)
    if focal > 0.0:
        kind = "converging"
    else:
        kind = "diverging"
    return round(focal, 1), round(power, 2), kind


def classify_shape(front, back):
    if front > 0.0:
        if back < 0.0:
            return "biconvex"
        return "meniscus"
    if back > 0.0:
        return "biconcave"
    return "meniscus"


def describe(parameters):
    focal, power, kind = optics(parameters)
    shape = classify_shape(float(parameters[0]), float(parameters[1]))
    template = "{0} {1}: focal {2:.1f} mm, power {3:.2f} D"
    return template.format(shape, kind, focal, power)


def strongest(lenses):
    best = lenses[0]
    for lens in lenses:
        if abs(optics(lens)[1]) > abs(optics(best)[1]):
            best = lens
    return best


def main():
    lenses = [
        [10.0, -15.0, 1.5],
        [-20.0, 20.0, 1.52],
        [50.0, 100.0, 1.6],
        [25.0, -25.0, 1.7],
    ]
    for lens in lenses:
        print(describe(lens))
    print("strongest lens is the " + describe(strongest(lenses)))
    total = sum(optics(lens)[1] for lens in lenses)
    print("stacked power {0:.2f} D".format(total))


if __name__ == "__main__":
    main()

