import math


G0 = 9.8
ORBITAL_THRESHOLD = 9300


def initial_mass(empty_mass, propellant_mass):
    """Mass of a loaded stage before its engine fires."""
    return empty_mass + propellant_mass


def mass_ratio(empty_mass, propellant_mass):
    """Loaded mass divided by burnt-out mass."""
    return initial_mass(empty_mass, propellant_mass) / empty_mass


def exhaust_velocity(specific_impulse):
    """Effective exhaust velocity in metres per second."""
    return specific_impulse * G0


def validate_stage(stage, index):
    """Check one stage description and return its three numbers."""
    if len(stage) != 3:
        raise ValueError("stage {} must have exactly three values".format(index))
    empty_mass = float(stage[0])
    propellant_mass = float(stage[1])
    specific_impulse = float(stage[2])
    if empty_mass <= 0:
        raise ValueError("stage {} has a non-positive empty mass".format(index))
    if propellant_mass < 0:
        raise ValueError("stage {} has a negative propellant mass".format(index))
    if specific_impulse <= 0:
        raise ValueError("stage {} has a non-positive specific impulse".format(index))
    return empty_mass, propellant_mass, specific_impulse


def stage_delta_v(empty_mass, propellant_mass, specific_impulse):
    """Tsiolkovsky velocity change of a single stage."""
    return exhaust_velocity(specific_impulse) * math.log(mass_ratio(empty_mass, propellant_mass))


def stage_table(stages):
    """Build one (number, mass ratio, delta-v) triple per stage."""
    rows = []
    for number, stage in enumerate(stages, 1):
        empty_mass, propellant_mass, specific_impulse = validate_stage(stage, number)
        ratio = mass_ratio(empty_mass, propellant_mass)
        delta_v = stage_delta_v(empty_mass, propellant_mass, specific_impulse)
        rows.append((number, ratio, delta_v))
    return rows


def propulsion(stages):
    """Total velocity change of a vehicle and its orbital classification."""
    total_delta_v = math.fsum(row[2] for row in stage_table(stages))
    if total_delta_v > ORBITAL_THRESHOLD:
        classification = "orbital"
    else:
        classification = "suborbital"
    return [round(total_delta_v), classification]


def orbital_margin(stages):
    """How far the vehicle's capability sits above the orbital threshold."""
    return propulsion(stages)[0] - ORBITAL_THRESHOLD


def format_report(stages):
    """Human readable summary of a vehicle's staging performance."""
    lines = []
    for number, ratio, delta_v in stage_table(stages):
        lines.append("stage {}: ratio {:.2f}, dv {:.0f} m/s".format(number, ratio, delta_v))
    total, classification = propulsion(stages)
    lines.append("total dv {} m/s -> {}".format(total, classification))
    return "\n".join(lines)


def main():
    single = [[1000, 9000, 300]]
    two_stage = [[2000, 30000, 290], [500, 6000, 340]]
    print(propulsion(single))
    print(format_report(single))
    print(format_report(two_stage))
    print("two-stage margin over threshold: {} m/s".format(orbital_margin(two_stage)))


if __name__ == "__main__":
    main()

