    return rows


def propulsion(stages):
    """Total velocity change of a vehicle and its orbital classification."""
    total_delta_v=math.fsum(row[2] for row in stage_table(stages))
    if total_delta_v>ORBITAL_THRESHOLD:
        classification="orbital"
    else:
        classification="suborbital"
    return [round(total_delta_v), classification]


def orbital_margin(stages):
    """How far the vehicle's capability sits above the orbital threshold."""
    return propulsion(stages)[0]-ORBITAL_THRESHOLD


def format_report(stages):
    """Human readable summary of a vehicle's staging performance."""
    lines=[]
    for number, ratio, delta_v in stage_table(stages):
        lines.append("stage {}: ratio {:.2f}, dv {:.0f} m/s".format(number, ratio, delta_v))
    total, classification=propulsion(stages)
    lines.append("total dv {} m/s -> {}".format(total, classification))
    return "\n".join(lines)


def main():
    single=[[1000, 9000, 300]]
    two_stage=[[2000, 30000, 290], [500, 6000, 340]]
    print(propulsion(single))
    print(format_report(single))
    print(format_report(two_stage))
    print("two-stage margin over threshold: {} m/s".format(orbital_margin(two_stage)))


if __name__=="__main__":
    main()

