"""Depth-of-field calculations for a single lens, all distances in millimetres."""

import math

FIELD_NAMES = ("focal length", "aperture", "subject distance", "circle of confusion")


def _focal_squared(focal):
    return focal * focal


def _blur_budget(aperture, coc):
    return aperture * coc


def _subject_offset(distance, focal):
    return distance - focal


def _focus_product(hyper, distance):
    return hyper * distance


def _lens_term(focal, aperture, coc):
    return _focal_squared(focal) / _blur_budget(aperture, coc)


def _hyperfocal_distance(focal, aperture, coc):
    return focal + _lens_term(focal, aperture, coc)


def _near_denominator(hyper, distance, focal):
    return hyper + _subject_offset(distance, focal)


def _far_denominator(hyper, distance, focal):
    return hyper - _subject_offset(distance, focal)


def _near_limit(hyper, distance, focal):
    denominator = _near_denominator(hyper, distance, focal)
    return _focus_product(hyper, distance) / denominator


def _far_limit(hyper, distance, focal):
    denominator = _far_denominator(hyper, distance, focal)
    if denominator <= 0:
        return math.inf
    return _focus_product(hyper, distance) / denominator


def _depth_of_field(near, far):
    return far - near


def _validate(settings):
    values = tuple(settings)
    if len(values) != 4:
        raise ValueError("hyperfocal() needs exactly four numbers")
    for name, value in zip(FIELD_NAMES, values):
        if value <= 0:
            raise ValueError(f"the {name} must be positive")
    return values


def hyperfocal(settings):
    focal, aperture, distance, coc = _validate(settings)
    hyper = _hyperfocal_distance(focal, aperture, coc)
    near = _near_limit(hyper, distance, focal)
    far = _far_limit(hyper, distance, focal)
    return round(hyper, 1), round(near, 1), round(far, 1)


def format_report(settings):
    focal, aperture, distance, coc = settings
    hyper, near, far = hyperfocal(settings)
    if far == math.inf:
        depth = "infinite"
    else:
        depth = f"{_depth_of_field(near, far):.1f} mm"
    header = f"{focal} mm at f/{aperture}, subject {distance} mm, CoC {coc} mm"
    body = f"  hyperfocal {hyper} | near {near} | far {far} | depth {depth}"
    return f"{header}\n{body}"


def main():
    setups = [(50, 8, 5000, 0.03), (135, 2.8, 12000, 0.02), (50, 8, 20000, 0.03)]
    for settings in setups:
        print(format_report(settings))


if __name__ == "__main__":
    main()

