LABELS = ("cab mass", "capacity mass", "cable mass", "suspension ratio")


def _to_float(value, label):
    """Convert one specification entry to a non-negative float."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise ValueError("%s must be numeric" % label)
    if number < 0:
        raise ValueError("%s cannot be negative" % label)
    return number


def _parse_specs(specs):
    """Return the four validated numbers described by the specs sequence."""
    values = list(specs)
    if len(values) != 4:
        raise ValueError("expected four specifications: %s" % ", ".join(LABELS))
    numbers = [_to_float(value, label) for value, label in zip(values, LABELS)]
    if numbers[3] <= 0:
        raise ValueError("suspension ratio must be positive")
    return numbers


def _half_capacity(capacity):
    """Half of the passenger capacity balances out on the counterweight."""
    return capacity / 2.0


def _counterweight(cab, capacity):
    """Ideal counterweight: the cab plus half of the passenger capacity."""
    return cab + _half_capacity(capacity)


def _empty_side_mass(cab, cable):
    """Mass hanging on the cab side with no passengers aboard."""
    return cab + cable


def _loaded_side_mass(cab, capacity, cable):
    """Mass hanging on the cab side with the cab fully loaded."""
    return capacity + _empty_side_mass(cab, cable)


def _net_mass(hanging_mass, counterweight):
    """Imbalance between the cab side and the counterweight side."""
    return hanging_mass - counterweight


def _motor_load(hanging_mass, counterweight, ratio):
    """Load seen by the motor for a given mass hanging on the cab side."""
    return _net_mass(hanging_mass, counterweight) / ratio


def _load_span(top, bottom):
    """Range the motor has to cover between its extreme loads."""
    return top - bottom


def elevator(specs):
    """Counterweight mass, maximum and minimum motor load, each to 0.1 kg."""
    cab, capacity, cable, ratio = _parse_specs(specs)
    counterweight = _counterweight(cab, capacity)
    empty_side = _empty_side_mass(cab, cable)
    loaded_side = _loaded_side_mass(cab, capacity, cable)
    top = _motor_load(loaded_side, counterweight, ratio)
    bottom = _motor_load(empty_side, counterweight, ratio)
    return [round(counterweight, 1), round(top, 1), round(bottom, 1)]


def format_report(name, specs):
    """Human readable summary of one elevator installation."""
    counterweight, top, bottom = elevator(specs)
    span = _load_span(top, bottom)
    lines = [name]
    lines.append("  counterweight:   %.1f kg" % counterweight)
    lines.append("  max motor load:  %.1f kg" % top)
    lines.append("  min motor load:  %.1f kg" % bottom)
    lines.append("  load span:       %.1f kg" % span)
    if top >= abs(bottom):
        lines.append("  sizing case:     lifting a fully loaded cab")
    else:
        lines.append("  sizing case:     lifting an empty cab")
    return "\n".join(lines)


def main():
    fleet = [
        ("Passenger lift A", (1000, 800, 100, 2)),
        ("Freight lift B", (2400, 2000, 260, 4)),
    ]
    for name, specs in fleet:
        print(format_report(name, specs))
        print("")


if __name__ == "__main__":
    main()

