import math

def validate_dimensions(dimensions):
    if len(dimensions) != 4:
        raise ValueError("expected length, width, roll width and pattern repeat")
    length, width, roll_width, repeat = (float(value) for value in dimensions)
    if length <= 0 or width <= 0:
        raise ValueError("room dimensions must be positive")
    if roll_width <= 0:
        raise ValueError("carpet roll width must be positive")
    if repeat < 0:
        raise ValueError("pattern repeat cannot be negative")
    return length, width, roll_width, repeat

def strip_count(width, roll_width):
    return math.ceil(width / roll_width)

def flooring(dimensions):
    length, width, roll_width, repeat = validate_dimensions(dimensions)
    strips = strip_count(width, roll_width)
    strip_length = length + repeat
    linear_meters = strip_length * strips
    purchased_area = linear_meters * roll_width
    room_area = length * width
    waste = purchased_area - room_area
    return [strips, linear_meters, round(waste, 2)]

def waste_fraction(dimensions):
    length, width = validate_dimensions(dimensions)[:2]
    room_area = length * width
    waste = flooring(dimensions)[2]
    return waste / room_area

def describe(name, dimensions):
    strips, linear_meters, waste = flooring(dimensions)
    fraction = waste_fraction(dimensions) * 100
    verdict = "efficient"
    if fraction > 50:
        verdict = "very wasteful"
    elif fraction > 20:
        verdict = "wasteful"
    lines = [
        "Room: " + name,
        "  strips needed:   {0}".format(strips),
        "  linear meters:   {0:.2f} m".format(linear_meters),
        "  waste area:      {0:.2f} m2".format(waste),
        "  waste fraction:  {0:.1f}% ({1})".format(fraction, verdict),
    ]
    return "\n".join(lines)

def cheapest_roll(dimensions, roll_widths, price_per_linear_meter):
    length, width, _ignored, repeat = validate_dimensions(dimensions)
    best = None
    for roll_width in roll_widths:
        option = [length, width, roll_width, repeat]
        linear_meters = flooring(option)[1]
        cost = linear_meters * price_per_linear_meter * roll_width
        if best is None or cost < best[1]:
            best = (roll_width, cost)
    if best is None:
        raise ValueError("no roll widths supplied")
    return best

def main():
    rooms = [
        ("lounge", [5.0, 4.0, 4.0, 1.0]),
        ("hallway", [9.0, 1.2, 3.66, 0.5]),
        ("bedroom", [4.2, 3.8, 2.0, 0.25]),
    ]
    for name, dimensions in rooms:
        print(describe(name, dimensions))
        print()
    widths = [2.0, 3.66, 4.0]
    price = 18.5
    for name, dimensions in rooms:
        roll_width, cost = cheapest_roll(dimensions, widths, price)
        print("{0}: cheapest roll {1} m wide at {2:.2f}".format(name, roll_width, cost))

if __name__ == "__main__":
    main()

