import math


def parse_specs(specs):
    if isinstance(specs, dict):
        keys = ("horizontal", "rise", "speed", "spacing", "passengers")
        values = [specs[key] for key in keys]
    else:
        values = list(specs)
    if len(values) != 5:
        raise ValueError("specs must provide exactly five values")
    horizontal = float(values[0])
    rise = float(values[1])
    speed = float(values[2])
    spacing = float(values[3])
    passengers = int(values[4])
    if horizontal <= 0:
        raise ValueError("horizontal length must be positive")
    if rise < 0:
        raise ValueError("vertical rise cannot be negative")
    if speed <= 0:
        raise ValueError("lift speed must be positive")
    if spacing <= 0:
        raise ValueError("chair spacing must be positive")
    if passengers < 1:
        raise ValueError("a chair must carry at least one passenger")
    return horizontal, rise, speed, spacing, passengers


def travel_seconds(distance, speed):
    return distance / speed


def ride_minutes(slope, speed):
    seconds = travel_seconds(slope, speed)
    return seconds / 60.0


def loop_length(slope):
    return slope * 2.0


def loop_chairs(slope, spacing):
    loop = loop_length(slope)
    return loop / spacing


def chairs_per_hour(interval):
    return 3600.0 / interval


def hourly_capacity(interval, passengers):
    rate = chairs_per_hour(interval)
    return rate * passengers


def chairlift(specs):
    horizontal, rise, speed, spacing, passengers = parse_specs(specs)
    slope = math.hypot(horizontal, rise)
    ride_time = ride_minutes(slope, speed)
    total_chairs = loop_chairs(slope, spacing)
    interval = travel_seconds(spacing, speed)
    capacity = hourly_capacity(interval, passengers)
    return round(ride_time, 1), round(total_chairs, 1), round(capacity, 1)


def format_report(name, specs):
    ride_time, total_chairs, capacity = chairlift(specs)
    lines = ["Lift: {0}".format(name)]
    lines.append("  ride time     : {0} min".format(ride_time))
    lines.append("  chairs on loop: {0}".format(total_chairs))
    lines.append("  capacity      : {0} passengers/hour".format(capacity))
    if capacity >= 2000:
        lines.append("  rating        : high volume")
    else:
        lines.append("  rating        : low volume")
    return "\n".join(lines)


def main():
    lifts = [
        ("Summit Express", (1000, 300, 2.5, 15, 4)),
        ("Beginner Carpet", {"horizontal": 220, "rise": 40,
                             "speed": 1.8, "spacing": 12, "passengers": 2}),
        ("Glacier Gondola", (2400, 900, 5.0, 40, 8)),
    ]
    rates = []
    for name, specs in lifts:
        print(format_report(name, specs))
        hourly = chairlift(specs)[2]
        rates.append((hourly, name))
    busiest = max(rates)
    print("Busiest lift: {1} at {0} passengers/hour".format(*busiest))


if __name__ == "__main__":
    main()

