    if distance <= 0:
        raise ValueError("moon distance must be positive")
    if earth_speed < 0:
        raise ValueError("earth rotational velocity cannot be negative")
    return shadow, moon_speed, earth_speed, distance


def _relative_speed(moon_speed, earth_speed):
    """Speed of the shadow over the ground."""
    return moon_speed - earth_speed


def _totality(shadow, relative_speed):
    """Seconds needed for the shadow to pass one observer."""
    return shadow / relative_speed


def _penumbra(distance):
    """Width of the partial shadow ring."""
    return distance * SOLAR_ANGULAR_FACTOR


def eclipse(data):
    """Return (relative speed, totality duration, penumbra width)."""
    shadow, moon_speed, earth_speed, distance = _unpack(data)
    relative_speed = _relative_speed(moon_speed, earth_speed)
    if relative_speed <= 0:
        raise ValueError("shadow does not move across the surface")
    totality = _totality(shadow, relative_speed)
    penumbra = _penumbra(distance)
    return (round(relative_speed, 1), round(totality, 1), round(penumbra, 1))


