import math

FIELDS = (
    "daily_usage",
    "system_voltage",
    "autonomy_days",
    "depth_of_discharge",
    "inverter_efficiency",
)


def parse_requirements(requirements):
    if isinstance(requirements, dict):
        values = []
        for name in FIELDS:
            if name not in requirements:
                raise KeyError("missing requirement: " + name)
            values.append(requirements[name])
        return tuple(values)
    values = tuple(requirements)
    if len(values) != len(FIELDS):
        raise ValueError("expected five requirement values")
    return values


def validate(usage, voltage, days, dod, efficiency):
    if usage <= 0:
        raise ValueError("daily usage must be positive")
    if voltage <= 0:
        raise ValueError("system voltage must be positive")
    if days < 1:
        raise ValueError("autonomy days must be at least one")
    if dod <= 0:
        raise ValueError("depth of discharge must be above zero")
    if dod > 1:
        raise ValueError("depth of discharge cannot exceed 1.0")
    if efficiency <= 0:
        raise ValueError("inverter efficiency must be above zero")
    if efficiency > 1:
        raise ValueError("inverter efficiency cannot exceed 1.0")


def daily_draw(usage, efficiency):
    return usage / efficiency


def usable_energy(draw, days):
    return draw * days


def gross_storage(usable, dod):
    return usable / dod


def amp_hour_capacity(gross, voltage):
    return gross / voltage


def battery_count(amps, module_amps):
    return math.ceil(amps / module_amps)


def offgrid(requirements):
    usage, voltage, days, dod, efficiency = parse_requirements(requirements)
    validate(usage, voltage, days, dod, efficiency)
    draw = daily_draw(usage, efficiency)
    usable = usable_energy(draw, days)
    gross = gross_storage(usable, dod)
    amps = amp_hour_capacity(gross, voltage)
    return round(draw), round(gross), round(amps)


def format_report(requirements, module_amps=200):
    draw, gross, amps = offgrid(requirements)
    voltage = parse_requirements(requirements)[1]
    modules = battery_count(amps, module_amps)
    lines = ["Off-grid battery bank sizing at {} V".format(voltage)]
    lines.append("  Daily draw from battery: {} Wh".format(draw))
    lines.append("  Gross storage needed:    {} Wh".format(gross))
    lines.append("  Bank capacity:           {} Ah".format(amps))
    lines.append("  Modules of {} Ah:       {}".format(module_amps, modules))
    return "\n".join(lines)


def main():
    cabin = (5000, 48, 3, 0.8, 0.95)
    print(format_report(cabin))
    workshop = {
        "daily_usage": 8200,
        "system_voltage": 24,
        "autonomy_days": 2,
        "depth_of_discharge": 0.5,
        "inverter_efficiency": 0.9,
    }
    print(format_report(workshop, module_amps=300))


if __name__ == "__main__":
    main()

