import math

DOWNSPOUT_CAPACITY = 250.0


def _validate(roof):
    if len(roof) != 4:
        raise ValueError("roof needs length, width, pitch and rainfall intensity")
    for value in roof:
        if value <= 0:
            raise ValueError("every roof parameter must be positive")


def footprint(length, width):
    return length * width


def effective_area(length, width, pitch):
    base = footprint(length, width)
    return base * pitch


def runoff_per_hour(area, intensity):
    return area * intensity


def runoff_per_minute(volume_per_hour):
    return volume_per_hour / 60.0


def downspout_count(liters_per_minute):
    return math.ceil(liters_per_minute / DOWNSPOUT_CAPACITY)


def half_perimeter(length, width):
    return length + width


def perimeter(length, width):
    return 2 * half_perimeter(length, width)


def spacing(edge_length, count):
    return edge_length / count


def total_capacity(count):
    return DOWNSPOUT_CAPACITY * count


def spare_capacity(liters_per_minute, count):
    return total_capacity(count) - liters_per_minute


def drainage(roof):
    _validate(roof)
    length, width, pitch, intensity = roof
    area = effective_area(length, width, pitch)
    hourly = runoff_per_hour(area, intensity)
    per_minute = runoff_per_minute(hourly)
    count = downspout_count(per_minute)
    edge = perimeter(length, width)
    gap = spacing(edge, count)
    return [round(per_minute, 2), count, round(gap, 2)]


def format_report(roof, result):
    length, width, pitch, intensity = roof
    liters, count, gap = result
    noun = "downspouts"
    if count == 1:
        noun = "downspout"
    area = effective_area(length, width, pitch)
    margin = spare_capacity(liters, count)
    lines = ["Roof {:g} m x {:g} m, pitch {:g}".format(length, width, pitch)]
    lines.append("  effective area: {:.2f} m2".format(area))
    lines.append("  rainfall {:g} mm/h -> {:.2f} L/min".format(intensity, liters))
    lines.append("  {} {} needed, {:.2f} m apart".format(count, noun, gap))
    lines.append("  spare capacity: {:.2f} L/min".format(margin))
    if gap > 15.0:
        lines.append("  note: wide spacing, consider an intermediate outlet")
    return "\n".join(lines)


def main():
    roofs = [(10, 8, 1.2, 50), (24, 12, 1.4, 90), (30, 15, 1.0, 120)]
    for roof in roofs:
        result = drainage(roof)
        print(format_report(roof, result))
    fleet = sum(drainage(roof)[1] for roof in roofs)
    print("Total downspouts for all roofs: {}".format(fleet))


if __name__ == "__main__":
    main()

