G = 9.8

def to_kilograms(tons):
    return tons * 1000.0

def to_metres_per_second(kph):
    return kph / 3.6

def half(value):
    return value / 2.0

def square(value):
    return value * value

def kinetic_energy(mass, velocity):
    return half(mass * square(velocity))

def weight(mass):
    return mass * G

def grade_fraction(grade):
    return grade / 100.0

def grade_pull(mass, grade):
    return weight(mass) * grade_fraction(grade)

def brake_force(mass, friction):
    return weight(mass) * friction

def stopping_force(brake, pull):
    return brake + pull

def braking_distance(energy, force):
    return energy / force

def parse_train(text):
    """Turn a "mass, speed, grade, friction" string into a validated tuple."""
    values = [float(piece) for piece in text.split(",")]
    if len(values) != 4:
        raise ValueError("a train needs mass, speed, grade and friction")
    mass_t, speed_kph, grade, friction = values
    if mass_t <= 0:
        raise ValueError("mass must be positive")
    if friction <= 0:
        raise ValueError("friction coefficient must be positive")
    return (mass_t, speed_kph, grade, friction)

def braking(train):
    """Net stopping force in newtons and braking distance in metres."""
    mass_t, speed_kph, grade, friction = train
    mass = to_kilograms(mass_t)
    velocity = to_metres_per_second(speed_kph)
    energy = kinetic_energy(mass, velocity)
    net = stopping_force(brake_force(mass, friction), grade_pull(mass, grade))
    if net <= 0:
        return "runaway train: the grade beats the brakes"
    distance = braking_distance(energy, net)
    return round(net, 1), round(distance, 1)

def format_report(train, result):
    label = "%.0f t at %.0f km/h, grade %.1f%%" % (train[0], train[1], train[2])
    if isinstance(result, str):
        return "%s -> %s" % (label, result)
    return "%s -> %.1f N net, stops in %.1f m" % (label, result[0], result[1])

def main():
    samples = ["500, 80, -2, 0.05", "500, 80, -4, 0.03", "1200, 60, 1.5, 0.08"]
    longest = 0.0
    for text in samples:
        train = parse_train(text)
        result = braking(train)
        print(format_report(train, result))
        if not isinstance(result, str) and result[1] > longest:
            longest = result[1]
    print("longest braking distance: %.1f m" % longest)

if __name__ == "__main__":
    main()

