def validate_system(volume, adult_mass, feed_rate, processing_rate):
    """Every system parameter has to be a strictly positive number."""
    checks=(
        ("tank volume", volume),
        ("adult fish mass", adult_mass),
        ("feeding rate", feed_rate),
        ("biofilter processing rate", processing_rate),
    )
    for label, value in checks:
        if value<=0:
            raise ValueError(f"{label} must be positive")


def max_fish_count(volume):
    return int(volume//20)


def total_fish_mass_g(count, adult_mass):
    return count*adult_mass


def total_fish_mass_kg(mass_g):
    return mass_g/1000


def feed_fraction(feed_rate):
    return feed_rate/100


def daily_feed_g(mass_g, fraction):
    return mass_g*fraction


def daily_ammonia_g(feed):
    return feed*0.03


def biofilter_area_m2(ammonia, processing_rate):
    return ammonia/processing_rate


def aquaponics(system):
    """Return [fish count, daily feed in grams, biofilter area in m2]."""
    volume, adult_mass, feed_rate, processing_rate=parse_system(system)
    validate_system(volume, adult_mass, feed_rate, processing_rate)
    count=max_fish_count(volume)
    mass_g=total_fish_mass_g(count, adult_mass)
    fraction=feed_fraction(feed_rate)
    feed=daily_feed_g(mass_g, fraction)
    ammonia=daily_ammonia_g(feed)
    area=biofilter_area_m2(ammonia, processing_rate)
    return [count, round(feed, 2), round(area, 2)]


def format_report(system):
    volume, adult_mass, feed_rate, processing_rate=parse_system(system)
    count, feed, area=aquaponics(system)
    mass_g=total_fish_mass_g(count, adult_mass)
    mass_kg=total_fish_mass_kg(mass_g)
    lines=[f"Tank volume: {volume} L"]
    lines.append(f"Stocking limit: {count} fish at {adult_mass} g each")
    lines.append(f"Standing biomass: {round(mass_kg, 2)} kg")
    lines.append(f"Feeding rate: {feed_rate} % of body weight")
    lines.append(f"Daily feed: {feed} g")
    lines.append(f"Biofilter rate: {processing_rate} g ammonia per m2")
    lines.append(f"Required biofilter area: {area} m2")
    return "\n".join(lines)


def main():
    system={
        "tank_volume_l": 1000,
        "adult_fish_mass_g": 500,
        "feeding_rate_pct": 2.0,
        "biofilter_rate_g_per_m2": 0.5,
    }
    print(format_report(system))


if __name__=="__main__":
    main()

