import math

GRAVITY = 9.8
SPEED_OF_SOUND = 340.29


def validate(specs):
    radius = specs["radius"]
    rpm = specs["rpm"]
    density = specs["density"]
    lift_coefficient = specs["lift_coefficient"]
    if radius <= 0:
        raise ValueError("radius must be positive")
    if rpm <= 0:
        raise ValueError("rpm must be positive")
    if density <= 0:
        raise ValueError("air density must be positive")
    if lift_coefficient <= 0:
        raise ValueError("lift coefficient must be positive")
    return radius, rpm, density, lift_coefficient


def disc_area(radius):
    return math.pi * math.pow(radius, 2)


def angular_velocity(rpm):
    return math.radians(rpm * 6.0)


def blade_tip_speed(omega, radius):
    return omega * radius


def dynamic_pressure(density, tip_speed):
    return math.prod((0.5, density, math.pow(tip_speed, 2)))


def total_lift(pressure, area, lift_coefficient):
    return math.prod((pressure, area, lift_coefficient))


def mass_from_force(force):
    return force / GRAVITY


def mach_fraction(tip_speed):
    return tip_speed / SPEED_OF_SOUND


def rotor(specs):
    radius, rpm, density, lift_coefficient = validate(specs)
    area = disc_area(radius)
    omega = angular_velocity(rpm)
    tip_speed = blade_tip_speed(omega, radius)
    pressure = dynamic_pressure(density, tip_speed)
    force = total_lift(pressure, area, lift_coefficient)
    capacity = mass_from_force(force)
    return round(tip_speed, 2), round(force, 2), round(capacity, 2)


def report(name, specs):
    tip_speed, force, capacity = rotor(specs)
    mach = mach_fraction(tip_speed)
    lines = [name]
    lines.append("  tip speed    : {0:>12.2f} m/s".format(tip_speed))
    lines.append("  tip mach     : {0:>12.3f}".format(mach))
    lines.append("  lift force   : {0:>12.2f} N".format(force))
    lines.append("  max capacity : {0:>12.2f} kg".format(capacity))
    if mach >= 1.0:
        lines.append("  warning: blade tips are supersonic")
    elif mach > 0.92:
        lines.append("  warning: blade tips near sonic limit")
    return "\n".join(lines)


def capacity_of(entry):
    return rotor(entry[1])[2]


def main():
    fleet = [
        ("Light utility", {"radius": 5.5, "rpm": 400, "density": 1.225, "lift_coefficient": 0.4}),
        ("Medium lift", {"radius": 8.0, "rpm": 320, "density": 1.225, "lift_coefficient": 0.5}),
        ("Heavy lift", {"radius": 11.0, "rpm": 250, "density": 1.1, "lift_coefficient": 0.55}),
        ("High altitude", {"radius": 8.0, "rpm": 360, "density": 0.82, "lift_coefficient": 0.5}),
    ]
    for entry in fleet:
        print(report(entry[0], entry[1]))
    best = max(fleet, key=capacity_of)
    print("Greatest lifting capacity: {0} at {1:.2f} kg".format(best[0], capacity_of(best)))


if __name__ == "__main__":
    main()

