import math

SEAWATER_POUNDS_PER_CUBIC_FOOT = 64.0
POUNDS_PER_LONG_TON = 2240.0
HULL_SPEED_FACTOR = 1.34
FIELD_NAMES = ("waterline length", "beam width", "draft depth", "displacement")


def _validated(measurements):
    values = tuple(float(value) for value in measurements)
    if len(values) != 4:
        raise ValueError("four measurements are required")
    for name, value in zip(FIELD_NAMES, values):
        if value <= 0:
            raise ValueError(f"{name} must be greater than zero")
    return values


def hull_speed(waterline_length):
    return HULL_SPEED_FACTOR * math.sqrt(waterline_length)


def displacement_length_ratio(waterline_length, displacement):
    long_tons = displacement / POUNDS_PER_LONG_TON
    hundredths = waterline_length / 100.0
    cubed = hundredths ** 3
    return long_tons / cubed


def immersed_volume(displacement):
    return displacement / SEAWATER_POUNDS_PER_CUBIC_FOOT


def sail_area_displacement_ratio(waterline_length, beam_width, displacement):
    nominal_sail_area = waterline_length * beam_width
    volume = immersed_volume(displacement)
    exponent = 2.0 / 3.0
    return nominal_sail_area / volume ** exponent


def draft_to_length_ratio(waterline_length, draft_depth):
    return draft_depth / waterline_length


def sailboat(measurements):
    waterline_length, beam_width, draft_depth, displacement = _validated(measurements)
    speed = hull_speed(waterline_length)
    heaviness = displacement_length_ratio(waterline_length, displacement)
    power = sail_area_displacement_ratio(waterline_length, beam_width, displacement)
    return round(speed, 2), round(heaviness, 2), round(power, 2)


def describe_displacement(ratio):
    if ratio < 100.0:
        return "ultralight"
    if ratio < 200.0:
        return "light"
    if ratio < 300.0:
        return "moderate"
    return "heavy"


def describe_rig(ratio):
    if ratio < 14.0:
        return "cruiser"
    if ratio < 18.0:
        return "performance cruiser"
    return "racer"


def main():
    fleet = [
        ("Windward", (36, 12, 6, 20000)),
        ("Petrel", (24, 8.5, 4, 6200)),
        ("Albatross", (48, 14, 7.5, 42000)),
    ]
    best_name = None
    best_speed = 0.0
    for name, measurements in fleet:
        speed, heaviness, power = sailboat(measurements)
        grip = draft_to_length_ratio(measurements[0], measurements[2])
        print(f"{name}: {speed} kn, D/L {heaviness}, SA/D {power}")
        print(f"  {describe_displacement(heaviness)} hull rigged as a {describe_rig(power)}")
        print(f"  draft is {round(grip, 3)} of the waterline length")
        if speed > best_speed:
            best_speed = speed
            best_name = name
    print(f"Fastest hull speed: {best_name} at {best_speed} kn")


if __name__ == "__main__":
    main()

