def validate_optics(optics):
    """Check that optics holds three positive numbers and return them as floats."""
    values = list(optics)
    if len(values) != 3:
        raise ValueError("optics must hold diameter, objective focal length, eyepiece focal length")
    diameter = float(values[0])
    objective = float(values[1])
    eyepiece = float(values[2])
    if diameter <= 0:
        raise ValueError("objective diameter must be positive")
    if objective <= 0:
        raise ValueError("objective focal length must be positive")
    if eyepiece <= 0:
        raise ValueError("eyepiece focal length must be positive")
    return diameter, objective, eyepiece


def focal_ratio(diameter, objective):
    """Objective focal length expressed in units of the aperture."""
    return objective / diameter


def magnification(objective, eyepiece):
    """Angular magnification produced by the given eyepiece."""
    return objective / eyepiece


def exit_pupil(diameter, power):
    """Diameter in millimetres of the light cone leaving the eyepiece."""
    return diameter / power


def max_useful_power(diameter):
    """Highest magnification the aperture can usefully support."""
    return 2 * diameter


def resolving_power(diameter):
    """Dawes limit in arcseconds for the given aperture."""
    return 116 / diameter


def telescope(optics):
    """Return (focal ratio, magnification, exit pupil, max useful power, resolving power)."""
    diameter, objective, eyepiece = validate_optics(optics)
    power = magnification(objective, eyepiece)
    return (
        round(focal_ratio(diameter, objective), 1),
        round(power, 1),
        round(exit_pupil(diameter, power), 1),
        round(max_useful_power(diameter), 1),
        round(resolving_power(diameter), 1),
    )


def describe(name, diameter, readings):
    """Build a multi-line report for one telescope and eyepiece combination."""
    ratio, power, pupil, limit, resolution = readings
    lines = ["{} ({:.0f} mm aperture)".format(name, diameter)]
    lines.append("  focal ratio        f/{:.1f}".format(ratio))
    lines.append("  magnification      {:.1f}x".format(power))
    lines.append("  exit pupil         {:.1f} mm".format(pupil))
    lines.append("  max useful power   {:.1f}x".format(limit))
    lines.append("  resolving power    {:.1f} arcsec".format(resolution))
    if power > limit:
        lines.append("  warning: eyepiece exceeds the useful magnification limit")
    elif pupil < 0.5:
        lines.append("  note: exit pupil is small, the image will look dim")
    return "\n".join(lines)


def main():
    instruments = [
        ("Newtonian reflector", (200, 2000, 10)),
        ("Achromatic refractor", (102, 714, 25)),
        ("Schmidt-Cassegrain", (203, 2032, 4)),
    ]
    best_name = None
    best_resolution = float("inf")
    for name, optics in instruments:
        readings = telescope(optics)
        print(describe(name, optics[0], readings))
        print()
        if readings[4] < best_resolution:
            best_resolution = readings[4]
            best_name = name
    print("Sharpest instrument: {} at {:.1f} arcsec".format(best_name, best_resolution))


if __name__ == "__main__":
    main()

