import math

ASPHALT_DENSITY = 2400.0
GRAVEL_DENSITY = 2000.0
CM_PER_M = 100.0
KG_PER_TON = 1000.0
TRUCK_CAPACITY = 25.0


def _check_positive(name, value):
    if value <= 0:
        raise ValueError(f"{name} must be greater than zero")
    return float(value)


def _validate(lot):
    values = list(lot)
    if len(values) != 4:
        raise ValueError("lot must hold length, width, asphalt cm, gravel cm")
    names = ("length", "width", "asphalt thickness", "gravel thickness")
    return [_check_positive(name, value) for name, value in zip(names, values)]


def surface_area(length, width):
    return length * width


def to_meters(centimeters):
    return centimeters / CM_PER_M


def layer_volume(area, thickness_m):
    return area * thickness_m


def layer_kilograms(volume_m3, density):
    return volume_m3 * density


def to_tons(kilograms):
    return kilograms / KG_PER_TON


def total_weight(asphalt_tons, gravel_tons):
    return asphalt_tons + gravel_tons


def truckloads(total_tons):
    return math.ceil(total_tons / TRUCK_CAPACITY)


def paving(lot):
    length, width, asphalt_cm, gravel_cm = _validate(lot)
    area = surface_area(length, width)
    asphalt_m = to_meters(asphalt_cm)
    gravel_m = to_meters(gravel_cm)
    asphalt_volume = layer_volume(area, asphalt_m)
    gravel_volume = layer_volume(area, gravel_m)
    asphalt_tons = to_tons(layer_kilograms(asphalt_volume, ASPHALT_DENSITY))
    gravel_tons = to_tons(layer_kilograms(gravel_volume, GRAVEL_DENSITY))
    return [round(asphalt_volume, 2), round(asphalt_tons, 2), round(gravel_tons, 2)]


def asphalt_tons_of(lot):
    return paving(lot)[1]


def heaviest_asphalt(jobs):
    return max(jobs, key=asphalt_tons_of)


def format_report(lot):
    asphalt_volume, asphalt_tons, gravel_tons = paving(lot)
    total_tons = total_weight(asphalt_tons, gravel_tons)
    lines = [f"Lot {lot[0]} m by {lot[1]} m"]
    lines.append(f"  asphalt volume : {asphalt_volume:.2f} m3")
    lines.append(f"  asphalt weight : {asphalt_tons:.2f} t")
    lines.append(f"  gravel weight  : {gravel_tons:.2f} t")
    lines.append(f"  total material : {total_tons:.2f} t")
    loads = truckloads(total_tons)
    lines.append(f"  haulage        : {loads} truckloads")
    return "\n".join(lines)


def main():
    jobs = [(100, 50, 10, 20), (25, 12.5, 8, 15), (18, 6, 5, 10)]
    for lot in jobs:
        print(format_report(lot))
        print()
    heaviest = heaviest_asphalt(jobs)
    print(f"Largest asphalt order: lot {heaviest[0]} m by {heaviest[1]} m")


if __name__ == "__main__":
    main()

