SPEED_OF_LIGHT = 300000
HIGH_REDSHIFT_LIMIT = 0.5


def redshift(wavelength, rest, hubble):
    if rest <= 0:
        raise ValueError("rest wavelength must be positive")
    if hubble <= 0:
        raise ValueError("hubble constant must be positive")
    shift = (
        wavelength - rest
    )
    z = (
        shift / rest
    )
    velocity = (
        z * SPEED_OF_LIGHT
    )
    distance = (
        velocity / hubble
    )
    highly_distant = (
        z > HIGH_REDSHIFT_LIMIT
    )
    return [z, velocity, round(distance, 1), highly_distant]


def classify(z):
    if z < 0:
        return "blueshifted"
    if z < 0.01:
        return "local"
    if z <= HIGH_REDSHIFT_LIMIT:
        return "nearby"
    return "distant"


def format_report(name, result):
    z, velocity, distance, highly_distant = result
    kind = classify(z)
    flag = "yes" if highly_distant else "no"
    line = "{:<10} z = {:>8.4f}  v = {:>10.1f} km/s  d = {:>9.1f} Mpc  {:<11} far: {}"
    return line.format(name, z, velocity, distance, kind, flag)


def survey(observations, hubble):
    report = []
    for name, wavelength, rest in observations:
        result = redshift(wavelength, rest, hubble)
        report.append((name, result))
    return report


def mean_distance(report):
    if not report:
        return 0.0
    total = 0.0
    for _, result in report:
        total = (
            total + result[2]
        )
    return total / len(report)


def main():
    hubble = 70
    observations = [
        ("NGC-1000", 500, 400),
        ("NGC-2200", 656.5, 656.3),
        ("QSO-7", 900, 400),
        ("ARP-14", 4100, 4200),
    ]
    report = survey(observations, hubble)
    print("Hubble constant = {} km/s/Mpc".format(hubble))
    for name, result in report:
        print(format_report(name, result))
    far_count = sum(1 for _, result in report if result[3])
    average = mean_distance(report)
    print("Highly distant galaxies: {} of {}".format(far_count, len(report)))
    print("Mean estimated distance: {:.1f} Mpc".format(average))
    if average > 1000:
        print("Survey reaches beyond 1000 Mpc")


if __name__ == "__main__":
    main()

