def as_fraction(percent):
    return percent / 100


def percent_of(base, percent):
    return base * as_fraction(percent)


def validate_inputs(flour, hydration, salt, yeast):
    if flour <= 0:
        raise ValueError("flour weight must be positive")
    if hydration < 0:
        raise ValueError("hydration percentage cannot be negative")
    if salt < 0:
        raise ValueError("salt percentage cannot be negative")
    if yeast < 0:
        raise ValueError("yeast percentage cannot be negative")


def dough(flour, hydration, salt, yeast):
    validate_inputs(flour, hydration, salt, yeast)
    water_weight = percent_of(flour, hydration)
    salt_weight = percent_of(flour, salt)
    yeast_weight = percent_of(flour, yeast)
    total = sum([flour, water_weight, salt_weight, yeast_weight])
    if hydration > 65:
        classification = "wet dough"
    else:
        classification = "standard dough"
    return (water_weight, salt_weight, yeast_weight, total, classification)


def format_grams(weight):
    rounded = round(weight, 1)
    if rounded == int(rounded):
        return "{:d}g".format(int(rounded))
    return "{:.1f}g".format(rounded)


def ball_count(total, ball_weight):
    if ball_weight <= 0:
        raise ValueError("ball weight must be positive")
    return int(total // ball_weight)


def used_dough(total, ball_weight):
    return ball_count(total, ball_weight) * ball_weight


def leftover_dough(total, ball_weight):
    return total - used_dough(total, ball_weight)


def recipe_report(name, flour, hydration, salt, yeast, ball_weight):
    water, salt_g, yeast_g, total, kind = dough(flour, hydration, salt, yeast)
    balls = ball_count(total, ball_weight)
    leftover = leftover_dough(total, ball_weight)
    lines = ["{} ({})".format(name, kind)]
    lines.append("  flour  {}".format(format_grams(flour)))
    lines.append("  water  {}".format(format_grams(water)))
    lines.append("  salt   {}".format(format_grams(salt_g)))
    lines.append("  yeast  {}".format(format_grams(yeast_g)))
    lines.append("  total  {}".format(format_grams(total)))
    summary = "  yields {} ball(s) of {}".format(balls, format_grams(ball_weight))
    if leftover > 0.05:
        summary = "{}, {} left over".format(summary, format_grams(leftover))
    lines.append(summary)
    return "\n".join(lines)


def main():
    recipes = [
        ("Napoletana", 1000, 70, 2, 1, 250),
        ("New York", 1500, 62, 2.5, 0.4, 350),
        ("Focaccia", 800, 80, 2, 1.5, 400),
    ]
    kinds = []
    for name, flour, hydration, salt, yeast, ball in recipes:
        print(recipe_report(name, flour, hydration, salt, yeast, ball))
        kinds.append(dough(flour, hydration, salt, yeast)[4])
        print("")
    wet_count = kinds.count("wet dough")
    standard_count = kinds.count("standard dough")
    print("wet doughs: {}, standard: {}".format(wet_count, standard_count))


if __name__ == "__main__":
    main()

