import math

GRAMS_PER_DRINK = 14
GENDER_FACTOR_MALE = 0.73
GENDER_FACTOR_FEMALE = 0.66
DISTRIBUTION_SPREAD = 8
METABOLISM_PER_HOUR = 15
TENTHS_PER_UNIT = 10.0
LEGAL_LIMIT = 80


def validate_inputs(drinks, weight, hours):
    """Reject physically impossible arguments before any arithmetic."""
    if drinks < 0:
        raise ValueError("drinks cannot be negative")
    if weight <= 0:
        raise ValueError("weight must be a positive number of kilograms")
    if hours < 0:
        raise ValueError("hours cannot be negative")


def gender_factor(male):
    """Fraction of body mass in which alcohol is distributed."""
    if male:
        return GENDER_FACTOR_MALE
    return GENDER_FACTOR_FEMALE


def grams_of_alcohol(drinks):
    return drinks * GRAMS_PER_DRINK


def distribution_volume(weight, male):
    factor = gender_factor(male)
    return weight * factor


def concentration(grams, volume):
    return grams / volume


def raw_level(grams, volume):
    return DISTRIBUTION_SPREAD * concentration(grams, volume)


def metabolized(hours):
    return hours * METABOLISM_PER_HOUR


def net_level(grams, volume, hours):
    return raw_level(grams, volume) - metabolized(hours)


def scale_to_tenths(value):
    """Express the level in tenths so that it can be floored."""
    return value * TENTHS_PER_UNIT


def truncate_tenths(value):
    """Cut the value down to one decimal place without rounding up."""
    return math.floor(scale_to_tenths(value)) / TENTHS_PER_UNIT


def is_over_limit(level):
    return level >= LEGAL_LIMIT


def bac(drinks, weight, male, hours):
    validate_inputs(drinks, weight, hours)
    grams = grams_of_alcohol(drinks)
    volume = distribution_volume(weight, male)
    level = net_level(grams, volume, hours)
    if level < 0:
        level = 0.0
    level = truncate_tenths(level)
    return level, is_over_limit(level)


def describe(drinks, weight, male, hours):
    level, over = bac(drinks, weight, male, hours)
    gender = "male" if male else "female"
    status = "over the legal limit" if over else "within the legal limit"
    return f"{drinks} drinks, {weight} kg {gender}, {hours} h later: {level} ({status})"


def main():
    cases = [(10, 80, True, 1), (12, 70, False, 0), (2, 95, True, 3)]
    for drinks, weight, male, hours in cases:
        print(describe(drinks, weight, male, hours))


if __name__ == "__main__":
    main()

