import math


def validate_inputs(length, mass, angle, gravity):
    if length <= 0:
        raise ValueError("length must be positive")
    if mass <= 0:
        raise ValueError("mass must be positive")
    if gravity <= 0:
        raise ValueError("gravity must be positive")
    if angle < 0 or angle > 180:
        raise ValueError("angle must be between 0 and 180 degrees")


def standard_period(length, gravity):
    return 2 * math.pi * math.sqrt(length / gravity)


def max_height(length, angle):
    radians = math.radians(angle)
    return length * (1 - math.cos(radians))


def potential_energy(mass, gravity, height):
    return mass * gravity * height


def small_angle_valid(angle):
    return angle < 15


def pendulum(length, mass, angle, gravity):
    validate_inputs(length, mass, angle, gravity)
    period = standard_period(length, gravity)
    height = max_height(length, angle)
    energy = potential_energy(mass, gravity, height)
    valid = small_angle_valid(angle)
    return [round(period, 2), round(height, 2), round(energy, 2), valid]


def corrected_period(length, angle, gravity, terms=4):
    base = standard_period(length, gravity)
    half = math.radians(angle) / 2
    k = math.sin(half)
    total = 1.0
    n = 1
    while n < terms:
        numerator = math.factorial(2 * n)
        denominator = (2 ** n * math.factorial(n)) ** 2
        coefficient = (numerator / denominator) ** 2
        total += coefficient * k ** (2 * n)
        n += 1
    return base * total


def format_report(length, mass, angle, gravity):
    period, height, energy, valid = pendulum(length, mass, angle, gravity)
    exact = corrected_period(length, angle, gravity)
    error = abs(exact - period) / exact * 100
    lines = []
    lines.append("Pendulum: L = {0} m, m = {1} kg, theta = {2} deg".format(length, mass, angle))
    lines.append("  period          : {0:.2f} s".format(period))
    lines.append("  max height      : {0:.2f} m".format(height))
    lines.append("  potential energy: {0:.2f} J".format(energy))
    lines.append("  small angle ok  : {0}".format(valid))
    lines.append("  corrected period: {0:.2f} s".format(exact))
    lines.append("  relative error  : {0:.3f} %".format(error))
    return "\n".join(lines)


def main():
    cases = [
        (2.0, 1.5, 10, 9.81),
        (1.0, 0.5, 45, 9.81),
        (0.25, 2.0, 60, 1.62),
    ]
    for length, mass, angle, gravity in cases:
        print(format_report(length, mass, angle, gravity))
        print()


if __name__ == "__main__":
    main()

