def validate_inputs(price, salvage, years, age):
    """Check that the vehicle figures make sense before any arithmetic."""
    if price <= 0:
        raise ValueError("price must be positive")
    if salvage < 0:
        raise ValueError("salvage cannot be negative")
    if salvage > price:
        raise ValueError("salvage cannot exceed the purchase price")
    if years <= 0:
        raise ValueError("years must be positive")
    if age < 0:
        raise ValueError("age cannot be negative")


def depreciation(price, salvage, years, age):
    """Return the straight line and double declining values of a vehicle."""
    validate_inputs(price, salvage, years, age)
    depreciable = price - salvage
    yearly_drop = depreciable / years
    accumulated = yearly_drop * age
    straight_line = price - accumulated
    rate = 2 / years
    retained = 1 - rate
    declining = price * retained ** age
    if straight_line < salvage:
        straight_line = salvage
    if declining < salvage:
        declining = salvage
    return (straight_line, declining)


def format_money(value):
    return "${:>12,.2f}".format(value)


def lost_value(price, current):
    """How much value the vehicle has shed so far."""
    return price - current


def faster_method(straight_line, declining):
    if declining < straight_line:
        return "double declining"
    if straight_line < declining:
        return "straight line"
    return "tie"


def build_schedule(price, salvage, years):
    """Year by year table of both valuation methods."""
    rows = []
    last = years + 1
    for age in range(last):
        straight_line, declining = depreciation(price, salvage, years, age)
        rows.append((age, straight_line, declining))
    return rows


def print_schedule(price, salvage, years):
    print(" Age   Straight line   Double declining        Spread")
    for age, straight_line, declining in build_schedule(price, salvage, years):
        gap = straight_line - declining
        print("{:>4}  {}  {}  {}".format(age, format_money(straight_line),
                                         format_money(declining),
                                         format_money(gap)))


def main():
    price = 20000
    salvage = 2000
    years = 10
    age = 3
