ABSOLUTE_ZERO_C = -273.15
PERCENT = 100.0


def expansion(length, alpha, initial, final):
    """Return (new_length, percent_change, is_contraction) for a heated rod."""
    validate_inputs(length, alpha, initial, final)
    delta_t = temperature_change(initial, final)
    amount = linear_expansion(length, alpha, delta_t)
    return (
        length + amount,
        percent_change(amount, length),
        delta_t < 0,
    )


def temperature_change(initial, final):
    """Temperature rise of the rod, negative when it cools down."""
    return final - initial


def expansion_per_degree(length, alpha):
    """Length gained for every degree of temperature rise."""
    return length * alpha


def linear_expansion(length, alpha, delta_t):
    """Absolute length change produced by a change of delta_t degrees."""
    per_degree = expansion_per_degree(length, alpha)
    return per_degree * delta_t


def relative_change(amount, length):
    """Length change as a fraction of the original length."""
    return amount / length


def percent_change(amount, length):
    """Length change as a percentage of the original length."""
    fraction = relative_change(amount, length)
    return fraction * PERCENT


def validate_inputs(length, alpha, initial, final):
    """Reject physically meaningless rod data before computing."""
    if length <= 0:
        raise ValueError("rod length must be positive")
    if alpha < 0:
        raise ValueError("expansion coefficient cannot be negative")
    if initial < ABSOLUTE_ZERO_C:
        raise ValueError("initial temperature is below absolute zero")
    if final < ABSOLUTE_ZERO_C:
        raise ValueError("final temperature is below absolute zero")


def describe(material, length, alpha, initial, final):
    """Build a one-line report for a single rod measurement."""
    new_length, percent, contracted = expansion(length, alpha, initial, final)
    verb = "shrinks" if contracted else "grows"
    template = "{:<10} {} to {:.4f} m ({:+.4f}%)"
    return template.format(material, verb, new_length, percent)


def worst_case(samples):
    """Find the sample whose absolute percentage change is largest."""
    chosen = None
    largest = 0.0
    for material, length, alpha, initial, final in samples:
        percent = expansion(length, alpha, initial, final)[1]
        magnitude = abs(percent)
        if magnitude > largest:
            largest = magnitude
            chosen = material
    return chosen, largest


def main():
    samples = [
        ("steel", 100.0, 0.000012, 20.0, 70.0),
        ("aluminium", 2.5, 0.0000231, 15.0, 95.0),
        ("copper", 12.0, 0.0000168, 25.0, -40.0),
        ("glass", 0.75, 0.0000085, 20.0, 20.0),
    ]
    for sample in samples:
        print(describe(*sample))

    material, largest = worst_case(samples)
    print("Largest relative change: {} at {:.4f}%".format(material, largest))


if __name__ == "__main__":
    main()

