import math

G = 9.8
PERCENT = 100.0


def require_positive(name, value):
    if value <= 0:
        raise ValueError(f"{name} must be positive, got {value!r}")
    return float(value)


def require_percent(value):
    if value < 0:
        raise ValueError(f"friction must not be negative, got {value!r}")
    if value > PERCENT:
        raise ValueError(f"friction must not exceed 100, got {value!r}")
    return float(value)


def weight(mass):
    return mass * G


def potential_energy(mass, height):
    return weight(mass) * height


def fraction(percent):
    return percent / PERCENT


def friction_loss(energy, percent):
    return energy * fraction(percent)


def kinetic_energy(energy, loss):
    return energy - loss


def specific_energy(energy, mass):
    return energy / mass


def velocity_from_energy(energy, mass):
    return math.sqrt(2 * specific_energy(energy, mass))


def clears_loop(velocity, loop):
    return velocity >= loop


def coaster(mass, height, friction, loop):
    car_mass = require_positive("mass", mass)
    drop = require_positive("height", height)
    loss_percent = require_percent(friction)
    threshold = require_positive("loop", loop)
    initial = potential_energy(car_mass, drop)
    lost = friction_loss(initial, loss_percent)
    remaining = kinetic_energy(initial, lost)
    velocity = velocity_from_energy(remaining, car_mass)
    return round(velocity, 2), clears_loop(velocity, threshold)


def describe(mass, height, friction, loop):
    velocity, cleared = coaster(mass, height, friction, loop)
    verdict = "clears" if cleared else "stalls in"
    head = f"{mass} kg dropping {height} m, {friction}% lost to friction"
    return f"{head}: {velocity} m/s, {verdict} the {loop} m/s loop"


def main():
    rides = [
        (500, 50, 10, 25),
        (500, 50, 60, 25),
        (800, 20, 5, 15),
    ]
    for mass, height, friction, loop in rides:
        print(describe(mass, height, friction, loop))
    cleared = [r for r in rides if coaster(*r)[1]]
    print(f"{len(cleared)} of {len(rides)} rides make it around the loop")


if __name__ == "__main__":
    main()

