def validate(flour, original, target, liquid):
    if flour <= 0:
        raise ValueError("flour must be a positive amount in grams")
    if original <= 0:
        raise ValueError("original sugar must be a positive amount in grams")
    if target < 0:
        raise ValueError("target sugar cannot be negative")
    if target > original:
        raise ValueError("target sugar must not exceed the original sugar")
    if liquid < 0:
        raise ValueError("liquid cannot be negative")


def removed_sugar(original, target):
    return original - target


def fraction_removed(original, target):
    return removed_sugar(original, target) / original


def reduction_percent(original, target):
    return fraction_removed(original, target) * 100


def lost_volume(original, target):
    return removed_sugar(original, target) / 200


def extra_liquid(original, target):
    return lost_volume(original, target) * 0.5


def adjusted_liquid(original, target, liquid):
    return liquid + extra_liquid(original, target)


def sugar(flour, original, target, liquid):
    validate(flour, original, target, liquid)
    reduction = reduction_percent(original, target)
    return adjusted_liquid(original, target, liquid), reduction, reduction > 25


def hydration_ratio(flour, liquid):
    return liquid / flour


def hydration(flour, liquid):
    return hydration_ratio(flour, liquid) * 100


def format_amount(value):
    rounded = round(value, 2)
    if rounded == int(rounded):
        return str(int(rounded))
    return f"{rounded:g}"


def advice(reduction, texture_change):
    if not texture_change:
        return "Texture should stay close to the original."
    if reduction >= 50:
        return "Add an egg yolk or extra fat to rebuild richness."
    return "Expect a drier crumb, so shorten the bake slightly."


def report(name, flour, original, target, liquid):
    new_liquid, reduction, texture_change = sugar(flour, original, target, liquid)
    before = hydration(flour, liquid)
    after = hydration(flour, new_liquid)
    lines = [f"{name}: {format_amount(original)}g sugar -> {format_amount(target)}g sugar"]
    lines.append(f"  sugar reduction: {format_amount(reduction)}%")
    lines.append(f"  liquid: {format_amount(liquid)} -> {format_amount(new_liquid)} cups")
    lines.append(f"  hydration: {format_amount(before)}% -> {format_amount(after)}%")
    lines.append(f"  texture change likely: {str(texture_change).lower()}")
    lines.append(f"  {advice(reduction, texture_change)}")
    return "\n".join(lines)


def main():
    recipes = [
        ("Vanilla sponge", 300, 200, 100, 100),
        ("Oat cookies", 250, 180, 150, 40),
        ("Brownies", 200, 400, 120, 60),
    ]
    for name, flour, original, target, liquid in recipes:
        print(report(name, flour, original, target, liquid))
        print()
    total_removed = sum(removed_sugar(o, t) for _, _, o, t, _ in recipes)
    print(f"Total sugar removed across recipes: {format_amount(total_removed)}g")


if __name__ == "__main__":
    main()

