"""Ballast water calculations for a submarine trimming to a target depth."""

GRAVITY = 9.8


def _validate(mass, volume, density, target):
    if mass <= 0:
        raise ValueError("hull mass must be positive")
    if volume <= 0:
        raise ValueError("displaced volume must be positive")
    if density <= 0:
        raise ValueError("water density must be positive")
    if target < 0:
        raise ValueError("ballast tank capacity cannot be negative")


def _exceeds_capacity(ballast_volume, capacity):
    return ballast_volume > capacity


def submarine(mass, volume, density, target):
    _validate(mass, volume, density, target)
    buoyant = volume
    buoyant *= density
    buoyant *= GRAVITY
    weight = mass
    weight *= GRAVITY
    net_force = buoyant
    net_force -= weight
    ballast_mass = net_force
    ballast_mass /= GRAVITY
    ballast_volume = ballast_mass
    ballast_volume /= density
    exceeded = _exceeds_capacity(ballast_volume, target)
    return round(net_force, 2), round(ballast_volume, 2), exceeded


def tank_fill_percent(ballast_volume, capacity):
    if capacity == 0:
        return float("inf")
    fill = ballast_volume
    fill /= capacity
    fill *= 100
    return round(fill, 1)


def format_report(mass, volume, density, target, result):
    net_force, ballast_volume, exceeded = result
    fill = tank_fill_percent(ballast_volume, target)
    lines = ["Submarine: {} kg hull, {} m^3 displaced".format(mass, volume)]
    lines.append("Water density: {} kg/m^3".format(density))
    if net_force > 0:
        trend = "positively buoyant, rises without ballast"
    else:
        trend = "negatively buoyant, sinks without ballast"
    lines.append("Net force: {} N ({})".format(net_force, trend))
    lines.append("Ballast water required: {} m^3".format(ballast_volume))
    lines.append("Tank capacity: {} m^3, {}% used".format(target, fill))
    if exceeded:
        lines.append("WARNING: required ballast exceeds tank capacity")
    else:
        lines.append("Target depth reachable with available ballast")
    return "\n".join(lines)


def main():
    cases = [(5000, 6, 1025, 2), (5000, 9, 1025, 2)]
    for mass, volume, density, target in cases:
        result = submarine(mass, volume, density, target)
        report = format_report(mass, volume, density, target, result)
        print(report)
        print()


if __name__ == "__main__":
    main()

