BASE_SPEED=331.3
TEMP_COEFFICIENT=0.6
RUNNING_SPEED=5
SAFE_DISTANCE=5000
MAX_SAFE_TIME=30
ABSOLUTE_ZERO=-273.15


def validate_inputs(seconds, temperature, shelter, thunder):
    if seconds<0:
        raise ValueError("seconds since the flash cannot be negative")
    if temperature<ABSOLUTE_ZERO:
        raise ValueError("temperature is below absolute zero")
    if shelter<0:
        raise ValueError("distance to shelter cannot be negative")
    if thunder<0:
        raise ValueError("thunder loudness cannot be negative")


def temperature_drift(temperature):
    return temperature*TEMP_COEFFICIENT


def speed_of_sound(temperature):
    return BASE_SPEED+temperature_drift(temperature)


def strike_distance(speed, seconds):
    return speed*seconds


def time_to_safety(shelter):
    return shelter/RUNNING_SPEED


def is_dangerous(distance, seconds_needed):
    if distance>=SAFE_DISTANCE:
        return False
    return seconds_needed>MAX_SAFE_TIME


def thunder_description(thunder):
    if thunder>=120:
        return "deafening"
    if thunder>=90:
        return "loud"
    if thunder>=60:
        return "moderate"
    return "faint"


def tidy(value):
    if value==int(value):
        return int(value)
    return round(value, 1)


def lightning(seconds, temperature, shelter, thunder):
    validate_inputs(seconds, temperature, shelter, thunder)
    speed=speed_of_sound(temperature)
    distance=strike_distance(speed, seconds)
    seconds_needed=time_to_safety(shelter)
    danger=is_dangerous(distance, seconds_needed)
    return tidy(speed), tidy(distance), tidy(seconds_needed), danger


