import math

SPOKE_HOLES = 32
FULL_CIRCLE = 360

BUILDS = [
    ("Road rear", 600, 50, 5, 3),
    ("Road front", 600, 44, 0, 3),
    ("Touring rear", 622, 56, 4, 2),
]


def half(value):
    return value / 2


def square(value):
    return value * value


def hole_span():
    return FULL_CIRCLE / SPOKE_HOLES


def cross_angle(cross):
    return math.radians(cross * hole_span())


def sum_of_squares(rim_radius, flange_radius, offset):
    parts = [square(rim_radius), square(flange_radius), square(offset)]
    return sum(parts)


def chord_correction(rim_radius, flange_radius, angle):
    cosine = math.cos(angle)
    return math.prod([2, rim_radius, flange_radius, cosine])


def spoke_length(squared_terms, correction):
    return math.sqrt(squared_terms - correction)


def is_asymmetric(offset):
    return offset > 0


def validate_dimensions(rim, flange, offset, cross):
    if rim <= 0:
        raise ValueError("rim diameter must be positive")
    if flange <= 0:
        raise ValueError("flange diameter must be positive")
    if offset < 0:
        raise ValueError("offset must not be negative")
    if cross < 0:
        raise ValueError("cross number must not be negative")


def spokes(rim, flange, offset, cross):
    validate_dimensions(rim, flange, offset, cross)
    rim_radius = half(rim)
    flange_radius = half(flange)
    angle = cross_angle(cross)
    squared_terms = sum_of_squares(rim_radius, flange_radius, offset)
    correction = chord_correction(rim_radius, flange_radius, angle)
    length = spoke_length(squared_terms, correction)
    asymmetric = is_asymmetric(offset)
    return angle, length, asymmetric


def format_build(name, angle, length, asymmetric):
    degrees = math.degrees(angle)
    build = "asymmetric" if asymmetric else "symmetric"
    return f"{name}: {angle:.3f} rad ({degrees:.2f} deg), spoke {length:.1f} mm, {build}"


def main():
    best_name = None
    best_length = 0.0
    for name, rim, flange, offset, cross in BUILDS:
        angle, length, asymmetric = spokes(rim, flange, offset, cross)
        print(format_build(name, angle, length, asymmetric))
        if length > best_length:
            best_length = length
            best_name = name
    print(f"Longest spokes needed for {best_name}: {best_length:.1f} mm")


if __name__ == "__main__":
    main()

