IDEAL_LOW = 20
IDEAL_HIGH = 25


def elapsed(later, earlier):
    """Minutes between two clock readings of the same roast."""
    return later - earlier


def percent(fraction):
    return fraction * 100


def development_percent(total_time, development_time):
    """Share of the roast spent after first crack, as a percentage."""
    return percent(development_time / total_time)


def rise_rate(temperature, start, crack):
    """Degrees gained per minute on the way to first crack."""
    return temperature / elapsed(crack, start)


def is_ideal(development_ratio):
    if development_ratio < IDEAL_LOW:
        return False
    return development_ratio <= IDEAL_HIGH


def validate_session(start, crack, end, temperature):
    """Check that the roasting timeline and temperature make sense."""
    errors = []
    if crack <= start:
        errors.append("first crack must occur after the roast starts")
    if end <= crack:
        errors.append("the roast must end after first crack")
    if temperature <= 0:
        errors.append("temperature must be positive")
    return errors


def roast(start, crack, end, temperature):
    """Analyze one roasting session.

    Returns (total_time, development_ratio, rate_of_rise, ideal).
    """
    problems = validate_session(start, crack, end, temperature)
    if problems:
        raise ValueError("; ".join(problems))
    total_time = elapsed(end, start)
    development_time = elapsed(end, crack)
    development_ratio = development_percent(total_time, development_time)
    rate_of_rise = rise_rate(temperature, start, crack)
    ideal = is_ideal(development_ratio)
    return total_time, development_ratio, rate_of_rise, ideal


def verdict(development_ratio, ideal):
    if ideal:
        return "ideal"
    if development_ratio < IDEAL_LOW:
        return "off target (underdeveloped)"
    return "off target (overdeveloped)"


def format_report(name, total_time, development_ratio, rate_of_rise, ideal):
    """Build a one-line human readable summary of an analyzed roast."""
    return (
        "{0}: total {1:.1f} min, development {2:.1f}%, "
        "rate of rise {3:.1f} deg/min - {4}".format(
            name, total_time, development_ratio, rate_of_rise,
            verdict(development_ratio, ideal)
        )
    )


def analyze_batches(batches):
    """Analyze many named sessions and return reports plus the ideal count."""
    reports = []
    ideal_count = 0
    for name, start, crack, end, temperature in batches:
        try:
            total, ratio, rise, ideal = roast(start, crack, end, temperature)
        except ValueError as exc:
            reports.append("{0}: invalid session - {1}".format(name, exc))
            continue
        if ideal:
            ideal_count += 1
        reports.append(format_report(name, total, ratio, rise, ideal))
    return reports, ideal_count


def main():
    batches = [
        ("Ethiopia natural", 0, 8, 10, 400),
        ("Colombia washed", 0, 9, 12, 420),
        ("Sumatra wet hulled", 1, 7, 15, 430),
        ("Broken probe", 0, 5, 4, 390),
    ]
    reports, ideal_count = analyze_batches(batches)
    for line in reports:
        print(line)
    print("Ideal roasts: {0} of {1} ({2:.0f}%)".format(
        ideal_count, len(batches), percent(ideal_count / len(batches))
    ))


if __name__ == "__main__":
    main()

