import math

GRAVITY = 9.81
SAFE_LIMIT = 6.0


def _positive(name, value):
    """Return the value as a float, rejecting zero or negative input."""
    if value <= 0:
        raise ValueError(name + " must be greater than zero")
    return float(value)


def weight(mass):
    """Gravitational force pulling the jumper down, in newtons."""
    return GRAVITY * mass


def doubled_weight(mass):
    """Twice the weight, the numerator of the terminal velocity formula."""
    return 2 * weight(mass)


def squared(value):
    """The value multiplied by itself."""
    return value * value


def drag_density(density, drag):
    """Air density combined with the drag coefficient of the canopy."""
    return density * drag


def drag_denominator(density, area, drag):
    """Product of air density, cross sectional area and drag coefficient."""
    return area * drag_density(density, drag)


def terminal_velocity(mass, area, density, drag):
    """Steady descent rate once drag balances weight, in metres per second."""
    return math.sqrt(doubled_weight(mass) / drag_denominator(density, area, drag))


def half_mass(mass):
    """Half of the jumper mass, the coefficient of the kinetic energy."""
    return 0.5 * mass


def impact_energy(mass, velocity):
    """Kinetic energy carried into the ground, in joules."""
    return half_mass(mass) * squared(velocity)


def is_safe(velocity):
    """True when the descent rate is gentle enough to land on."""
    return velocity <= SAFE_LIMIT


def safety_margin(velocity):
    """How much slower than the safe limit the descent is."""
    return SAFE_LIMIT - velocity


def safe_drag_pressure(density, drag):
    """Drag force per square metre of canopy at the safe descent rate."""
    return squared(SAFE_LIMIT) * drag_density(density, drag)


def required_area(mass, density, drag):
    """Canopy area that brings the descent rate down to the safe limit."""
    return doubled_weight(mass) / safe_drag_pressure(density, drag)


def parachute(mass, area, density, drag):
    """Return terminal velocity, impact energy and the safe landing flag."""
    mass = _positive("mass", mass)
    area = _positive("area", area)
    density = _positive("density", density)
    drag = _positive("drag", drag)
    velocity = terminal_velocity(mass, area, density, drag)
    return velocity, impact_energy(mass, velocity), is_safe(velocity)


def format_report(label, velocity, energy, safe):
    """Build a one line summary of a single jump."""
    margin = safety_margin(velocity)
    verdict = "safe landing" if safe else "hard landing"
    template = "{}: descent {:.2f} mps, energy {:.1f} J, margin {:+.2f}, {}"
    return template.format(label, velocity, energy, margin, verdict)


def main():
    jumpers = [
        ("round canopy, 80 kg", 80, 45, 1.225, 1.5),
        ("round canopy, 110 kg", 110, 45, 1.225, 1.5),
        ("small reserve, 95 kg", 95, 18, 1.225, 1.4),
        ("high altitude drop", 80, 45, 0.65, 1.5),
    ]
    worst_energy = 0.0
    for label, mass, area, density, drag in jumpers:
        velocity, energy, safe = parachute(mass, area, density, drag)
        print(format_report(label, velocity, energy, safe))
        if energy > worst_energy:
            worst_energy = energy
        if not safe:
            needed = required_area(mass, density, drag)
            print("  enlarge canopy to {:.2f} m2, adding {:.2f} m2".format(
                needed, needed - area))
    print("worst impact energy: {:.1f} J".format(worst_energy))


if __name__ == "__main__":
    main()

