from decimal import Decimal, ROUND_DOWN

MOLAR_MASS_NACL = 58.44
VAN_T_HOFF_FACTOR = 2
PRESSURE_FACTOR = 0.0012
SEA_LEVEL_BOILING = 100
CENT = Decimal("0.01")


def truncate(value):
    trimmed = Decimal(str(value))
    return float(trimmed.quantize(CENT, ROUND_DOWN))


def validate_inputs(elevation, mass, volume, constant):
    if elevation < 0:
        raise ValueError("elevation must not be negative")
    if mass < 0:
        raise ValueError("solute mass must not be negative")
    if volume <= 0:
        raise ValueError("solvent volume must be greater than zero")
    if constant <= 0:
        raise ValueError("ebullioscopic constant must be greater than zero")


def pressure_drop(elevation):
    return elevation * PRESSURE_FACTOR


def baseline_boiling(elevation):
    drop = pressure_drop(elevation)
    return SEA_LEVEL_BOILING - drop


def moles_of_solute(mass):
    return mass / MOLAR_MASS_NACL


def molality(mass, volume):
    moles = moles_of_solute(mass)
    return moles / volume


def effective_molality(molal):
    return VAN_T_HOFF_FACTOR * molal


def boiling_elevation(constant, molal):
    effective = effective_molality(molal)
    return constant * effective


def final_boiling(baseline, delta):
    return baseline + delta


def boils_lower(final):
    return final < SEA_LEVEL_BOILING


def boiling(elevation, mass, volume, constant):
    validate_inputs(elevation, mass, volume, constant)
    raw_baseline = baseline_boiling(elevation)
    molal = molality(mass, volume)
    delta = boiling_elevation(constant, molal)
    raw_final = final_boiling(raw_baseline, delta)
    final = truncate(raw_final)
    return {
        "baseline": truncate(raw_baseline),
        "molality": truncate(molal),
        "final": final,
        "lower": boils_lower(final),
    }


def format_report(elevation, mass, volume, result):
    lines = ["Saltwater boiling point report"]
    lines.append("Elevation: {0} m".format(elevation))
    lines.append("Solution: {0} g of salt in {1} L".format(mass, volume))
    lines.append("Baseline boiling point: {0} C".format(result["baseline"]))
    lines.append("Molality: {0} mol/kg".format(result["molality"]))
    lines.append("Final boiling point: {0} C".format(result["final"]))
    if result["lower"]:
        verdict = "below the sea level boiling point"
    else:
        verdict = "at or above the sea level boiling point"
    lines.append("Verdict: boils " + verdict)
    return "\n".join(lines)


def main():
    elevation = 1000
    mass = 100
    volume = 2
    constant = 0.512
    result = boiling(elevation, mass, volume, constant)
    print(format_report(elevation, mass, volume, result))


if __name__ == "__main__":
    main()

