BOIL_TIME = 60
BOIL_DIVISOR = 280
UTILIZATION_SCALE = 75
HOPPY_THRESHOLD = 40


def _validate(ounces, alpha, volume, gravity):
    if ounces <= 0:
        raise ValueError("hop weight in ounces must be positive")
    if alpha <= 0:
        raise ValueError("alpha acid percentage must be positive")
    if volume <= 0:
        raise ValueError("batch volume in gallons must be positive")
    if gravity < 1:
        raise ValueError("original gravity must be at least 1.000")


def _gravity_excess(gravity):
    return gravity - 1


def _gravity_points(gravity):
    return _gravity_excess(gravity) * 10


def bigness_factor(gravity):
    return 1.65 - _gravity_points(gravity)


def boil_time_factor():
    return BOIL_TIME / BOIL_DIVISOR


def utilization(gravity):
    return bigness_factor(gravity) * boil_time_factor()


def _hop_mass(ounces, alpha):
    return ounces * alpha


def _hop_extract(ounces, alpha, gravity):
    return _hop_mass(ounces, alpha) * utilization(gravity)


def _scaled_extract(ounces, alpha, gravity):
    return _hop_extract(ounces, alpha, gravity) * UTILIZATION_SCALE


def _raw_units(ounces, alpha, volume, gravity):
    return _scaled_extract(ounces, alpha, gravity) / volume


def _tenths(value):
    return value * 10


def _truncate_tenths(value):
    return int(_tenths(value)) / 10


def _is_hoppy(units):
    return units > HOPPY_THRESHOLD


def bitterness(ounces, alpha, volume, gravity):
    _validate(ounces, alpha, volume, gravity)
    bigness = round(bigness_factor(gravity), 2)
    raw = _raw_units(ounces, alpha, volume, gravity)
    units = _truncate_tenths(raw)
    hoppy = _is_hoppy(units)
    return bigness, units, hoppy


def format_row(name, bigness, units, hoppy):
    label = "hoppy" if hoppy else "balanced"
    return f"{name}: bigness {bigness}, IBU {units}, {label}"


def summarize(recipes):
    lines = []
    strongest = None
    top = 0.0
    for name, ounces, alpha, volume, gravity in recipes:
        bigness, units, hoppy = bitterness(ounces, alpha, volume, gravity)
        lines.append(format_row(name, bigness, units, hoppy))
        if units > top:
            top = units
            strongest = name
    lines.append(f"Hoppiest batch: {strongest} at {top} IBU")
    return lines


def main():
    recipes = [
        ("Pale Ale", 2, 5, 5, 1.050),
        ("Double IPA", 6, 12, 5, 1.075),
        ("Mild", 1, 4, 5, 1.036),
    ]
    for line in summarize(recipes):
        print(line)


if __name__ == "__main__":
    main()

