text_nat:
FEET_PER_MILE = 5280


def feet_to_miles(altitude):
    """Convert an altitude in feet to an altitude in miles."""
    return altitude / FEET_PER_MILE


def base_glide_distance(altitude_miles, ratio):
    """Miles the airplane covers per mile of altitude lost, in still air."""
    return altitude_miles * ratio


def descent_hours(base_distance, speed):
    """Hours needed to fly the still-air glide at the given airspeed."""
    return base_distance / speed


def wind_penalty(wind, hours):
    """Ground miles lost to the headwind during the descent."""
    return wind * hours


def effective_distance(base_distance, penalty):
    """Ground distance actually available after the headwind is accounted for."""
    return base_distance - penalty


def is_reachable(actual_distance, distance):
    """True when the glide reaches at least as far as the runway."""
    return actual_distance >= distance


def margin(actual_distance, distance):
    """Miles of reserve (positive) or shortfall (negative) against the runway."""
    return actual_distance - distance


def validate_inputs(altitude, ratio, distance, wind, speed):
    """Reject inputs that make the glide computation meaningless."""
    if altitude < 0:
        raise ValueError("altitude must not be negative")
    if ratio <= 0:
        raise ValueError("glide ratio must be positive")
    if distance < 0:
        raise ValueError("distance to the runway must not be negative")
    if speed <= 0:
        raise ValueError("airspeed must be positive")
    if wind >= speed:
        raise ValueError("headwind must be smaller than airspeed")


def glide(altitude, ratio, distance, wind, speed):
    """Return the achievable glide distance in miles and whether the runway is reachable."""
    validate_inputs(altitude, ratio, distance, wind, speed)
    altitude_miles = feet_to_miles(altitude)
    base_distance = base_glide_distance(altitude_miles, ratio)
    hours = descent_hours(base_distance, speed)
    penalty = wind_penalty(wind, hours)
    actual_distance = effective_distance(base_distance, penalty)
    reachable = is_reachable(actual_distance, distance)
    return actual_distance, reachable


def format_report(altitude, ratio, distance, wind, speed):
    """Build a one line summary of a single engine-failure scenario."""
    actual_distance, reachable = glide(altitude, ratio, distance, wind, speed)
    reserve = margin(actual_distance, distance)
    verdict = "REACHABLE" if reachable else "TOO FAR"
    head = "{:>7.0f} ft, ratio {:>4.1f}, {:>5.1f} mi out".format(altitude, ratio, distance)
    tail = "wind {:>4.1f} kt at {:>5.1f} kt -> {:>6.2f} mi ({:+.2f}) {}".format(
        wind, speed, actual_distance, reserve, verdict
    )
    return " | ".join([head, tail])


def main():
    scenarios = [
        (10560, 9, 15, 20, 100),
        (10560, 9, 12, 20, 100),
        (5280, 12, 10, 0, 120),
        (21120, 17, 60, 35, 140),
    ]
    for scenario in scenarios:
        print(format_report(*scenario))
    reached = [s for s in scenarios if glide(*s)[1]]
    print("{} of {} scenarios make the runway".format(len(reached), len(scenarios)))


if __name__ == "__main__":
    main()

