"""Estimate the walking time needed to mow a rectangular lawn."""

from decimal import Decimal, ROUND_DOWN

OVERLAP_INCHES = 2
INCHES_PER_FOOT = 12
MAX_SESSION_MINUTES = 60


def usable_inches(deck):
    """Deck width minus the overlap kept between passes."""
    return deck - OVERLAP_INCHES


def to_feet(inches):
    """Convert a measurement in inches to feet."""
    return inches / INCHES_PER_FOOT


def truncate2(value):
    """Cut a float down to two decimal places without rounding up."""
    exact = Decimal(str(value))
    return float(exact.quantize(Decimal("0.01"), rounding=ROUND_DOWN))


def lawn_area(length, width):
    """Square footage of a rectangular lawn."""
    return length * width


def walking_distance(area, cut_width):
    """Feet walked while covering the area with the given cutting width."""
    return round(area / cut_width)


def mow_minutes(distance, speed):
    """Minutes spent walking the distance at the given pace."""
    return round(distance / speed, 2)


def fits_one_charge(minutes, battery):
    """True when the mower battery outlasts the job."""
    return minutes <= battery


def validate(length, width, deck, speed, battery):
    for value in (length, width, deck, speed, battery):
        if value <= 0:
            raise ValueError("all mowing inputs must be positive")
    if deck <= OVERLAP_INCHES:
        raise ValueError("deck must be wider than the overlap")


def mowing(length, width, deck, speed, battery):
    validate(length, width, deck, speed, battery)
    raw_width = to_feet(usable_inches(deck))
    cut_width = truncate2(raw_width)
    area = lawn_area(length, width)
    distance = walking_distance(area, cut_width)
    minutes = mow_minutes(distance, speed)
    one_charge = fits_one_charge(minutes, battery)
    return cut_width, distance, minutes, one_charge


def format_report(name, result):
    cut_width, distance, minutes, one_charge = result
    charge = "yes" if one_charge else "no"
    return (
        f"{name}: cut width {cut_width:.2f} ft, "
        f"distance {distance} ft, time {minutes:.2f} min, "
        f"one charge: {charge}"
    )


def main():
    lawns = [
        ("Front yard", 100, 50, 22, 150, 45),
        ("Back yard", 120, 80, 30, 160, 45),
        ("Side strip", 60, 25, 22, 150, 45),
    ]
    times = []
    for name, length, width, deck, speed, battery in lawns:
        result = mowing(length, width, deck, speed, battery)
        times.append(result[2])
        print(format_report(name, result))
    grand_total = sum(times)
    print(f"Total mowing time: {grand_total:.2f} min")
    if grand_total > MAX_SESSION_MINUTES:
        print("Split the work across more than one session.")
    else:
        print("All lawns fit into a single session.")


if __name__ == "__main__":
    main()

