def kilobits(duration, rate):
    """Total kilobits produced by a stream of `rate` kbps over `duration` seconds."""
    return duration * rate


def megabytes(total_kilobits):
    """Convert kilobits to megabytes (8000 kilobits per megabyte)."""
    return total_kilobits / 8000.0


def compress(size_mb):
    """Apply the ten percent compression reduction."""
    return size_mb * 0.9


def to_minutes(seconds):
    """Express a duration in seconds as a number of minutes."""
    return seconds / 60.0


def validate(duration, bitrate, audio):
    if duration <= 0:
        raise ValueError("duration must be a positive number of seconds")
    if bitrate <= 0:
        raise ValueError("video bitrate must be a positive number of kbps")
    if audio < 0:
        raise ValueError("audio bitrate cannot be negative")


def filesize(duration, bitrate, audio):
    validate(duration, bitrate, audio)
    video_kilobits = kilobits(duration, bitrate)
    audio_kilobits = kilobits(duration, audio)
    combined_kilobits = sum([video_kilobits, audio_kilobits])
    video_mb = megabytes(video_kilobits)
    audio_mb = megabytes(audio_kilobits)
    total_mb = megabytes(combined_kilobits)
    if total_mb > 500:
        total_mb = compress(total_mb)
    return [round(total_mb, 4), round(video_mb, 4), round(audio_mb, 4)]


def parse_spec(text):
    """Read a 'duration,video_bitrate,audio_bitrate' specification."""
    parts = text.split(",")
    if len(parts) != 3:
        raise ValueError("a spec needs exactly three comma separated values")
    duration = float(parts[0].strip())
    bitrate = float(parts[1].strip())
    audio = float(parts[2].strip())
    return duration, bitrate, audio


def format_report(duration, sizes):
    final_mb, video_mb, audio_mb = sizes
    uncompressed_mb = sum([video_mb, audio_mb])
    minutes = to_minutes(duration)
    lines = ["length: {:.2f} min".format(minutes)]
    lines.append("video: {:.2f} MB".format(video_mb))
    lines.append("audio: {:.2f} MB".format(audio_mb))
    lines.append("final: {:.2f} MB".format(final_mb))
    if final_mb < uncompressed_mb:
        lines.append("compression saved {:.2f} MB".format(uncompressed_mb - final_mb))
    return "\n".join(lines)


def main():
    specs = ["600, 4000, 128", "3600, 6000, 192", "120, 800, 64"]
    for spec in specs:
        duration, bitrate, audio = parse_spec(spec)
        sizes = filesize(duration, bitrate, audio)
        print(sizes)
        print(format_report(duration, sizes))
        print("=" * 32)


if __name__ == "__main__":
    main()

