STORAGE_RATE = 0.02
DISCOUNT_RATE = 0.015
DISCOUNT_THRESHOLD = 50
RETRIEVAL_RATE = 0.0005
MINIMUM_FEE = 5.0


def storage_cost(gigabytes):
    """Cost of storing the given amount of data for one month."""
    if gigabytes > DISCOUNT_THRESHOLD:
        rate = DISCOUNT_RATE
    else:
        rate = STORAGE_RATE
    return round(gigabytes * rate, 2)


def retrieval_cost(retrievals):
    """Cost of the retrieval requests made during the month."""
    return round(retrievals * RETRIEVAL_RATE, 2)


def minimum_adjustment(subtotal, final):
    """Amount added to the subtotal to reach the minimum monthly fee."""
    return round(final - subtotal, 2)


def bill(gigabytes, retrievals):
    """Return [storage cost, retrieval cost, amount actually billed]."""
    if gigabytes < 0:
        raise ValueError("stored data cannot be negative")
    if retrievals < 0:
        raise ValueError("retrieval count cannot be negative")
    stored = storage_cost(gigabytes)
    fetched = retrieval_cost(retrievals)
