CONGESTION_THRESHOLD = 300
SECONDS_PER_MINUTE = 60.0


def _validate(people, capacity, time):
    """Reject inputs that cannot describe a real boarding queue."""
    if people < 0:
        raise ValueError("people cannot be negative")
    if capacity <= 0:
        raise ValueError("capacity must be a positive number of passengers")
    if time < 0:
        raise ValueError("round trip time cannot be negative")


def _full_trips(people, capacity):
    """Number of trips that leave with a completely full car."""
    return people // capacity


def _remaining(people, capacity):
    """People left for the final, partly filled trip."""
    return people % capacity


def _trip_wait(full_trips, time):
    """Seconds the last person waits: only the completed round trips count."""
    return full_trips * float(time)


def _is_congested(wait_time):
    return wait_time > CONGESTION_THRESHOLD


def _total_trips(full_trips, remaining):
    """Add the final trip, which the last person rides but does not wait for."""
    if remaining > 0:
        return full_trips + 1
    return full_trips


def _minutes(wait_time):
    return wait_time / SECONDS_PER_MINUTE


def boarding(people, capacity, time):
    _validate(people, capacity, time)
    full_trips = _full_trips(people, capacity)
    wait_time = _trip_wait(full_trips, time)
    congested = _is_congested(wait_time)
    return [full_trips, wait_time, congested]


def describe(people, capacity, time):
    """Render one lobby scenario as a human readable line."""
    full_trips, wait_time, congested = boarding(people, capacity, time)
    remaining = _remaining(people, capacity)
    total_trips = _total_trips(full_trips, remaining)
    status = "CONGESTED" if congested else "clear"
    header = f"{people} waiting, cars of {capacity}, {time}s round trip"
    detail = f"{full_trips} full trips, then {remaining} on trip {total_trips}"
    timing = f"last person waits {wait_time:.1f}s ({_minutes(wait_time):.1f} min)"
    return f"{header}: {detail}; {timing}; lobby {status}"


def main():
    scenarios = [(45, 10, 60), (120, 8, 75), (7, 12, 45), (500, 15, 90)]
    worst_wait = 0.0
    worst_label = "none"
    for people, capacity, time in scenarios:
        print(describe(people, capacity, time))
        wait_time = boarding(people, capacity, time)[1]
        if wait_time > worst_wait:
            worst_wait = wait_time
            worst_label = f"{people} people at capacity {capacity}"
    print(f"Worst case: {worst_label} with a {worst_wait:.1f}s wait")


if __name__ == "__main__":
    main()

