CALORIES_PER_CUP = 335.0
KCAL_PER_KG = 30.0
BASE_KCAL = 70.0
PUPPY_PREMIUM = 200.0
PUPPY_AGE = 1


def metabolic_need(weight):
    return weight * KCAL_PER_KG


def resting_energy(weight):
    if weight <= 0:
        raise ValueError("weight must be positive")
    return metabolic_need(weight) + BASE_KCAL


def active_need(resting, activity):
    return resting * activity


def daily_need(resting, age, activity):
    need = active_need(resting, activity)
    if age < PUPPY_AGE:
        return need + PUPPY_PREMIUM
    return need


def cups_needed(daily):
    return daily / CALORIES_PER_CUP


def ration(weight, age, activity):
    if age < 0:
        raise ValueError("age must not be negative")
    if activity <= 0:
        raise ValueError("activity multiplier must be positive")
    resting = resting_energy(weight)
    daily = daily_need(resting, age, activity)
    cups = cups_needed(daily)
    return [resting, daily, cups]


def meals_per_day(age):
    if age < 0.5:
        return 4
    if age < PUPPY_AGE:
        return 3
    return 2


def portion_size(cups, meals):
    return cups / meals


def describe(name, weight, age, activity):
    resting, daily, cups = ration(weight, age, activity)
    meals = meals_per_day(age)
    per_meal = portion_size(cups, meals)
    if age < PUPPY_AGE:
        stage = "puppy"
    else:
        stage = "adult"
    lines = ["{0} ({1}, {2} kg, {3} yr)".format(name, stage, weight, age)]
    lines.append("  resting energy: {0:.0f} kcal".format(resting))
    lines.append("  daily need:     {0:.0f} kcal".format(daily))
    lines.append("  food:           {0:.2f} cups".format(cups))
    lines.append("  {0} meals of {1:.2f} cups".format(meals, per_meal))
    return "\n".join(lines)


def shopping_days(cups_per_day, bag_cups):
    if bag_cups <= 0:
        raise ValueError("bag size must be positive")
    return int(bag_cups / cups_per_day)


def main():
    kennel = [
        ("Rex", 20, 3, 1.5),
        ("Pip", 4.5, 0.4, 1.8),
        ("Bruno", 35, 7, 1.2),
    ]
    bag_cups = 60
    daily_cups = []
    for name, weight, age, activity in kennel:
        print(describe(name, weight, age, activity))
        daily_cups.append(ration(weight, age, activity)[2])
    total_cups = sum(daily_cups)
    print("kennel total: {0:.2f} cups per day".format(total_cups))
    lasts = shopping_days(total_cups, bag_cups)
    print("a {0}-cup bag lasts {1} full days".format(bag_cups, lasts))
    if lasts < 7:
        print("order more food this week")


if __name__ == "__main__":
    main()

