SAP_OLIVE = 0.134
SAP_COCONUT = 0.19


def olive_lye(olive):
    """Grams of lye consumed by the olive oil."""
    return olive * SAP_OLIVE


def coconut_lye(coconut):
    """Grams of lye consumed by the coconut oil."""
    return coconut * SAP_COCONUT


def total_lye(olive, coconut):
    """Grams of lye the whole batch of oils needs."""
    return olive_lye(olive) + coconut_lye(coconut)


def solution_mass(olive, coconut, lye):
    """Mass of the finished lye solution at the given concentration."""
    return total_lye(olive, coconut) / lye


def water(olive, coconut, lye):
    """Water required to dilute the lye to the given concentration."""
    return solution_mass(olive, coconut, lye) - total_lye(olive, coconut)


def total_oil(olive, coconut):
    """Combined mass of the oils."""
    return olive + coconut


def validate_batch(olive, coconut, lye):
    """Reject masses and concentrations that cannot describe a real batch."""
    if olive < 0:
        raise ValueError("mass of olive oil cannot be negative")
    if coconut < 0:
        raise ValueError("mass of coconut oil cannot be negative")
    if total_oil(olive, coconut) <= 0:
        raise ValueError("at least one oil must have a positive mass")
    if lye <= 0:
        raise ValueError("lye concentration must be greater than zero")
    if lye > 1:
        raise ValueError("lye concentration must be a decimal at most 1")


def saponification(olive, coconut, lye):
    """Return [olive lye, coconut lye, water] for a soap batch in grams."""
    validate_batch(olive, coconut, lye)
    return [olive_lye(olive), coconut_lye(coconut), water(olive, coconut, lye)]


def total_batch_mass(olive, coconut, lye):
    """Total mass of the finished raw soap mixture."""
    validate_batch(olive, coconut, lye)
    return total_oil(olive, coconut) + solution_mass(olive, coconut, lye)


def format_recipe(olive, coconut, lye):
    """Build a human readable recipe listing every component in grams."""
    validate_batch(olive, coconut, lye)
    lines = ["Lye solution strength: {0:.1%}".format(lye)]
    lines.append("Olive oil: {0:.1f} g -> lye {1:.2f} g".format(olive, olive_lye(olive)))
    lines.append("Coconut oil: {0:.1f} g -> lye {1:.2f} g".format(coconut, coconut_lye(coconut)))
    lines.append("Water: {0:.2f} g".format(water(olive, coconut, lye)))
    lines.append("Batch total: {0:.2f} g".format(total_batch_mass(olive, coconut, lye)))
    return "\n".join(lines)


def scale_factor(olive, coconut, lye, target_mass):
    """Ratio by which the oils must grow or shrink to hit target_mass."""
    if target_mass <= 0:
        raise ValueError("target mass must be positive")
    return target_mass / total_batch_mass(olive, coconut, lye)


def scale_batch(olive, coconut, lye, target_mass):
    """Scale the oil masses so the finished batch weighs target_mass grams."""
    factor = scale_factor(olive, coconut, lye, target_mass)
    return [oil * factor for oil in (olive, coconut)]


def main():
    print(saponification(500, 200, 0.3))
    print(format_recipe(500, 200, 0.3))
    olive, coconut = scale_batch(500, 200, 0.3, 500.0)
    print("\nScaled to a 500 g batch:")
    print(format_recipe(olive, coconut, 0.3))
    strong = water(300, 300, 0.4)
    weak = water(300, 300, 0.25)
    print("\nA 25% solution needs {0:.2f} g more water.".format(weak - strong))


if __name__ == "__main__":
    main()

