def _check_inputs(temperature, humidity, wind):
    """Reject readings that cannot come from a real sensor."""
    if humidity<0:
        raise ValueError("relative humidity cannot be negative")
    if humidity>100:
        raise ValueError("relative humidity cannot exceed 100 percent")
    if wind<0:
        raise ValueError("wind speed cannot be negative")
    return float(temperature), float(humidity), float(wind)


def transpiration(temperature, humidity, wind):
    """Return [rate, high_stress] for the given ambient conditions."""
    temperature, humidity, wind=_check_inputs(temperature, humidity, wind)
    base=(
        temperature*0.2
    )
    drop=(
        humidity*0.05
    )
    lift=(
        wind*0.1
    )
    net=(
        base-drop
    )
    rate=(
        net+lift
    )
    if rate<0:
        rate=0.0
    rate=round(rate, 6)
    high_stress=(
        rate>4
    )
    return [rate, high_stress]


def format_report(label, temperature, humidity, wind):
    """Build a one-line summary of a single sensor reading."""
    rate, high_stress=transpiration(temperature, humidity, wind)
    status="HIGH STRESS" if high_stress else "normal"
    return f"{label:<8} {temperature:>5.1f}C {humidity:>5.1f}% {wind:>4.1f}m/s -> {rate:>5.2f} ({status})"


def average_rate(measurements):
    """Mean transpiration rate over a list of (temperature, humidity, wind)."""
    count=len(measurements)
    if count==0:
        return 0.0
    total=0.0
    for temperature, humidity, wind in measurements:
        rate=transpiration(temperature, humidity, wind)[0]
        total+=rate
    mean=(
        total/count
    )
    return round(mean, 6)


def count_stressed(measurements):
    """How many readings put the plant under high stress."""
    stressed=0
    for temperature, humidity, wind in measurements:
        if transpiration(temperature, humidity, wind)[1]:
            stressed+=1
    return stressed


def main():
    readings=[
        ("dawn", 14, 85, 0.5),
        ("morning", 22, 60, 2.0),
        ("noon", 30, 40, 5.0),
        ("afternoon", 34, 25, 7.5),
        ("dusk", 19, 75, 1.0),
    ]
    for label, temperature, humidity, wind in readings:
        print(format_report(label, temperature, humidity, wind))
    measurements=[reading[1:] for reading in readings]
    print(f"average rate: {average_rate(measurements):.2f}")
    stressed=count_stressed(measurements)
    fraction=(
        stressed/len(measurements)
    )
    percent=(
        fraction*100.0
    )
    print(f"high stress readings: {stressed} ({percent:.0f}% of the day)")
    if percent>50.0:
        print("irrigation strongly recommended")


if __name__=="__main__":
    main()

