TOTAL_STAFF_POINTS = 100
MINIMUM_HOURLY_TIP = 2.0
TOP_UP_AMOUNT = 10.0

ROLE_MULTIPLIERS = {
    "server": 1.5,
    "bartender": 1.25,
    "host": 1.0,
    "busser": 0.75,
}


def validate_shift(hours, tips, points):
    if hours <= 0:
        raise ValueError("hours must be positive")
    if tips < 0:
        raise ValueError("tips cannot be negative")
    if points <= 0:
        raise ValueError("points multiplier must be positive")


def worker_points(hours, points):
    return hours * points


def point_value(tips):
    return tips / TOTAL_STAFF_POINTS


def base_share(earned_points, value):
    return earned_points * value


def hourly_rate(share, hours):
    return share / hours


def needs_top_up(share, hours):
    return hourly_rate(share, hours) < MINIMUM_HOURLY_TIP


def topped_up(share):
    return share + TOP_UP_AMOUNT


def gratuity(hours, tips, points):
    validate_shift(hours, tips, points)
    earned = worker_points(hours, points)
    share = base_share(earned, point_value(tips))
    final = share
    if needs_top_up(share, hours):
        final = topped_up(share)
    return [earned, share, final]


def gratuity_for_role(hours, tips, role):
    key = role.strip().lower()
    if key not in ROLE_MULTIPLIERS:
        raise KeyError("unknown role: " + role)
    return gratuity(hours, tips, ROLE_MULTIPLIERS[key])


def format_line(name, role, result):
    earned, share, final = result
    parts = ["{:<8} {:<10} {:>7.2f} pts  base ${:>7.2f}".format(name, role, earned, share)]
    if final > share:
        parts.append("top up ${:.2f}".format(TOP_UP_AMOUNT))
    parts.append("paid ${:.2f}".format(final))
    return "  ".join(parts)


def shift_report(staff, tips):
    lines = []
    payouts = []
    for name, role, hours in staff:
        result = gratuity_for_role(hours, tips, role)
        payouts.append(result[2])
        lines.append(format_line(name, role, result))
    lines.append("Total paid out: ${:.2f} of ${:.2f} collected".format(sum(payouts), tips))
    return lines


def main():
    crew = [
        ("Ada", "server", 8),
        ("Bo", "bartender", 6),
        ("Cy", "host", 4),
        ("Di", "busser", 3),
    ]
    for line in shift_report(crew, 500.0):
        print(line)
    print("Slow night server:", gratuity(8, 100, 1.5))


if __name__ == "__main__":
    main()

