GRAVITY = 9.8
FORCE_LIMIT = 2000.0


def weight(mass):
    """Downward force of the jumper hanging at rest, in newtons."""
    return mass * GRAVITY


def static_stretch(mass, stiffness):
    """Cord extension once the jumper hangs motionless."""
    return weight(mass) / stiffness


def dynamic_stretch(mass, stiffness):
    """Extension at the lowest point of the fall."""
    return 2 * static_stretch(mass, stiffness)


def total_fall(length, stretch):
    """Distance travelled from the platform to the lowest point."""
    return length + stretch


def peak_force(stretch, stiffness):
    """Force felt by the jumper when the cord is fully stretched."""
    return stretch * stiffness


def is_extreme(force):
    """True when the peak force passes the comfort limit."""
    return force > FORCE_LIMIT


def safety_factor(force):
    """Fraction of the comfort limit used up by the jump."""
    return force / FORCE_LIMIT


def clearance(tower_height, fall):
    """Metres left between the lowest point of the jump and the ground."""
    return tower_height - fall


def bungee(mass, length, stiffness):
    """Return [dynamic stretch, total fall, peak force, extreme flag]."""
    if mass <= 0:
        raise ValueError("mass must be positive")
    if length <= 0:
        raise ValueError("cord length must be positive")
    if stiffness <= 0:
        raise ValueError("stiffness must be positive")
    stretch = dynamic_stretch(mass, stiffness)
    fall = total_fall(length, stretch)
    force = peak_force(stretch, stiffness)
    return [stretch, fall, force, is_extreme(force)]


def describe(mass, length, stiffness):
    """Build a one-line human readable report for a single jump."""
    stretch, fall, force, extreme = bungee(mass, length, stiffness)
    verdict = "EXTREME" if extreme else "ok"
    load = safety_factor(force)
    return (
        "{0:.0f}kg on a {1:.0f}m cord of {2:.0f}N/m: stretch {3:.2f}m, "
        "fall {4:.2f}m, peak {5:.1f}N ({6:.0%} of limit), {7}"
    ).format(mass, length, stiffness, stretch, fall, force, load, verdict)


def main():
    jumps = [
        (75, 20, 200),
        (110, 25, 150),
        (55, 30, 120),
    ]
    tower = 40.0
    for mass, length, stiffness in jumps:
        print(describe(mass, length, stiffness))
        fall = bungee(mass, length, stiffness)[1]
        gap = clearance(tower, fall)
        if gap < 5.0:
            print("  WARNING: only {0:.2f}m of clearance".format(gap))
        else:
            print("  clearance {0:.2f}m below a {1:.0f}m tower".format(gap, tower))


if __name__ == "__main__":
    main()

