MAX_OCCUPANCY = 2
SECONDS_PER_MINUTE = 60
UNDERUTILIZED_THRESHOLD = 0.5


def validate_inputs(speed, steps, occupancy):
    """Reject escalator parameters that cannot describe a real installation."""
    if speed <= 0:
        raise ValueError("speed must be a positive number of steps per second")
    if steps <= 0:
        raise ValueError("steps must be a positive count of visible steps")
    if occupancy <= 0:
        raise ValueError("occupancy must be positive passengers per step")
    if occupancy > MAX_OCCUPANCY:
        raise ValueError("occupancy cannot exceed two passengers per step")


def passengers_per_second(speed, occupancy):
    """Steps arriving each second multiplied by the people riding them."""
    return speed * occupancy


def passengers_per_minute(speed, occupancy):
    """Throughput over a full minute of running at the given loading."""
    return passengers_per_second(speed, occupancy) * SECONDS_PER_MINUTE


def journey_seconds(steps, speed):
    """Time a passenger spends on the visible part of the escalator."""
    return steps / speed


def flag_level(maximum):
    """Throughput below which an escalator counts as underutilized."""
    return maximum * UNDERUTILIZED_THRESHOLD


def is_underutilized(actual, maximum):
    """True when actual flow falls under half the theoretical maximum."""
    return actual < flag_level(maximum)


def escalator(speed, steps, occupancy):
    """Return [journey time, actual passengers/minute, underutilized flag]."""
    validate_inputs(speed, steps, occupancy)
    maximum = passengers_per_minute(speed, MAX_OCCUPANCY)
    actual = passengers_per_minute(speed, occupancy)
    journey_time = journey_seconds(steps, speed)
    underutilized = is_underutilized(actual, maximum)
    return [journey_time, actual, underutilized]


def utilization_ratio(occupancy):
    """Fraction of the maximum loading that the passengers actually use."""
    return occupancy / MAX_OCCUPANCY


def utilization_percent(occupancy):
    """Utilization ratio expressed as a percentage."""
    return utilization_ratio(occupancy) * 100


def unused_occupancy(occupancy):
    """Places left free on every step."""
    return MAX_OCCUPANCY - occupancy


def spare_capacity(speed, occupancy):
    """Passengers per minute that could still be carried at full loading."""
    unused = unused_occupancy(occupancy)
    return passengers_per_minute(speed, unused)


def describe(name, speed, steps, occupancy):
    """Build a one-line human readable report for a single escalator."""
    journey_time, actual, underutilized = escalator(speed, steps, occupancy)
    percent = utilization_percent(occupancy)
    spare = spare_capacity(speed, occupancy)
    status = "UNDERUTILIZED" if underutilized else "healthy"
    parts = [
        f"{name}: journey {journey_time:.1f} s",
        f"throughput {actual:.1f} pax/min",
        f"utilization {percent:.0f}%",
        f"spare {spare:.1f} pax/min",
        status,
    ]
    return " | ".join(parts)


def main():
    fleet = [
        ("Mall north", 2, 60, 0.8),
        ("Metro exit A", 0.75, 45, 1.6),
        ("Airport pier", 1.5, 90, 1.0),
    ]
    busiest_name = None
    busiest_flow = 0.0
    flagged = []
    for name, speed, steps, occupancy in fleet:
        print(describe(name, speed, steps, occupancy))
        result = escalator(speed, steps, occupancy)
        actual = result[1]
        if actual > busiest_flow:
            busiest_flow = actual
            busiest_name = name
        if result[2]:
            flagged.append(name)
    print(f"Busiest: {busiest_name} at {busiest_flow:.1f} pax/min")
    print(f"Flagged as underutilized: {len(flagged)} of {len(fleet)}")


if __name__ == "__main__":
    main()

