def _validate(characters, time, errors):
    if characters <= 0:
        raise ValueError("characters must be a positive number")
    if time <= 0:
        raise ValueError("time must be a positive number of seconds")
    if errors < 0:
        raise ValueError("errors cannot be negative")
    if errors > characters:
        raise ValueError("errors cannot exceed the characters typed")


def gross_wpm(characters, time):
    words = characters
    words /= 5
    words *= 60
    words /= time
    return words


def error_penalty(errors):
    penalty = errors
    penalty *= 2
    return penalty


def accuracy_percent(characters, errors):
    correct = characters
    correct -= errors
    correct /= characters
    correct *= 100
    return correct


def typing(characters, time, errors):
    _validate(characters, time, errors)
    gross = gross_wpm(characters, time)
    net = gross
    net -= error_penalty(errors)
    if net < 0:
        net = 0.0
    return [gross, net, accuracy_percent(characters, errors)]


def grade(net_wpm):
    if net_wpm >= 70:
        return "expert"
    if net_wpm >= 50:
        return "proficient"
    if net_wpm >= 30:
        return "average"
    return "beginner"


def format_report(label, characters, time, errors):
    gross, net, accuracy = typing(characters, time, errors)
    lines = [label]
    lines.append("  duration     : {0:.2f} min".format(time / 60))
    lines.append("  gross wpm    : {0:.1f}".format(gross))
    lines.append("  net wpm      : {0:.1f}".format(net))
    lines.append("  accuracy     : {0:.1f}%".format(accuracy))
    lines.append("  skill level  : " + grade(net))
    return "\n".join(lines)


def best_run(runs):
    scored = [(typing(*run[1:])[1], run[0]) for run in runs]
    return max(scored)


def main():
    runs = [
        ("Warm-up", 300, 60, 3),
        ("Timed drill", 1240, 120, 11),
        ("Sloppy sprint", 180, 45, 20),
    ]
    for run in runs:
        print(format_report(*run))
        print()
    net, label = best_run(runs)
    print("Best run: {0} with {1:.1f} net wpm".format(label, net))


if __name__ == "__main__":
    main()

