DECELERATION = 3.0
MINIMUM_PHASE = 4.0

def doubled_deceleration():
    """Twice the assumed deceleration rate."""
    return 2 * DECELERATION

def validate(speed, width, perception):
    """Reject inputs that cannot describe a real intersection approach."""
    if speed <= 0:
        raise ValueError("approach speed must be positive")
    if width <= 0:
        raise ValueError("intersection width must be positive")
    if perception < 0:
        raise ValueError("perception time cannot be negative")

def braking_time(speed):
    """Time absorbed by braking from the approach speed."""
    return speed / doubled_deceleration()

def yellow_time(speed, perception):
    """Perception time plus the braking time."""
    return perception + braking_time(speed)

def red_clearance(speed, width):
    """Time needed to traverse the intersection at the approach speed."""
    return width / speed

def phase_total(yellow, red):
    """Combined phase length, never shorter than the allowed minimum."""
    return max(MINIMUM_PHASE, yellow + red)

def timing(speed, width, perception):
    validate(speed, width, perception)
    yellow = yellow_time(speed, perception)
    red = red_clearance(speed, width)
    return [yellow, red, phase_total(yellow, red)]

def format_phase(phase):
    """Render a computed phase as aligned, human readable lines."""
    labels = ["yellow", "red clearance", "total phase"]
    lines = []
    for label, value in zip(labels, phase):
        padded = label.rjust(13)
        lines.append("{0}: {1:5.2f} s".format(padded, value))
    return "\n".join(lines)

def report(approaches):
    """Summarise several approaches and flag the ones held at the minimum."""
    clamped = []
    for speed, width, perception in approaches:
        phase = timing(speed, width, perception)
        natural = sum(phase[0:2])
        print("speed {0} m/s, width {1} m, perception {2} s".format(
            speed, width, perception))
        print(format_phase(phase))
        if phase[2] > natural:
            clamped.append(speed)
            print("  raised to the four second minimum")
        print("")
    print("approaches held at the minimum: {0} of {1}".format(
        len(clamped), len(approaches)))

def main():
    approaches = [
        (12.0, 24.0, 1.0),
        (20.0, 18.0, 1.5),
        (8.0, 10.0, 0.8),
        (25.0, 30.0, 2.0),
    ]
    report(approaches)
    fastest = max(approaches, key=lambda item: item[0])
    slowest = min(approaches, key=lambda item: item[0])
    fast_total = timing(*fastest)[2]
    slow_total = timing(*slowest)[2]
    print("phase spread between fastest and slowest: {0:.2f} s".format(
        fast_total - slow_total))

if __name__ == "__main__":
    main()

