GRAVITY = 9.8
TAKEOFF_SPEED = 60.0
MAX_RUNWAY = 2000.0


def validate(weight, thrust, drag):
    """Reject inputs that cannot describe a real takeoff roll."""
    if weight <= 0:
        raise ValueError("weight must be a positive number of kilograms")
    if thrust <= 0:
        raise ValueError("thrust must be a positive number of newtons")
    if drag < 0:
        raise ValueError("drag factor cannot be negative")


def weight_force(weight):
    """Downward force of the aircraft in newtons."""
    return weight * GRAVITY


def resistance(weight, drag):
    """Combined aerodynamic and rolling resistance in newtons."""
    return weight_force(weight) * drag


def net_force(thrust, weight, drag):
    """Force left over to accelerate the aircraft."""
    return thrust - resistance(weight, drag)


def acceleration(net, weight):
    """Constant acceleration along the runway."""
    return net / weight


def roll_time(accel):
    """Seconds needed to reach takeoff speed."""
    return TAKEOFF_SPEED / accel


def mean_speed():
    """Average speed of a uniform acceleration from a standstill."""
    return TAKEOFF_SPEED / 2


def distance_for(accel):
    """Ground roll covered before rotation."""
    return mean_speed() * roll_time(accel)


def exceeds_runway(distance):
    return distance > MAX_RUNWAY


def takeoff(weight, thrust, drag):
    validate(weight, thrust, drag)
    net = net_force(thrust, weight, drag)
    if net <= 0:
        raise ValueError("thrust is too low to overcome drag")
    accel = acceleration(net, weight)
    distance = round(distance_for(accel), 2)
    insufficient = exceeds_runway(distance)
    return [net, distance, insufficient]


def margin_note(distance):
    return "cleared, margin {0:.0f} m".format(MAX_RUNWAY - distance)


def describe(name, weight, thrust, drag):
    """Build a one line report for a single aircraft configuration."""
    net, distance, insufficient = takeoff(weight, thrust, drag)
    seconds = roll_time(acceleration(net, weight))
    if insufficient:
        verdict = "INSUFFICIENT RUNWAY"
    else:
        verdict = margin_note(distance)
    return "{0:<12} net {1:>10.1f} N  roll {2:>8.2f} m  {3:>5.1f} s  {4}".format(
        name, net, distance, seconds, verdict)


def main():
    fleet = [
        ("Trainer", 1200, 6000, 0.04),
        ("Regional", 50000, 150000, 0.05),
        ("Freighter", 300000, 900000, 0.06),
        ("Overloaded", 400000, 700000, 0.08),
    ]
    for name, weight, thrust, drag in fleet:
        print(describe(name, weight, thrust, drag))
    grounded = [row[0] for row in fleet if takeoff(*row[1:])[2]]
    if grounded:
        print("Needs a longer runway: " + ", ".join(grounded))
    else:
        print("All configurations depart within {0:.0f} m".format(MAX_RUNWAY))


if __name__ == "__main__":
    main()

