def validate(capacity, price, sold):
    """Check that the ticketing inputs describe a possible event."""
    if capacity <= 0:
        raise ValueError("capacity must be positive")
    if price < 0:
        raise ValueError("price cannot be negative")
    if sold < 0:
        raise ValueError("sold cannot be negative")
    if sold > capacity:
        raise ValueError("sold cannot exceed capacity")


def vip_count(sold):
    """Twenty percent of the sold tickets are VIP tickets."""
    return int(sold * 0.2)


def standard_count(sold):
    """The tickets that are not VIP are sold at the base price."""
    return sold - vip_count(sold)


def vip_price(price):
    """VIP tickets carry a fifty percent premium over the base price."""
    return price * 1.5


def vip_revenue(price, sold):
    return vip_count(sold) * vip_price(price)


def standard_revenue(price, sold):
    return standard_count(sold) * price


def total_revenue(price, sold):
    return vip_revenue(price, sold) + standard_revenue(price, sold)


def occupancy_rate(capacity, sold):
    return sold / capacity


def is_underperforming(rate):
    return rate < 0.6


def as_percent(rate):
    return rate * 100


def ticketing(capacity, price, sold):
    validate(capacity, price, sold)
    revenue = total_revenue(price, sold)
    occupancy = occupancy_rate(capacity, sold)
    flag = is_underperforming(occupancy)
    return [float(revenue), occupancy, flag]


def breakdown(capacity, price, sold):
    """Return a dictionary describing every component of the sale."""
    revenue, occupancy, flag = ticketing(capacity, price, sold)
    return {
        "vip_tickets": vip_count(sold),
        "standard_tickets": standard_count(sold),
        "vip_revenue": vip_revenue(price, sold),
        "standard_revenue": standard_revenue(price, sold),
        "total_revenue": revenue,
        "occupancy": occupancy,
        "underperforming": flag,
    }


def format_report(name, capacity, price, sold):
    data = breakdown(capacity, price, sold)
    percent = as_percent(data["occupancy"])
    status = "UNDERPERFORMING" if data["underperforming"] else "healthy"
    lines = ["Event: {}".format(name)]
    lines.append("  VIP tickets     : {:d} @ {:.2f}".format(data["vip_tickets"], vip_price(price)))
    lines.append("  Standard tickets: {:d} @ {:.2f}".format(data["standard_tickets"], price))
    lines.append("  VIP revenue     : {:.2f}".format(data["vip_revenue"]))
    lines.append("  Standard revenue: {:.2f}".format(data["standard_revenue"]))
    lines.append("  Total revenue   : {:.2f}".format(data["total_revenue"]))
    lines.append("  Occupancy       : {:.1f}% ({})".format(percent, status))
    return "\n".join(lines)


def main():
    events = [
        ("Summer Gala", 1000, 50, 800),
        ("Winter Recital", 500, 40, 240),
        ("Jazz Night", 300, 65, 300),
    ]
    best_revenue = 0.0
    best_name = ""
    for name, capacity, price, sold in events:
        print(format_report(name, capacity, price, sold))
        revenue = ticketing(capacity, price, sold)[0]
        if revenue > best_revenue:
            best_revenue = revenue
            best_name = name
    print("Top grossing event: {} ({:.2f})".format(best_name, best_revenue))


if __name__ == "__main__":
    main()

