import math

FIRST_FLUSH_FRACTION=0.05
TANK_CAPACITY_LITERS=5000


def total_volume(area, rainfall):
    """Litres of rain landing on the roof over the year."""
    return area*rainfall


def collectable_liters(volume, efficiency):
    """Litres that actually reach the downpipe after runoff losses."""
    return volume*efficiency


def first_flush(collectable):
    """Litres diverted at the start of the rains to wash off debris."""
    return collectable*FIRST_FLUSH_FRACTION


def usable_liters(collectable):
    """Litres left once the first flush has been diverted."""
    return collectable-first_flush(collectable)


def full_tanks(usable):
    """Number of completely filled standard tanks."""
    return math.floor(usable/TANK_CAPACITY_LITERS)


def validate_inputs(area, rainfall, efficiency):
    """Reject harvesting parameters that cannot describe a real roof."""
    if area<=0:
        raise ValueError("area must be a positive number of square meters")
    if rainfall<0:
        raise ValueError("rainfall cannot be negative")
    if efficiency<=0:
        raise ValueError("efficiency must be greater than zero")
    if efficiency>1:
        raise ValueError("efficiency cannot exceed one")


def catchment(area, rainfall, efficiency):
    """Return [collectable liters, usable liters after first flush, full tanks]."""
    validate_inputs(area, rainfall, efficiency)
    volume=total_volume(area, rainfall)
    collectable=collectable_liters(volume, efficiency)
    usable=usable_liters(collectable)
    tanks=full_tanks(usable)
    return [collectable, usable, tanks]


