DIESEL_RATE = 30.0
MIN_SPEED = 10.0
DEPTH_THRESHOLD = 5.0
SPEED_PENALTY = 0.5


def validate_inputs(distance, speed, depth):
    """Reject route data that cannot describe a real plowing job."""
    if distance <= 0:
        raise ValueError("route distance must be positive")
    if speed <= 0:
        raise ValueError("base plowing speed must be positive")
    if depth < 0:
        raise ValueError("snow depth cannot be negative")


def excess_depth(depth):
    """Centimetres of snow above the depth the truck handles at full speed."""
    if depth <= DEPTH_THRESHOLD:
        return 0.0
    return depth - DEPTH_THRESHOLD


def speed_penalty(depth):
    return SPEED_PENALTY * excess_depth(depth)


def reduced_speed(speed, depth):
    return speed - speed_penalty(depth)


def adjusted_speed(speed, depth):
    """Never let the deep-snow penalty push the truck below the floor speed."""
    return float(max(MIN_SPEED, reduced_speed(speed, depth)))


def clearing_time(distance, speed):
    return distance / speed


def fuel_used(hours):
    return hours * DIESEL_RATE


def plowing(distance, speed, depth):
    validate_inputs(distance, speed, depth)
    effective = adjusted_speed(speed, depth)
    hours = clearing_time(distance, effective)
    fuel = fuel_used(hours)
    return [effective, hours, fuel]


def format_report(name, distance, depth, effective, hours, fuel):
    header = f"{name}: {distance:.1f} km through {depth:.0f} cm of snow"
    detail = f"  speed {effective:.1f} km/h | time {hours:.2f} h | diesel {fuel:.1f} L"
    return "\n".join((header, detail))


def main():
    routes = [
        ("Main Street", 60, 40, 25),
        ("Harbour Road", 18.5, 35, 4),
        ("Mountain Pass", 42, 30, 60),
        ("Airport Loop", 25, 45, 12),
    ]
    total_fuel = 0.0
    worst_name = routes[0][0]
    worst_time = 0.0
    for name, distance, speed, depth in routes:
        effective, hours, fuel = plowing(distance, speed, depth)
        print(format_report(name, distance, depth, effective, hours, fuel))
        total_fuel += fuel
        if hours > worst_time:
            worst_time = hours
            worst_name = name
    print(f"Fleet diesel needed: {total_fuel:.1f} L")
    print(f"Longest single job: {worst_name} at {worst_time:.2f} h")


if __name__ == "__main__":
    main()

