PI = 3.14
GRAVITY = 9.81
DENSITY = 1000.0
VELOCITY_LIMIT = 3.0


def square(value):
    return value * value


def twice_gravity():
    return 2.0 * GRAVITY


def cross_section(diameter):
    radius = diameter
    radius /= 2.0
    return PI * square(radius)


def velocity(flow, diameter):
    area = cross_section(diameter)
    return flow / area


def velocity_head(speed):
    return square(speed) / twice_gravity()


def slenderness(length, diameter):
    return length / diameter


def friction_head(factor, length, diameter, speed):
    head = velocity_head(speed)
    head *= factor
    head *= slenderness(length, diameter)
    return head


def weight_flow(flow):
    rate = flow
    rate *= DENSITY
    rate *= GRAVITY
    return rate


def hydraulic_power(total_head, flow):
    power = weight_flow(flow)
    power *= total_head
    return power


def validate(system):
    if len(system) != 5:
        raise ValueError("system must hold lift, length, diameter, factor, flow")
    lift, length, diameter, factor, flow = system
    if diameter <= 0.0:
        raise ValueError("pipe diameter must be positive")
    if flow <= 0.0:
        raise ValueError("flow rate must be positive")
    if length < 0.0:
        raise ValueError("pipe length cannot be negative")
    if factor < 0.0:
        raise ValueError("friction factor cannot be negative")
    if lift < 0.0:
        raise ValueError("static lift cannot be negative")


def analyze(system):
    validate(system)
    lift, length, diameter, factor, flow = system
    speed = velocity(flow, diameter)
    losses = friction_head(factor, length, diameter, speed)
    total = lift
    total += losses
    power = hydraulic_power(total, flow)
    return (round(speed, 2), round(total, 2), round(power, 1))


def report(system):
    speed, head, power = analyze(system)
    kilowatts = power
    kilowatts /= 1000.0
    lines = ["Velocity: {0:.2f} m/s".format(speed)]
    lines.append("Total dynamic head: {0:.2f} m".format(head))
    lines.append("Hydraulic power: {0:.1f} W ({1:.3f} kW)".format(power, kilowatts))
    if speed > VELOCITY_LIMIT:
        lines.append("Warning: velocity above {0:.1f} m/s, enlarge the pipe".format(VELOCITY_LIMIT))
    return lines


def main():
    pump = [10.0, 50.0, 0.2, 0.02, 0.1]
    for line in report(pump):
        print(line)


if __name__ == "__main__":
    main()

