def total_available(volume, pressure):
    """Liters of gas the cylinder holds at the current pressure."""
    return volume * pressure


def safety_volume(volume, reserve):
    """Liters that must stay in the cylinder as a safety reserve."""
    return volume * reserve


def usable_liters(total, safety):
    """Liters that may actually be breathed."""
    return total - safety


def usable_mass(liters, density):
    """Mass in kg of the usable oxygen."""
    return liters * density


def available_minutes(liters, flow):
    """Minutes of breathing left at the prescribed flow rate."""
    return liters / flow


def current_mass(empty_mass, gas_mass):
    """Mass in kg of the cylinder plus the gas it still contains."""
    return empty_mass + gas_mass


def to_hours(minutes):
    return minutes / 60.0


def is_low(minutes):
    return minutes < 30.0


def _validated(tank):
    if len(tank) != 6:
        raise ValueError("a tank record needs exactly 6 values")
    values = [float(item) for item in tank]
    volume, pressure, flow, reserve, empty_mass, density = values
    if volume <= 0:
        raise ValueError("cylinder volume must be positive")
    if flow <= 0:
        raise ValueError("patient flow rate must be positive")
    if pressure < 0:
        raise ValueError("pressure cannot be negative")
    if reserve < 0:
        raise ValueError("reserve pressure cannot be negative")
    if empty_mass < 0:
        raise ValueError("empty tank mass cannot be negative")
    if density < 0:
        raise ValueError("oxygen density cannot be negative")
    return values


def evaluate(tank):
    volume, pressure, flow, reserve, empty_mass, density = _validated(tank)
    total = total_available(volume, pressure)
    safety = safety_volume(volume, reserve)
    liters = usable_liters(total, safety)
    if liters < 0.0:
        liters = 0.0
    gas_mass = usable_mass(liters, density)
    mass = current_mass(empty_mass, gas_mass)
    minutes = available_minutes(liters, flow)
    return (round(liters, 2), round(minutes, 2), round(mass, 2), is_low(minutes))


def format_report(label, result):
    liters, minutes, mass, low = result
    status = "REFILL SOON" if low else "OK"
    hours = to_hours(minutes)
    return ("{}: {:.1f} usable L, {:.1f} min ({:.2f} h), total mass {:.2f} kg -> {}"
            .format(label, liters, minutes, hours, mass, status))


def main():
    fleet = [
        ("ward cylinder", [10.0, 150.0, 2.0, 20.0, 14.0, 0.0013]),
        ("transport bottle", [2.0, 120.0, 6.0, 20.0, 3.5, 0.0013]),
        ("bedside spare", [5.0, 40.0, 4.0, 15.0, 7.2, 0.0013]),
    ]
    alerts = 0
    for label, tank in fleet:
        result = evaluate(tank)
        print(format_report(label, result))
        if result[3]:
            alerts = alerts + 1
    print("cylinders needing attention: {} of {}".format(alerts, len(fleet)))


if __name__ == "__main__":
    main()

