    resistance=float(circuit[1])
    initial_voltage=float(circuit[2])
    target_voltage=float(circuit[3])
    if capacitance<=0.0:
        raise ValueError("capacitance must be positive")
    if resistance<=0.0:
        raise ValueError("resistance must be positive")
    if target_voltage<=0.0:
        raise ValueError("target voltage must be positive")
    if initial_voltage<target_voltage:
        raise ValueError("initial voltage must be at least the target voltage")
    return capacitance, resistance, initial_voltage, target_voltage


def charge(capacitance, voltage):
    """Charge held on a capacitor, in coulombs."""
    return capacitance*voltage


def average_voltage(voltage):
    """Mean voltage seen while charging from zero up to the given voltage."""
    return voltage/2.0


def stored_energy(capacitance, voltage):
    """Energy held by a capacitor, the charge times the average voltage."""
    return charge(capacitance, voltage)*average_voltage(voltage)


def time_constant(resistance, capacitance):
    return resistance*capacitance


def voltage_ratio(initial_voltage, target_voltage):
    return initial_voltage/target_voltage


def decay_time(tau, initial_voltage, target_voltage):
    """Time for an RC network to fall from one voltage to another."""
    return tau*math.log(voltage_ratio(initial_voltage, target_voltage))


def dissipated_energy(capacitance, initial_voltage, target_voltage):
    return stored_energy(capacitance, initial_voltage)-stored_energy(capacitance, target_voltage)


def half_life(tau):
    """Time for the capacitor voltage to fall to half of its value."""
    return tau*math.log(2.0)


def truncate_hundredths(value):
    """Cut a seconds value to two decimals without rounding upwards."""
    return float(Decimal(value).quantize(Decimal("0.01"), ROUND_DOWN))


def discharge(circuit):
    capacitance, resistance, initial_voltage, target_voltage=validate(circuit)
    tau=time_constant(resistance, capacitance)
    seconds=decay_time(tau, initial_voltage, target_voltage)
    released=dissipated_energy(capacitance, initial_voltage, target_voltage)
    return (round(tau, 6), truncate_hundredths(seconds), round(released, 6))


def format_report(name, circuit, result):
    """Build a textual summary of one circuit's discharge behaviour."""
    tau, seconds, released=result
    lines=["Circuit: {0}".format(name)]
    lines.append("  stored charge   = {0:.6f} C".format(charge(circuit[0], circuit[2])))
    lines.append("  time constant   = {0:.3f} s".format(tau))
    lines.append("  half life       = {0:.3f} s".format(half_life(tau)))
    lines.append("  time to target  = {0:.2f} s".format(seconds))
    lines.append("  energy released = {0:.4f} J".format(released))
    return "\n".join(lines)


def main():
    circuits=[
        ("flash trigger", [0.001, 1000.0, 12.0, 3.0]),
        ("timer stage", [4.7e-6, 100000.0, 5.0, 1.65]),
        ("power rail bleeder", [0.0022, 47000.0, 24.0, 0.2]),
    ]
    energies=[]
    slowest=0.0
    for name, circuit in circuits:
        result=discharge(circuit)
        print(format_report(name, circuit, result))
        energies.append(result[2])
        if result[1]>slowest:
            slowest=result[1]
    print("total energy dissipated = {0:.4f} J".format(sum(energies)))
    print("slowest discharge       = {0:.2f} s".format(slowest))


if __name__=="__main__":
    main()

