def _validate(vitals):
    """Check that vitals holds four positive numbers in the expected order."""
    if len(vitals) != 4:
        raise ValueError("vitals must list systolic, diastolic, heart rate and age")
    for name, value in zip(("systolic", "diastolic", "heart rate", "age"), vitals):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be numeric")
        if value <= 0:
            raise ValueError(f"{name} must be positive")
    systolic = float(vitals[0])
    diastolic = float(vitals[1])
    if diastolic >= systolic:
        raise ValueError("diastolic pressure must be below systolic pressure")
    return systolic, diastolic, float(vitals[2]), float(vitals[3])


def _pulse_pressure(systolic, diastolic):
    return systolic - diastolic


def _mean_arterial(diastolic, pulse_pressure):
    third = pulse_pressure / 3.0
    return diastolic + third


def _cardiac_output(pulse_pressure, heart_rate):
    stroke_volume = pulse_pressure * 2.0
    beat_output = stroke_volume * heart_rate
    return beat_output / 1000.0


def _is_hypertensive(systolic, diastolic):
    if systolic > 130.0:
        return True
    return diastolic > 80.0


def assess(vitals):
    """Evaluate circulatory health from [systolic, diastolic, heart rate, age]."""
    systolic, diastolic, heart_rate = _validate(vitals)[:3]
    pulse = _pulse_pressure(systolic, diastolic)
    mean = _mean_arterial(diastolic, pulse)
    output = _cardiac_output(pulse, heart_rate)
    hypertensive = _is_hypertensive(systolic, diastolic)
    return (round(pulse, 2), round(mean, 2), round(output, 2), hypertensive)


def target_heart_rate(age):
    """Upper bound of the aerobic training zone for the given age."""
    maximum = 220.0 - age
    return round(maximum * 0.85, 1)


def describe(vitals):
    """Build a readable report line for one patient reading."""
    pulse, mean, output, hypertensive = assess(vitals)
    heart_rate = float(vitals[2])
    age = float(vitals[3])
    notes = []
    if mean < 70.0:
        notes.append("low perfusion pressure")
    if pulse > 60.0:
        notes.append("wide pulse pressure")
    if heart_rate > target_heart_rate(age):
        notes.append("heart rate above training zone")
    if hypertensive:
        status = "hypertensive"
    else:
        status = "normotensive"
    summary = "; ".join(notes) or "no flags"
    template = "age {:.0f}: PP {:.1f}, MAP {:.2f}, CO {:.2f}, {} ({})"
    return template.format(age, pulse, mean, output, status, summary)


def main():
    readings = [
        [120.0, 80.0, 70.0, 45.0],
        [145.0, 92.0, 88.0, 62.0],
        [98.0, 62.0, 55.0, 27.0],
        [160.0, 70.0, 105.0, 74.0],
    ]
    hypertensive_count = 0
    for vitals in readings:
        print(describe(vitals))
        if assess(vitals)[3]:
            hypertensive_count += 1
    fraction = hypertensive_count / len(readings)
    share = 100.0 * fraction
    print("hypertensive in cohort: {} of {} ({:.1f}%)".format(
        hypertensive_count, len(readings), share))


if __name__ == "__main__":
    main()

