"""Highway congestion analysis based on a simple triangular flow model."""

CAPACITY_DIVISOR = 4.0
JAM_SHARE = 2.0


def parse_traffic(traffic):
    """Validate and unpack [flow rate, jam density, free flow speed, lanes]."""
    if len(traffic) != 4:
        raise ValueError("traffic needs exactly four observed values")
    values = [float(value) for value in traffic]
    flow_rate, jam_density, free_flow_speed, lane_count = values
    if flow_rate < 0.0:
        raise ValueError("observed flow rate cannot be negative")
    if jam_density <= 0.0:
        raise ValueError("jam density must be positive")
    if free_flow_speed <= 0.0:
        raise ValueError("free flow speed must be positive")
    if lane_count < 1.0:
        raise ValueError("there must be at least one lane")
    return flow_rate, jam_density, free_flow_speed, lane_count


def saturation_flow(free_flow_speed, jam_density):
    """Theoretical flow if every car moved at free flow speed at jam density."""
    return free_flow_speed * jam_density


def lane_capacity(free_flow_speed, jam_density):
    """Capacity of a single lane in cars per hour."""
    saturation = saturation_flow(free_flow_speed, jam_density)
    return saturation / CAPACITY_DIVISOR


def total_capacity(lane_count, free_flow_speed, jam_density):
    per_lane = lane_capacity(free_flow_speed, jam_density)
    return lane_count * per_lane


def per_lane_flow(flow_rate, lane_count):
    return flow_rate / lane_count


def current_density(flow_rate, lane_count, free_flow_speed):
    """Cars per mile per lane implied by the observed flow."""
    lane_flow = per_lane_flow(flow_rate, lane_count)
    return lane_flow / free_flow_speed


def jam_threshold(jam_density):
    return jam_density / JAM_SHARE


def is_congested(density, jam_density):
    threshold = jam_threshold(jam_density)
    return density > threshold


def density_ratio(density, jam_density):
    return density / jam_density


def speed_drop(free_flow_speed, ratio):
    return free_flow_speed * ratio


def average_speed(free_flow_speed, density, jam_density):
    """Speed loss grows linearly with how close density is to jam density."""
    ratio = density_ratio(density, jam_density)
    drop = speed_drop(free_flow_speed, ratio)
    return free_flow_speed - drop


def evaluate(traffic):
    flow_rate, jam_density, free_flow_speed, lane_count = parse_traffic(traffic)
    capacity = total_capacity(lane_count, free_flow_speed, jam_density)
    density = current_density(flow_rate, lane_count, free_flow_speed)
    congested = is_congested(density, jam_density)
    speed = average_speed(free_flow_speed, density, jam_density)
    return capacity, speed, congested


def format_report(capacity, speed, congested):
    status = "CONGESTED" if congested else "free flowing"
    return "capacity {0:.1f} cars/h, mean speed {1:.2f} mph, {2}".format(
        capacity, speed, status)


def main():
    observations = [
        [3000.0, 120.0, 60.0, 2.0],
        [7000.0, 150.0, 65.0, 3.0],
        [9000.0, 100.0, 50.0, 2.0],
    ]
    for traffic in observations:
        capacity, speed, congested = evaluate(traffic)
        print(format_report(capacity, speed, congested))


if __name__ == "__main__":
    main()

