import math

SABINE_CONSTANT = 0.161
CEILING_ABSORPTION = 0.1


def _positive(value, name):
    number = float(value)
    if number <= 0.0:
        raise ValueError(f"{name} must be positive, got {number}")
    return number


def _coefficient(value, name):
    number = float(value)
    if number < 0.0:
        raise ValueError(f"{name} absorption coefficient cannot be negative")
    if number > 1.0:
        raise ValueError(f"{name} absorption coefficient cannot exceed 1.0")
    return number


def parse_room(room):
    if len(room) != 5:
        raise ValueError("room needs length, width, height and two coefficients")
    length = _positive(room[0], "length")
    width = _positive(room[1], "width")
    height = _positive(room[2], "height")
    wall_coefficient = _coefficient(room[3], "wall")
    floor_coefficient = _coefficient(room[4], "floor")
    return length, width, height, wall_coefficient, floor_coefficient


def floor_area(length, width):
    return length * width


def room_volume(length, width, height):
    base = floor_area(length, width)
    return base * height


def wall_area(length, width, height):
    span = sum((length, width))
    return math.prod((2.0, span, height))


def total_absorption(walls, floor, ceiling, wall_coefficient, floor_coefficient):
    areas = (walls, floor, ceiling)
    coefficients = (wall_coefficient, floor_coefficient, CEILING_ABSORPTION)
    pairs = zip(areas, coefficients)
    return sum(area * coefficient for area, coefficient in pairs)


def _sabine_numerator(volume):
    return SABINE_CONSTANT * volume


def reverberation_time(volume, absorption):
    if absorption <= 0.0:
        raise ValueError("absorption must be positive to compute a reverberation time")
    return _sabine_numerator(volume) / absorption


def _hundredths(value):
    return value * 100.0


def _truncate_two(value):
    scaled = math.floor(_hundredths(value))
    return scaled / 100.0


def describe(seconds):
    if seconds < 1.0:
        return "dry"
    if seconds < 2.0:
        return "balanced"
    return "reverberant"


def analyze(room):
    length, width, height, wall_coefficient, floor_coefficient = parse_room(room)
    volume = room_volume(length, width, height)
    walls = wall_area(length, width, height)
    floor = floor_area(length, width)
    absorption = total_absorption(walls, floor, floor, wall_coefficient, floor_coefficient)
    seconds = reverberation_time(volume, absorption)
    return volume, absorption, _truncate_two(seconds)


def main():
    halls = {
        "main hall": [20.0, 15.0, 5.0, 0.05, 0.2],
        "studio": [8.0, 6.0, 3.0, 0.3, 0.4],
    }
    for name, room in halls.items():
        volume, absorption, seconds = analyze(room)
        quality = describe(seconds)
        print(f"{name}: {volume:.1f} m3, {absorption:.1f} sabins, RT {seconds:.2f} s ({quality})")


if __name__ == "__main__":
    main()

