PI = 3.14159


def validate(motor):
    """Check that a motor reading has five usable numeric fields."""
    if len(motor) != 5:
        raise ValueError("a motor reading needs exactly five values")
    for value in motor:
        if not isinstance(value, (int, float)):
            raise TypeError("motor values must be numeric")
    voltage, current, efficiency, speed, torque_limit = motor
    if voltage <= 0 or current <= 0:
        raise ValueError("voltage and current must be positive")
    if efficiency <= 0 or efficiency > 1:
        raise ValueError("efficiency must be a decimal in (0, 1]")
    if speed <= 0:
        raise ValueError("speed must be positive")
    if torque_limit <= 0:
        raise ValueError("the torque limit must be positive")
    return voltage, current, efficiency, speed, torque_limit


def truncate(value, places = 2):
    """Cut a value down to the given number of decimals, without rounding up."""
    scale = 10.0 ** places
    return int(value * scale) / scale


def evaluate(motor):
    voltage, current, efficiency, speed, torque_limit = validate(motor)
    electrical_power = voltage * current
    mechanical_power = electrical_power * efficiency
    angular_velocity = speed * PI / 30.0
    operating_torque = mechanical_power / angular_velocity
    warning = operating_torque >= torque_limit
    return electrical_power, truncate(operating_torque), warning


def headroom(motor):
    """Return how much torque margin, in newton-metres, is still available."""
    _, operating_torque, _ = evaluate(motor)
    limit = motor[4]
    return truncate(limit - operating_torque)


def describe(name, motor):
    power, torque, warning = evaluate(motor)
    margin = headroom(motor)
    state = "OVER LIMIT" if warning else "ok"
    return "%-10s %9.1f W %8.2f Nm  margin %6.2f Nm  %s" % (
        name, power, torque, margin, state)


def main():
    fleet = [
        ("pump-1", [400.0, 20.0, 0.9, 1500.0, 50.0]),
        ("fan-2", [230.0, 15.0, 0.85, 900.0, 25.0]),
        ("mill-3", [690.0, 60.0, 0.94, 750.0, 400.0]),
    ]
    print("motor          input power     torque")
    alerts = 0
    for name, motor in fleet:
        print(describe(name, motor))
        if evaluate(motor)[2]:
            alerts = alerts + 1
    print("motors needing attention: %d of %d" % (alerts, len(fleet)))


if __name__ == "__main__":
    main()

