DEGREE_DAY_FACTOR = 4.5
LATENT_HEAT_OF_FUSION = 334.0
TRANSFER_COEFFICIENT = 1.2
TEMPERATURE_FLOOR = -90.0


def validate_glacier(glacier):
    """Check that the measurement list is physically plausible."""
    if len(glacier) != 4:
        raise ValueError("glacier needs temperature, radiation, albedo, wind")
    temperature, radiation, albedo, wind = glacier
    if temperature < TEMPERATURE_FLOOR:
        raise ValueError("air temperature below the physical floor")
    if radiation < 0.0:
        raise ValueError("incoming shortwave radiation cannot be negative")
    if albedo < 0.0:
        raise ValueError("albedo fraction cannot be negative")
    if albedo > 1.0:
        raise ValueError("albedo fraction cannot exceed one")
    if wind < 0.0:
        raise ValueError("wind speed cannot be negative")


def positive_degree_day(temperature):
    """Melt contributed by air temperature above freezing."""
    if temperature > 0.0:
        return temperature * DEGREE_DAY_FACTOR
    return 0.0


def fraction_absorbed(albedo):
    return 1.0 - albedo


def net_shortwave(radiation, albedo):
    return radiation * fraction_absorbed(albedo)


def wind_transfer(wind):
    return wind * TRANSFER_COEFFICIENT


def sensible_heat(temperature, wind):
    return temperature * wind_transfer(wind)


def radiative_melt(net_radiation):
    return net_radiation / LATENT_HEAT_OF_FUSION


def total_melt(degree_day, net_radiation, sensible):
    return sum((degree_day, radiative_melt(net_radiation), sensible))


def ablation(glacier):
    """Return (net radiation, sensible heat flux, total daily melt in mm)."""
    validate_glacier(glacier)
    temperature, radiation, albedo, wind = glacier
    degree_day = positive_degree_day(temperature)
    net_radiation = net_shortwave(radiation, albedo)
    sensible = sensible_heat(temperature, wind)
    melt = total_melt(degree_day, net_radiation, sensible)
    return (round(net_radiation, 1), round(sensible, 1), round(melt, 1))


def format_report(name, result):
    net_radiation, sensible, melt = result
    rows = ["Glacier: {}".format(name)]
    rows.append("  net shortwave : {:.1f} W/m2".format(net_radiation))
    rows.append("  sensible heat : {:.1f} W/m2".format(sensible))
    rows.append("  daily melt    : {:.1f} mm".format(melt))
    return "\n".join(rows)


def main():
    sites = [("Rhone", [5.0, 400.0, 0.4, 2.0]),
             ("Vatnajokull", [-2.0, 250.0, 0.6, 5.0]),
             ("Franz Josef", [8.5, 520.0, 0.25, 3.5])]
    melts = []
    for name, glacier in sites:
        result = ablation(glacier)
        print(format_report(name, result))
        melts.append(result[2])
    cumulative = sum(melts)
    print("Mean melt   : {:.1f} mm".format(cumulative / len(sites)))
    peak = max(melts)
    leader = sites[melts.index(peak)][0]
    print("Fastest loss: {} at {:.1f} mm".format(leader, peak))


if __name__ == "__main__":
    main()

