import math

BASE_COEFFICIENT = 0.0011


def parse_pipeline(spec):
    """Turn a comma separated pipeline description into five floats."""
    fields = [item.strip() for item in spec.split(",")]
    if len(fields) != 5:
        raise ValueError("a pipeline spec needs exactly 5 values")
    return [float(field) for field in fields]


def validate_pipeline(pipeline):
    """Reject data that the transport equations cannot handle."""
    if len(pipeline) != 5:
        raise ValueError("pipeline must hold 5 values")
    upstream, downstream, diameter, length, gravity = pipeline
    if downstream <= 0.0:
        raise ValueError("downstream pressure must be positive")
    if downstream >= upstream:
        raise ValueError("upstream pressure must exceed downstream pressure")
    if diameter <= 0.0:
        raise ValueError("pipe diameter must be positive")
    if length <= 0.0:
        raise ValueError("pipe length must be positive")
    if gravity <= 0.0:
        raise ValueError("gas specific gravity must be positive")


def squared_difference(upstream, downstream):
    return pow(upstream, 2.0) - pow(downstream, 2.0)


def transmission_factor(gravity):
    return 1.0 / math.sqrt(gravity)


def pressure_gradient(pressure_diff, length):
    return pressure_diff / length


def flow_rate(pressure_diff, length, diameter, gravity):
    factor = transmission_factor(gravity)
    slope = math.sqrt(pressure_gradient(pressure_diff, length))
    bore = pow(diameter, 2.5)
    return BASE_COEFFICIENT * math.prod((factor, slope, bore))


def total_pressure(upstream, downstream):
    return upstream + downstream


def average_pressure(upstream, downstream):
    return total_pressure(upstream, downstream) / 2.0


def evaluate(pipeline):
    """Return (pressure difference, flow rate, average pressure)."""
    validate_pipeline(pipeline)
    upstream, downstream, diameter, length, gravity = pipeline
    pressure_diff = squared_difference(upstream, downstream)
    rate = flow_rate(pressure_diff, length, diameter, gravity)
    mean_pressure = average_pressure(upstream, downstream)
    return (pressure_diff, rate, mean_pressure)


def format_report(label, pipeline):
    pressure_diff, rate, mean_pressure = evaluate(pipeline)
    lines = [f"{label}:"]
    lines.append(f"  pressure difference: {pressure_diff:.1f}")
    lines.append(f"  flow rate: {rate:.5f}")
    lines.append(f"  average pressure: {mean_pressure:.1f}")
    return "\n".join(lines)


def main():
    specs = [
        ("Test spur", "100.0, 80.0, 0.5, 10.0, 0.6"),
        ("North trunk", "1200.0, 950.0, 0.75, 45.0, 0.62"),
    ]
    for label, spec in specs:
        pipeline = parse_pipeline(spec)
        print(format_report(label, pipeline))


if __name__ == "__main__":
    main()

