def scaled(value, factor):
    return value * factor


def fermentable_mass(soluble, insoluble):
    return scaled(soluble, 0.8) + scaled(insoluble, 0.2)


def fatty_acid_yield(fermentable):
    return scaled(fermentable, 0.6)


def derived_calories(fatty_acids):
    return scaled(fatty_acids, 2.4)


def total_mass(soluble, insoluble, protein):
    return sum((soluble, insoluble, protein))


def retained_fraction(moisture):
    return 1.0 - moisture


def dry_mass(total, moisture):
    return scaled(total, retained_fraction(moisture))


def mean(values):
    return sum(values) / len(values)


def validate(meal):
    if len(meal) != 4:
        raise ValueError("a meal must have exactly four components")
    values = []
    for index, raw in enumerate(meal):
        value = float(raw)
        if value < 0.0:
            raise ValueError("component {} may not be negative".format(index))
        values.append(value)
    if values[2] > 1.0:
        raise ValueError("moisture fraction must not exceed 1.0")
    return values


def nutrition(meal):
    soluble, insoluble, moisture, protein = validate(meal)
    fermentable = fermentable_mass(soluble, insoluble)
    fatty_acids = fatty_acid_yield(fermentable)
    calories = derived_calories(fatty_acids)
    total = total_mass(soluble, insoluble, protein)
    adjusted = dry_mass(total, moisture)
    return (round(fermentable, 2), round(calories, 2), round(adjusted, 2))


def parse_meal(text):
    parts = text.replace(",", " ").split()
    return [float(part) for part in parts]


def fermentation_ratio(meal):
    values = nutrition(meal)
    fermentable = values[0]
    adjusted = values[2]
    if adjusted <= 0.0:
        return 0.0
    return round(fermentable / adjusted, 4)


def describe(name, meal):
    fermentable, calories, adjusted = nutrition(meal)
    ratio = fermentation_ratio(meal)
    lines = ["{}:".format(name)]
    lines.append("  fermentable mass : {:6.2f} g".format(fermentable))
    lines.append("  derived calories : {:6.2f} kcal".format(calories))
    lines.append("  adjusted dry mass: {:6.2f} g".format(adjusted))
    if ratio >= 0.25:
        verdict = "highly fermentable"
    elif ratio >= 0.10:
        verdict = "moderately fermentable"
    else:
        verdict = "poorly fermentable"
    lines.append("  verdict          : {} (ratio {:.4f})".format(verdict, ratio))
    return "\n".join(lines)


def main():
    samples = [
        ("reference meal", "10.0, 15.0, 0.1, 20.0"),
        ("bran breakfast", "4.5 22.0 0.35 9.0"),
        ("lentil stew", "12.0 6.0 0.6 24.5"),
    ]
    calorie_totals = []
    for name, text in samples:
        meal = parse_meal(text)
        print(describe(name, meal))
        calorie_totals.append(nutrition(meal)[1])
    total_calories = sum(calorie_totals)
    print("total fiber calories: {:.2f} kcal".format(total_calories))
    print("average per meal: {:.2f} kcal".format(mean(calorie_totals)))


if __name__ == "__main__":
    main()

