def parse_inputs(array):
    if len(array) != 6:
        raise ValueError("expected three irradiance values, area, efficiency and inverter limit")
    values = [float(value) for value in array]
    irradiances = values[:3]
    area = values[3]
    efficiency = values[4]
    limit = values[5]
    if area <= 0.0:
        raise ValueError("array surface area must be positive")
    if efficiency <= 0.0:
        raise ValueError("panel efficiency must be positive")
    if efficiency > 1.0:
        raise ValueError("panel efficiency cannot exceed 1.0")
    if limit <= 0.0:
        raise ValueError("inverter limit must be positive")
    for irradiance in irradiances:
        if irradiance < 0.0:
            raise ValueError("irradiance values cannot be negative")
    return irradiances, area, efficiency, limit


def panel_output(irradiance, area):
    return irradiance * area


def potential_power(irradiance, area, efficiency):
    collected = panel_output(irradiance, area)
    return collected * efficiency


def excess_power(potential, limit):
    return potential - limit


def total_energy(delivered, clipped):
    return delivered + clipped


def clipped_share(clipped, total):
    if total <= 0.0:
        return 0.0
    return clipped / total


def loss_percentage(clipped, total):
    share = clipped_share(clipped, total)
    return round(share * 100.0, 1)


def clipping(array):
    irradiances, area, efficiency, limit = parse_inputs(array)
    total_delivered = 0.0
    total_clipped = 0.0
    for irradiance in irradiances:
        potential = potential_power(irradiance, area, efficiency)
        if potential > limit:
            total_delivered += limit
            total_clipped += excess_power(potential, limit)
        else:
            total_delivered += potential
    energy = total_energy(total_delivered, total_clipped)
    loss = loss_percentage(total_clipped, energy)
    return (total_delivered, total_clipped, loss)


def format_report(array):
    irradiances, area, efficiency, limit = parse_inputs(array)
    delivered, clipped, loss = clipping(array)
    lines = ["Hourly breakdown:"]
    for hour, irradiance in enumerate(irradiances, 1):
        potential = potential_power(irradiance, area, efficiency)
        if potential > limit:
            template = "  hour {0}: {1:.1f} W potential, {2:.1f} W clipped"
            lines.append(template.format(hour, potential, excess_power(potential, limit)))
        else:
            lines.append("  hour {0}: {1:.1f} W potential, fully delivered".format(hour, potential))
    lines.append("Delivered energy: {0:.1f} Wh".format(delivered))
    lines.append("Clipped energy: {0:.1f} Wh".format(clipped))
    lines.append("Clipping loss: {0:.1f} %".format(loss))
    return "\n".join(lines)


def main():
    sample = [500.0, 1000.0, 200.0, 10.0, 0.2, 1500.0]
    print(format_report(sample))
    print(clipping(sample))


if __name__ == "__main__":
    main()

