    minute_ventilation = to_liters(volume_per_minute(tidal, frequency))
    fresh_air = alveolar_volume(tidal, dead_space)
    alveolar_ventilation = to_liters(volume_per_minute(fresh_air, frequency))
    dead_space_ratio = ratio_of(dead_space, tidal)
    warning = is_warning(alveolar_ventilation, dead_space_ratio)
    return (minute_ventilation, alveolar_ventilation, dead_space_ratio, warning)


def classify(minute_ventilation):
    if minute_ventilation < 4.0:
