MU_0 = 0.000001256
CROSS_SECTION_AREA = 0.05
SATURATION_FIELD = 1.6


def validate_coil(coil):
    if len(coil) != 4:
        raise ValueError("coil must contain turns, length, current, permeability")
    turns, length, current, permeability = coil
    if turns <= 0:
        raise ValueError("number of turns must be positive")
    if length <= 0:
        raise ValueError("solenoid length must be positive")
    if permeability < 1.0:
        raise ValueError("relative permeability must be at least 1.0")
    return float(turns), float(length), float(current), float(permeability)


def turn_density(turns, length):
    return turns / length


def core_constant(permeability):
    return permeability * MU_0


def ampere_turns(density, current):
    return density * current


def magnetic_field(permeability, density, current):
    return core_constant(permeability) * ampere_turns(density, current)


def magnetic_flux(field):
    return field * CROSS_SECTION_AREA


def is_saturated(field):
    return field > SATURATION_FIELD


def saturation_fraction(field):
    return field / SATURATION_FIELD


def current_for_field(unit_field, target_field):
    return target_field / unit_field


def electromagnet(coil):
    turns, length, current, permeability = validate_coil(coil)
    density = turn_density(turns, length)
    field = magnetic_field(permeability, density, current)
    flux = magnetic_flux(field)
    return (density, field, flux, is_saturated(field))


def describe(coil):
    density, field, flux, saturated = electromagnet(coil)
    state = "saturated" if saturated else "linear"
    lines = ["turn density : {:.1f} turns/m".format(density)]
    lines.append("field        : {:.4f} T".format(field))
    lines.append("flux         : {:.5f} Wb".format(flux))
    lines.append("core state   : " + state)
    return "\n".join(lines)


def required_current(coil, target_field):
    turns, length, current, permeability = validate_coil(coil)
    if target_field <= 0:
        raise ValueError("target field must be positive")
    density = turn_density(turns, length)
    unit_field = magnetic_field(permeability, density, 1.0)
    needed = current_for_field(unit_field, target_field)
    return needed, needed - current


def direction(change):
    if change > 0:
        return "increase"
    return "reduce"


def sweep_currents(coil, currents):
    report = []
    for amps in currents:
        trial = list(coil)
        trial[2] = amps
        result = electromagnet(trial)
        report.append((amps, result[1], result[3]))
    return report


def main():
    coil = [1000.0, 0.2, 5.0, 200.0]
    print(describe(coil))
    needed, change = required_current(coil, SATURATION_FIELD)
    print("to reach saturation {} current by {:.3f} A (to {:.3f} A)".format(
        direction(change), abs(change), needed))
    print("current sweep:")
    for amps, field, saturated in sweep_currents(coil, [0.5, 1.0, 2.0, 5.0]):
        mark = "*" if saturated else " "
        print("  {:>4.1f} A -> {:7.4f} T {}".format(amps, field, mark))
    air_field = electromagnet([500.0, 0.5, 3.0, 1.0])[1]
    fraction = saturation_fraction(air_field)
    print("air core coil: {:.6f} T ({:.4%} of saturation)".format(air_field, fraction))


if __name__ == "__main__":
    main()

