EFFICIENCY = 0.95
TAU = 6.283185307179586


def validate(gears):
    if len(gears) != 5:
        raise ValueError("expected five values: three tooth counts, speed, torque")
    for value in gears:
        if value <= 0:
            raise ValueError("all gear, speed and torque values must be positive")
    for count in gears[:3]:
        if count != round(count):
            raise ValueError("tooth counts must be whole numbers")


def ratio(driven_teeth, driving_teeth):
    return driven_teeth / driving_teeth


def total_ratio(gears):
    return ratio(gears[1], gears[0]) * ratio(gears[2], gears[1])


def output_speed(gears, total):
    return gears[3] / total


def ideal_torque(gears, total):
    return gears[4] * total


def actual_torque(gears, total):
    return ideal_torque(gears, total) * EFFICIENCY


def transmission(gears):
    validate(gears)
    total = total_ratio(gears)
    return (total, output_speed(gears, total), actual_torque(gears, total))


def revs_per_second(speed_rpm):
    return speed_rpm / 60.0


def angular_speed(speed_rpm):
    return TAU * revs_per_second(speed_rpm)


def power_watts(speed_rpm, torque_nm):
    return torque_nm * angular_speed(speed_rpm)


def report(name, gears):
    total, speed, torque = transmission(gears)
    input_power = power_watts(gears[3], gears[4])
    output_power = power_watts(speed, torque)
    lines = ["{}:".format(name)]
    lines.append("  total ratio     {:.3f}:1".format(total))
    lines.append("  output speed    {:.1f} rpm".format(speed))
    lines.append("  output torque   {:.2f} Nm".format(torque))
    if total > 1.0:
        lines.append("  type            reduction drive")
    elif total < 1.0:
        lines.append("  type            overdrive")
    else:
        lines.append("  type            direct drive")
    lines.append("  power in        {:.1f} W".format(input_power))
    lines.append("  power lost      {:.1f} W".format(input_power - output_power))
    return "\n".join(lines)


def main():
    drives = [
        ("Reduction box", [20.0, 40.0, 60.0, 3000.0, 100.0]),
        ("Overdrive unit", [60.0, 30.0, 20.0, 1800.0, 240.0]),
        ("Direct coupling", [36.0, 18.0, 36.0, 1200.0, 55.0]),
    ]
    for name, gears in drives:
        print(report(name, gears))
        print()
    heaviest = max(drives, key=lambda item: transmission(item[1])[2])
    print("Highest output torque: " + heaviest[0])


if __name__ == "__main__":
    main()

