def surface_area(width, length):
    """Plan area of a rectangular clarifier in square metres."""
    return width * length


def tank_volume(area, depth):
    """Water volume held above the given plan area."""
    return area * depth


def overflow_rate(flow, area):
    """Upward water velocity leaving the clarifier surface."""
    return flow / area


def retention_time(volume, flow):
    """Average time a parcel of water stays in the tank, in seconds."""
    return volume / flow


def settling_margin(settling, rate):
    """How much faster the target particle settles than the water rises."""
    return settling - rate


def captures_particles(settling, rate):
    """True when the target particle outruns the surface overflow rate."""
    return settling > rate


def retains_long_enough(retention):
    """True when the water stays in the tank for more than two minutes."""
    return retention > 120.0


def parse_tank(raw):
    """Convert a sequence of textual or numeric tank parameters to floats."""
    values = []
    for item in raw:
        if isinstance(item, str):
            item = item.strip()
        values.append(float(item))
    if len(values) != 5:
        raise ValueError("a tank needs exactly 5 parameters")
    return values


def validate_tank(tank):
    """Reject tanks whose geometry or flow would make the analysis meaningless."""
    flow, width, length, depth, settling = tank
    if flow <= 0.0:
        raise ValueError("volumetric flow rate must be positive")
    if width <= 0.0:
        raise ValueError("tank width must be positive")
    if length <= 0.0:
        raise ValueError("tank length must be positive")
    if depth <= 0.0:
        raise ValueError("tank water depth must be positive")
    if settling <= 0.0:
        raise ValueError("target settling velocity must be positive")


def clarifier(tank):
    """Assess a rectangular clarifier and report its hydraulic performance."""
    validate_tank(tank)
    flow, width, length, depth, settling = tank
    area = surface_area(width, length)
    volume = tank_volume(area, depth)
    rate = overflow_rate(flow, area)
    retention = retention_time(volume, flow)
    success = captures_particles(settling, rate) and retains_long_enough(retention)
    return (round(area, 5), round(retention, 5), round(rate, 5), success)


def describe(name, settling, result):
    """Build a human readable performance summary for one clarifier."""
    area, retention, rate, success = result
    verdict = "adequate" if success else "inadequate"
    margin = settling_margin(settling, rate)
    lines = [
        "%s: settling is %s" % (name, verdict),
        "  surface area      %.2f m2" % area,
        "  retention time    %.1f s (%.1f min)" % (retention, retention / 60.0),
        "  overflow rate     %.5f m/s" % rate,
    ]
    if margin > 0.0:
        lines.append("  settling margin   %.5f m/s" % margin)
    else:
        lines.append("  particles escape by %.5f m/s" % -margin)
    return "\n".join(lines)


def main():
    plants = {
        "primary basin": ["0.5", "10.0", "30.0", "4.0", "0.002"],
        "storm basin": [1.2, 8.0, 12.0, 3.0, 0.0015],
        "polishing basin": [0.05, 4.0, 6.0, 2.5, 0.001],
    }
    passing = []
    for name in sorted(plants):
        tank = parse_tank(plants[name])
        result = clarifier(tank)
        print(describe(name, tank[4], result))
        if result[3]:
            passing.append(name)
        print()
    print("%d of %d basins meet the settling target" % (len(passing), len(plants)))


if __name__ == "__main__":
    main()

