"""Laundry load sizing for a hotel housekeeping department."""

import math

SHEET_WEIGHT_PER_BED = 3.5
TOWEL_WEIGHT_PER_BED = 2.2
POOL_TOWEL_FACTOR = 1.1
POOL_OCCUPANCY_THRESHOLD = 0.8
MACHINE_CAPACITY_KG = 50.0
DETERGENT_SURCHARGE_KG = 5.0
SURCHARGE_CYCLE_LIMIT = 10


def validate_inputs(rooms, occupancy):
    if rooms < 0:
        raise ValueError("rooms cannot be negative")
    if occupancy < 0:
        raise ValueError("occupancy cannot be negative")
    if occupancy > 1:
        raise ValueError("occupancy cannot exceed 1.0")


def bed_count(rooms, occupancy):
    return (
        rooms * occupancy
    )


def sheet_load(total_beds):
    return (
        total_beds * SHEET_WEIGHT_PER_BED
    )


def towel_load(total_beds, occupancy):
    weight = (
        total_beds * TOWEL_WEIGHT_PER_BED
    )
    if occupancy > POOL_OCCUPANCY_THRESHOLD:
        weight = (
            weight * POOL_TOWEL_FACTOR
        )
    return weight


def sizing(rooms, occupancy):
    validate_inputs(rooms, occupancy)
    total_beds = bed_count(rooms, occupancy)
    sheets_weight = sheet_load(total_beds)
    towels_weight = towel_load(total_beds, occupancy)
    total_weight = (
        sheets_weight + towels_weight
    )
    wash_cycles = (
        total_weight / MACHINE_CAPACITY_KG
    )
    if wash_cycles > SURCHARGE_CYCLE_LIMIT:
        total_weight = (
            total_weight + DETERGENT_SURCHARGE_KG
        )
    return wash_cycles, total_weight


def format_report(rooms, occupancy, wash_cycles, total_weight):
    occupancy_pct = (
        occupancy * 100
    )
    machines = math.ceil(wash_cycles)
    lines = [
        "Rooms: {} at {:.0f}% occupancy".format(rooms, occupancy_pct),
        "Linen weight: {:.2f} kg".format(total_weight),
        "Wash cycles: {:.4f}".format(wash_cycles),
        "Machines required: {}".format(machines),
    ]
    if wash_cycles > SURCHARGE_CYCLE_LIMIT:
        lines.append("Detergent surcharge applied")
    return "\n".join(lines)


def main():
    scenarios = [(10, 0.9), (120, 0.75), (200, 0.95)]
    for rooms, occupancy in scenarios:
        wash_cycles, total_weight = sizing(rooms, occupancy)
        print(format_report(rooms, occupancy, wash_cycles, total_weight))
        print("-" * 32)


if __name__ == "__main__":
    main()

