import math

ROLL_LENGTH = 10.0
DROP_WIDTH = 0.5
TRIM_ALLOWANCE = 0.2
BULK_THRESHOLD = 3.0
BULK_SAVING = 0.5
MIN_ROLLS = 3


def validate_inputs(perimeter, height, repeat):
    """Reject measurements that cannot describe a real room."""
    if perimeter <= 0:
        raise ValueError("perimeter must be a positive number of metres")
    if height <= 0:
        raise ValueError("height must be a positive number of metres")
    if repeat < 0:
        raise ValueError("pattern repeat cannot be negative")


def _drops(perimeter):
    return perimeter / DROP_WIDTH


def _trimmed(height):
    return height + TRIM_ALLOWANCE


def _drop_length(height, repeat):
    padded = _trimmed(height)
    return padded + repeat


def _total_fabric(drops, length):
    return drops * length


def _rolls(total):
    return total / ROLL_LENGTH


def _with_safety(rolls):
    return rolls + 1


def _bulk_adjusted(total):
    return total - BULK_SAVING


def wallpaper(perimeter, height, repeat):
    """Return (rolls needed, total fabric length) for a room."""
    validate_inputs(perimeter, height, repeat)
    drops = _drops(perimeter)
    length = _drop_length(height, repeat)
    total = _total_fabric(drops, length)
    rolls = _rolls(total)
    if rolls < MIN_ROLLS:
        rolls = _with_safety(rolls)
    if length > BULK_THRESHOLD:
        total = _bulk_adjusted(total)
    return rolls, total


def _supplied(whole_rolls):
    return whole_rolls * ROLL_LENGTH


def _spare(whole_rolls, total):
    supplied = _supplied(whole_rolls)
    return supplied - total


def format_estimate(perimeter, height, repeat):
    """Turn an estimate into human readable report lines."""
    rolls, total = wallpaper(perimeter, height, repeat)
    whole = math.ceil(rolls)
    spare = _spare(whole, total)
    report = [f"Fabric needed: {total:.2f} m", f"Rolls (raw): {rolls:.2f}"]
    report.append(f"Rolls to buy: {whole}")
    if spare < 1.0:
        report.append("Warning: under a metre of spare wallpaper")
    else:
        report.append(f"Spare wallpaper: {spare:.2f} m")
    return report


def main():
    rooms = [("Hallway", 10.0, 2.5, 0.5), ("Bedroom", 14.0, 2.4, 0.0),
             ("Snug", 8.0, 2.2, 0.64)]
    for name, perimeter, height, repeat in rooms:
        print(f"-- {name} --")
        for line in format_estimate(perimeter, height, repeat):
            print(line)


if __name__ == "__main__":
    main()

