import math


def validate_dimensions(length, height, thickness):
    if length <= 0:
        raise ValueError("length must be positive")
    if height <= 0:
        raise ValueError("height must be positive")
    if thickness <= 0:
        raise ValueError("thickness must be positive")


def wall_area(length, height):
    return length * height


def brick_count(area):
    return area * 60


def base_mortar(bricks):
    return bricks * 0.001


def apply_thickness(volume, thickness):
    if thickness > 1:
        return volume * 2
    return volume


def apply_waste(volume):
    return volume * 1.1


def sand_share(volume):
    return volume * 0.75


def cement_share(volume):
    return volume * 0.25


def mortar(length, height, thickness):
    validate_dimensions(length, height, thickness)
    area = wall_area(length, height)
    bricks = brick_count(area)
    volume = base_mortar(bricks)
    volume = apply_thickness(volume, thickness)
    volume = apply_waste(volume)
    return bricks, sand_share(volume), cement_share(volume)


def cement_bags(cement_volume, bag_volume=0.035):
    return math.ceil(cement_volume / bag_volume)


def format_report(length, height, thickness):
    bricks, sand, cement = mortar(length, height, thickness)
    lines = ["Wall {0}m x {1}m, mortar thickness {2}cm".format(length, height, thickness)]
    lines.append("  bricks  : {0:.0f}".format(bricks))
    lines.append("  sand    : {0:.2f} m3".format(sand))
    lines.append("  cement  : {0:.2f} m3".format(cement))
    lines.append("  bags    : {0}".format(cement_bags(cement)))
    return "\n".join(lines)


def total_materials(walls):
    results = [mortar(*wall) for wall in walls]
    bricks_total = sum(item[0] for item in results)
    sand_total = sum(item[1] for item in results)
    cement_total = sum(item[2] for item in results)
    return bricks_total, sand_total, cement_total


def main():
    walls = [(10, 2, 0.5), (6, 2.5, 1.5), (4, 3, 1)]
    for wall in walls:
        print(format_report(*wall))
        print()
    bricks, sand, cement = total_materials(walls)
    print("Project totals")
    print("  bricks  : {0:.0f}".format(bricks))
    print("  sand    : {0:.2f} m3".format(sand))
    print("  cement  : {0:.2f} m3".format(cement))
    largest = max(walls, key=lambda w: wall_area(w[0], w[1]))
    print("  largest wall area: {0:.1f} m2".format(wall_area(largest[0], largest[1])))
    if cement > 1.0:
        print("  order cement in bulk")
    else:
        print("  order {0} bags of cement".format(cement_bags(cement)))


if __name__ == "__main__":
    main()

