def validate_inputs(volume, bioload):
    """Check that the tank size and bioload make physical sense."""
    if volume <= 0:
        raise ValueError("volume must be a positive number of litres")
    if bioload < 0:
        raise ValueError("bioload must not be negative")


def normalize_planted(planted):
    """Return the planted flag as a plain 0 or 1."""
    flag = int(planted)
    if flag < 0:
        raise ValueError("planted must be 0 or 1")
    if flag > 1:
        raise ValueError("planted must be 0 or 1")
    return flag


def base_turnover(volume):
    """Four tank volumes per hour is the starting point."""
    return volume * 4


def bioload_surcharge(volume):
    """Extra flow for a heavily stocked tank."""
    return volume * 2


def turnover_rate(volume, bioload, planted):
    """Litres per hour the filter has to move."""
    rate = base_turnover(volume)
    if bioload > 5:
        rate += bioload_surcharge(volume)
    if planted == 1:
        rate -= volume
    return rate


def raw_filter_volume(rate):
    """Filter body volume implied by the turnover rate."""
    return rate / 20


def filter_volume(rate):
    """Filter volume, never smaller than the two litre minimum."""
    raw = raw_filter_volume(rate)
    if raw < 2:
        return 2.0
    return raw


def media_weight(capacity):
    """Weight of media that fills the filter body."""
    return capacity * 0.5


def filtration(volume, bioload, planted):
    """Return (turnover rate, filter volume, media weight) for a tank."""
    validate_inputs(volume, bioload)
    flag = normalize_planted(planted)
    rate = turnover_rate(volume, bioload, flag)
    capacity = filter_volume(rate)
    media = media_weight(capacity)
    return rate, capacity, media


def parse_tank(line):
    """Turn a 'volume,bioload,planted' text record into numeric fields."""
    parts = line.split(",")
    if len(parts) != 3:
        raise ValueError("each record needs volume, bioload and planted")
    volume = float(parts[0])
    bioload = float(parts[1])
    planted = int(parts[2])
    return volume, bioload, planted


def describe(volume, bioload, planted):
    """Build a one-line report for a single tank."""
    rate, capacity, media = filtration(volume, bioload, planted)
    if planted == 1:
        style = "planted"
    else:
        style = "bare"
    if bioload > 5:
        load = "heavy"
    else:
        load = "light"
    template = ("{:.0f} L {} tank ({} bioload): turnover {:.1f} L/h, "
                "filter {:.2f} L, media {:.2f} kg")
    return template.format(volume, style, load, rate, capacity, media)


def total_media(records):
    """Sum the media weight required across a list of parsed tanks."""
    total = 0.0
    for volume, bioload, planted in records:
        total += filtration(volume, bioload, planted)[2]
    return total


def main():
    lines = ["50.0,6.0,1", "20.0,3.0,0", "120.0,8.5,1", "8.0,1.0,0"]
    records = [parse_tank(line) for line in lines]
    for volume, bioload, planted in records:
        print(describe(volume, bioload, planted))
    stock = total_media(records)
    print("Total filter media to buy: {:.2f} kg".format(stock))


if __name__ == "__main__":
    main()

