def total_area(length, width):
    """Area of the hall before the dancefloor is removed."""
    return length*width


def usable_area(length, width, dancefloor):
    """Hall area that is actually available for tables."""
    gross=total_area(length, width)
    return gross-dancefloor


def tables_for(area):
    """One table fits in every eight units of usable area."""
    return area/8


def chairs_for(tables):
    """Ten chairs are placed around each table."""
    return tables*10


def aisle_limit(width):
    """Length beyond which a long central aisle is required."""
    return width*2


def aisle_adjust(tables):
    """Two tables are removed to keep a long central aisle clear."""
    return tables-2


def validate(length, width, dancefloor):
    if length<=0:
        raise ValueError("length must be positive")
    if width<=0:
        raise ValueError("width must be positive")
