"""Fragrance and water batching helpers for small-batch soap making."""

EVAPORATION_FACTOR = 1.1
WATER_RATIO = 0.3
HOT_TEMPERATURE = 40.0
HIGH_CONCENTRATION = 0.05
ABSOLUTE_ZERO = -273.15


def _check_positive(name, value):
    if value < 0:
        raise ValueError(name + " must not be negative")


def validate_inputs(oil, concentration, temperature):
    _check_positive("oil", oil)
    _check_positive("concentration", concentration)
    if concentration > 1:
        raise ValueError("concentration must be a fraction of the oil weight")
    if temperature < ABSOLUTE_ZERO:
        raise ValueError("temperature is below absolute zero")


def base_fragrance_weight(oil, concentration, temperature):
    weight = oil
    weight *= concentration
    if temperature > HOT_TEMPERATURE:
        weight *= EVAPORATION_FACTOR
    return weight


def base_water_weight(oil, concentration, temperature):
    water = oil
    water *= WATER_RATIO
    if concentration > HIGH_CONCENTRATION:
        water -= base_fragrance_weight(oil, concentration, temperature)
    return water


def fragrance(oil, concentration, temperature):
    validate_inputs(oil, concentration, temperature)
    frag = base_fragrance_weight(oil, concentration, temperature)
    water = base_water_weight(oil, concentration, temperature)
    total = oil
    total += water
    total += frag
    return round(frag, 6), round(water, 6), round(total, 6)


def format_batch(oil, concentration, temperature):
    frag, water, total = fragrance(oil, concentration, temperature)
    share = frag
    share /= total
    share *= 100
    note = "evaporation loss applied"
    if temperature <= HOT_TEMPERATURE:
        note = "no evaporation loss"
    template = (
        "oil {0:.1f} g at {1:.0f} C -> fragrance {2:.1f} g, water {3:.1f} g, "
        "batch {4:.1f} g ({5:.2f}% fragrance, {6})"
    )
    return template.format(oil, temperature, frag, water, total, share, note)


def main():
    recipes = [
        (100.0, 0.06, 45.0),
        (250.0, 0.04, 30.0),
        (500.0, 0.05, 55.0),
    ]
    combined = 0.0
    for oil, concentration, temperature in recipes:
        print(format_batch(oil, concentration, temperature))
        combined += fragrance(oil, concentration, temperature)[2]
    print("combined batch weight: {0:.1f} g".format(combined))


if __name__ == "__main__":
    main()

