def base_feed_per_bird(age):
    """Feed in kg per bird and per day for a flock of the given age in weeks."""
    return age * 0.05


def daily_total_feed(flock, base):
    """Feed consumed by the whole flock during one day."""
    return base * flock


def daily_mortality_loss(flock, mortality):
    """Number of birds lost in one day for the given mortality rate."""
    return flock * mortality


def surviving_flock(flock, loss):
    """Birds still alive after the daily losses."""
    return flock - loss


def end_of_week_feed(surviving, age):
    """Feed figure per bird at the end of the week, including the 0.1 kg margin."""
    per_bird = base_feed_per_bird(age)
    scaled = daily_total_feed(surviving, per_bird)
    return scaled + 0.1


def weekly_projection(weekly_part):
    """Spread the end of week figure over the remaining 3.5 feeding days."""
    return weekly_part * 3.5


def weekly_feed_total(total_daily, weekly_part):
    """Combine the daily consumption with the projected end of week need."""
    projected = weekly_projection(weekly_part)
    return total_daily + projected


def validate_inputs(flock, age, mortality):
    """Reject the values that would make the feed estimate meaningless."""
    if flock <= 0:
        raise ValueError("flock must contain at least one bird")
    if age < 0:
        raise ValueError("age in weeks cannot be negative")
    if mortality < 0:
        raise ValueError("mortality rate cannot be negative")
    if mortality > 1:
        raise ValueError("mortality rate cannot exceed 1.0")


def feed(flock, age, mortality):
    """Return the surviving flock and the weekly total feed in kg."""
    validate_inputs(flock, age, mortality)
    base = base_feed_per_bird(age)
    total_daily = daily_total_feed(flock, base)
    loss = daily_mortality_loss(flock, mortality)
    surviving = surviving_flock(flock, loss)
    weekly_part = end_of_week_feed(surviving, age)
    weekly_feed = weekly_feed_total(total_daily, weekly_part)
    if age > 10:
        return surviving, weekly_feed + 20
    return surviving, weekly_feed


def mean(values):
    """Arithmetic mean of a non-empty sequence of numbers."""
    return sum(values) / len(values)


def per_bird_share(weekly, surviving):
    """Weekly feed need attributed to a single surviving bird."""
    return weekly / surviving


def format_report(label, surviving, weekly):
    """One human readable line describing a house's weekly feed need."""
    per_bird = per_bird_share(weekly, surviving)
    return f"{label:<16} birds: {surviving:>8.1f}  feed: {weekly:>9.2f} kg  ({per_bird:.3f} kg/bird)"


def main():
    houses = [
        ("Broiler house A", 1000, 12, 0.01),
        ("Broiler house B", 2500, 8, 0.004),
        ("Pullet house", 640, 15, 0.02),
    ]
    weekly_needs = []
    for label, flock, age, mortality in houses:
        surviving, weekly = feed(flock, age, mortality)
        weekly_needs.append(weekly)
        print(format_report(label, surviving, weekly))
    farm_total = sum(weekly_needs)
    print(f"Farm weekly feed : {farm_total:.2f} kg")
    print(f"Average per house: {mean(weekly_needs):.2f} kg")
    if farm_total > 10000:
        print("Order a bulk delivery this week.")


if __name__ == "__main__":
    main()

