def validate_inputs(boards, taper):
    if not isinstance(boards, int) or not isinstance(taper, int):
        raise TypeError("boards and taper must be integers")
    if boards < 0:
        raise ValueError("boards cannot be negative")
    if taper < 0:
        raise ValueError("taper cannot be negative")


def joint_length(boards):
    return boards * 3


def external_corners(taper):
    return taper * 2


def total_length(boards, taper):
    return joint_length(boards) + external_corners(taper)


def base_coat_volume(length):
    return length * 0.2


def top_coat_volume(length):
    return length * 0.1


def combined_volume(base_coat, top_coat):
    return base_coat + top_coat


def taper_allowance(volume, taper):
    if taper > 5:
        return volume + 2
    return volume


def buckets_for(volume):
    return volume / 15


def compound(boards, taper):
    validate_inputs(boards, taper)
    length = total_length(boards, taper)
    base_coat = base_coat_volume(length)
    top_coat = top_coat_volume(length)
    volume = taper_allowance(combined_volume(base_coat, top_coat), taper)
    buckets = buckets_for(volume)
    return (round(base_coat, 3), round(top_coat, 3), round(buckets, 3))


def whole_buckets(buckets):
    count = int(buckets)
    if buckets > count:
        return count + 1
    return count


def bucket_cost(count, price_per_bucket):
    return count * price_per_bucket


def format_report(boards, taper, price_per_bucket):
    base_coat, top_coat, buckets = compound(boards, taper)
    count = whole_buckets(buckets)
    lines = ["Boards: {0}, tapered corners: {1}".format(boards, taper)]
    lines.append("Base coat volume: {0} L".format(base_coat))
    lines.append("Top coat volume: {0} L".format(top_coat))
    lines.append("Buckets required: {0}".format(buckets))
    lines.append("Buckets to purchase: {0}".format(count))
    lines.append("Estimated cost: {0:.2f}".format(bucket_cost(count, price_per_bucket)))
    return "\n".join(lines)


def main():
    jobs = [(20, 8), (12, 3), (45, 11)]
    price_per_bucket = 18.5
    costs = []
    for boards, taper in jobs:
        print(format_report(boards, taper, price_per_bucket))
        count = whole_buckets(compound(boards, taper)[2])
        costs.append(bucket_cost(count, price_per_bucket))
        if count > 2:
            print("Bulk delivery recommended for this job")
        print("-" * 34)
    print("Grand total for {0} jobs: {1:.2f}".format(len(jobs), sum(costs)))


if __name__ == "__main__":
    main()

