PALLET_LENGTH = 20.0
PALLET_WIDTH = 8.0
STACK_HEIGHT = 8.5
BOX_WEIGHT = 15.0


def boxes_per_row(length):
    """How many boxes fit along the long pallet side."""
    return PALLET_LENGTH / length


def rows_per_tier(width):
    """How many rows fit across the short pallet side."""
    return PALLET_WIDTH / width


def boxes_per_tier(length, width):
    """Boxes in one complete layer on the pallet."""
    return boxes_per_row(length) * rows_per_tier(width)


def pallet_clearance(tiers):
    """Drop one tier so a tall load clears the pallet above."""
    return tiers - 1


def max_tiers(height):
    """Layers that fit in the usable stack space."""
    if height > 2:
        return pallet_clearance(STACK_HEIGHT / height)
    return STACK_HEIGHT / height


def total_boxes(length, width, height):
    """Boxes in the whole load."""
    return boxes_per_tier(length, width) * max_tiers(height)


def load_weight(length, width, height):
    """Weight of the whole load in pounds."""
    return total_boxes(length, width, height) * BOX_WEIGHT


def validate_dimensions(length, width, height):
    """Reject dimensions that cannot be loaded on the pallet."""
    for name, value in (("length", length), ("width", width), ("height", height)):
        if value <= 0:
            raise ValueError(name + " must be positive")
    if length > PALLET_LENGTH:
        raise ValueError("length exceeds the pallet side")
    if width > PALLET_WIDTH:
        raise ValueError("width exceeds the pallet side")
    if height > STACK_HEIGHT:
        raise ValueError("height exceeds the usable stack space")


def tiering(length, width, height):
    """Return boxes per tier, max tiers and total load weight."""
    validate_dimensions(length, width, height)
    return (
        boxes_per_tier(length, width),
        max_tiers(height),
        load_weight(length, width, height),
    )


def whole_boxes(length, width, height):
    """Count only the boxes that fit completely on the pallet."""
    return int(boxes_per_tier(length, width)) * int(max_tiers(height))


def format_size(length, width, height):
    return "%.1f x %.1f x %.1f" % (length, width, height)


def mean(values):
    return sum(values) / len(values)


def header():
    return "%-16s %8s %8s %13s %7s" % ("box", "per tier", "tiers", "weight", "packed")


def describe(length, width, height):
    """Build a one line report for a single box size."""
    per_tier, tiers, weight = tiering(length, width, height)
    return "%-16s %8.1f %8.2f %10.1f lb %7d" % (
        format_size(length, width, height),
        per_tier,
        tiers,
        weight,
        whole_boxes(length, width, height),
    )


def main():
    catalogue = [
        (2.0, 1.0, 2.5),
        (4.0, 2.0, 1.5),
        (5.0, 4.0, 3.0),
        (2.5, 1.6, 0.85),
    ]
    weights = []
    print(header())
    print("-" * 62)
    for length, width, height in catalogue:
        print(describe(length, width, height))
        weights.append(load_weight(length, width, height))
    print("-" * 62)
    print("average load weight: %.1f lb" % mean(weights))
    print("heaviest load: %.1f lb" % max(weights))


if __name__ == "__main__":
    main()

