"""Firewood planning helpers for stocking a campsite."""

FIRES_PER_SITE = 0.8
BASE_HOURS_PER_FIRE = 4
COLD_BONUS_HOURS = 2
COLD_LIMIT_F = 50
WOOD_PER_HOUR = 0.05
RESERVE_TRIGGER = 10
RESERVE_PILE = 1
ABSOLUTE_ZERO_F = -459.67


def validate(sites, nights, temperature):
    """Reject campsite plans that cannot be stocked."""
    if sites <= 0:
        raise ValueError("sites must be positive")
    if nights <= 0:
        raise ValueError("nights must be positive")
    if temperature < ABSOLUTE_ZERO_F:
        raise ValueError("temperature is below absolute zero")


def fires_per_night(sites):
    """Not every site lights a fire, so scale the site count down."""
    return sites * FIRES_PER_SITE


def hours_per_fire(temperature):
    """Cold nights keep each fire burning longer."""
    if temperature < COLD_LIMIT_F:
        return BASE_HOURS_PER_FIRE + COLD_BONUS_HOURS
    return BASE_HOURS_PER_FIRE


def total_fire_hours(fires, hours):
    return fires * hours


def wood_per_night(fires, hours):
    return total_fire_hours(fires, hours) * WOOD_PER_HOUR


def total_wood_raw(fires, hours, nights):
    return wood_per_night(fires, hours) * nights


def with_reserve(total):
    """Big orders get an extra pile held back for emergencies."""
    if total > RESERVE_TRIGGER:
        return total + RESERVE_PILE
    return total


def firewood(sites, nights, temperature):
    validate(sites, nights, temperature)
    fires = fires_per_night(sites)
    hours = hours_per_fire(temperature)
    raw_total = round(total_wood_raw(fires, hours, nights), 2)
    total = with_reserve(raw_total)
    return fires, hours, round(total, 2)


def format_report(sites, nights, temperature, result):
    fires, hours, total = result
    nightly = wood_per_night(fires, hours)
    raw_total = round(total_wood_raw(fires, hours, nights), 2)
    lines = [f"Campsite plan: {sites} sites for {nights} nights at {temperature} F"]
    lines.append(f"Fires per night: {fires}")
    lines.append(f"Hours per fire: {hours}")
    if temperature < COLD_LIMIT_F:
        lines.append("Cold-weather bonus burn time applied.")
    lines.append(f"Wood per night: {round(nightly, 2)} units")
    if total > raw_total:
        lines.append(f"Reserve pile of {RESERVE_PILE} unit added.")
    lines.append(f"Total wood to stock: {total} units")
    return "\n".join(lines)


def main():
    sites = 20
    nights = 3
    temperature = 40
    result = firewood(sites, nights, temperature)
    print(format_report(sites, nights, temperature, result))


if __name__ == "__main__":
    main()

