import math

SHIFT_HOURS = 8
THINNING_RATE = 500
FRUIT_SPACING = 3
DENSITY_LIMIT = 50
HIGH_DENSITY_HOURS_PER_TREE = 2
LONG_JOB_HOURS = 100


def _validate(trees, branches, blossoms):
    if trees <= 0:
        raise ValueError("trees must be a positive count")
    if branches <= 0:
        raise ValueError("branches per tree must be a positive count")
    if blossoms <= 0:
        raise ValueError("blossoms per branch must be a positive count")


def branch_count(trees, branches):
    return trees * branches


def total_blossoms(trees, branches, blossoms):
    return branch_count(trees, branches) * blossoms


def target_fruit(blossoms):
    return blossoms / FRUIT_SPACING


def retained_blossoms(trees, branches, blossoms):
    return branch_count(trees, branches) * target_fruit(blossoms)


def thinning_load(total, retained):
    return total - retained


def base_labor_hours(amount):
    return amount / THINNING_RATE


def density_surcharge(trees):
    return trees * HIGH_DENSITY_HOURS_PER_TREE


def add_surcharge(hours, trees):
    return hours + density_surcharge(trees)


def workers_needed(hours):
    return hours / SHIFT_HOURS


def thinning(trees, branches, blossoms):
    _validate(trees, branches, blossoms)
    total = total_blossoms(trees, branches, blossoms)
    retained = retained_blossoms(trees, branches, blossoms)
    amount = thinning_load(total, retained)
    hours = base_labor_hours(amount)
    if blossoms > DENSITY_LIMIT:
        hours = add_surcharge(hours, trees)
    return retained, amount, hours


def format_report(name, trees, branches, blossoms):
    retained, amount, hours = thinning(trees, branches, blossoms)
    if blossoms > DENSITY_LIMIT:
        density = "high"
    else:
        density = "standard"
    crew = math.ceil(workers_needed(hours))
    lines = [f"Block {name} ({density} density)"]
    lines.append(f"  retained blossoms : {retained:.1f}")
    lines.append(f"  blossoms to thin  : {amount:.1f}")
    lines.append(f"  labor hours       : {hours:.1f}")
    lines.append(f"  crew for one shift: {crew}")
    if hours > LONG_JOB_HOURS:
        lines.append("  note: spread the work over several days")
    return "\n".join(lines)


def main():
    blocks = [("North", 10, 20, 60), ("South", 5, 15, 30), ("Ridge", 40, 25, 75)]
    for name, trees, branches, blossoms in blocks:
        print(format_report(name, trees, branches, blossoms))


if __name__ == "__main__":
    main()

