"""Irrigation timer configuration for a misting system."""

DRY_HUMIDITY = 50.0
HOT_TEMP = 30.0
FLOOD_LIMIT = 100.0
FLOOD_RELIEF = 10.0
MINUTES_PER_DAY = 1440.0


def validate_inputs(temp, humidity, sunlight):
    """Reject readings that cannot describe a real growing environment."""
    if sunlight <= 0.0:
        raise ValueError("sunlight hours must be positive")
    if humidity < 0.0:
        raise ValueError("humidity cannot be negative")


def base_duration(temp, humidity):
    """Minutes of misting per cycle, extended when the air is dry."""
    duration = float(temp)
    duration -= 20.0
    if humidity < DRY_HUMIDITY:
        duration += 5.0
    return duration


def base_frequency(temp, sunlight):
    """Minutes between cycles, halved when the day is hot."""
    if temp > HOT_TEMP:
        return 30.0 / float(sunlight)
    return 60.0 / float(sunlight)


def total_water(duration, frequency):
    """Litres consumed, trimmed once the beds risk flooding."""
    litres = float(duration)
    litres *= 12.0
    litres /= frequency
    if litres > FLOOD_LIMIT:
        litres -= FLOOD_RELIEF
    return litres


def misting(temp, humidity, sunlight):
    validate_inputs(temp, humidity, sunlight)
    duration = base_duration(temp, humidity)
    frequency = base_frequency(temp, sunlight)
    water = total_water(duration, frequency)
    return duration, frequency, water


def daily_cycles(frequency):
    return MINUTES_PER_DAY / frequency


def format_schedule(temp, humidity, sunlight):
    duration, frequency, water = misting(temp, humidity, sunlight)
    cycles = daily_cycles(frequency)
    parts = ["duration {0:.1f} min".format(duration)]
    parts.append("every {0:.1f} min".format(frequency))
    parts.append("{0:.0f} cycles/day".format(cycles))
    parts.append("{0:.1f} litres".format(water))
    return " | ".join(parts), water


def main():
    readings = [(35.0, 40.0, 1.5), (28.0, 65.0, 6.0), (42.0, 20.0, 0.5), (50.0, 30.0, 12.0)]
    fleet = 0.0
    for temp, humidity, sunlight in readings:
        text, water = format_schedule(temp, humidity, sunlight)
        print(text)
        fleet += water
    print("fleet demand {0:.1f} litres".format(fleet))
    if fleet > 150.0:
        print("warning: fleet demand exceeds the reservoir refill rate")


if __name__ == "__main__":
    main()

