STATION_SPACING_KM = 2.5
WATER_PER_DEGREE = 0.02
CUP_VOLUME_L = 0.15
HOT_THRESHOLD_C = 25.0
HOT_EXTRA_CUPS = 0.5
MIN_SENSIBLE_TEMP_C = -20.0


def validate(runners, temp, distance):
    if runners <= 0:
        raise ValueError("runners must be positive")
    if distance <= 0:
        raise ValueError("distance must be positive")
    if temp < MIN_SENSIBLE_TEMP_C:
        raise ValueError("temperature is below any plausible race condition")


def stations_needed(distance):
    return distance / STATION_SPACING_KM


def water_per_runner(temp):
    return temp * WATER_PER_DEGREE


def water_per_station(runners, per_runner):
    return runners * per_runner


def base_cups(station_water):
    return station_water / CUP_VOLUME_L


def hydration(runners, temp, distance):
    validate(runners, temp, distance)
    stations = stations_needed(distance)
    per_runner = water_per_runner(temp)
    station_water = water_per_station(runners, per_runner)
    cups = base_cups(station_water)
    if temp > HOT_THRESHOLD_C:
        cups = with_heat_surcharge(cups, runners)
    total = total_cups(cups, stations)
    return stations, cups, total


def heat_surcharge(runners):
    return runners * HOT_EXTRA_CUPS


def with_heat_surcharge(cups, runners):
    return cups + heat_surcharge(runners)


def cups_to_liters(cups):
    return cups * CUP_VOLUME_L


def total_cups(cups, stations):
    return cups * stations


def format_plan(name, runners, temp, distance):
    stations, cups, total = hydration(runners, temp, distance)
    station_liters = cups_to_liters(cups)
    race_liters = cups_to_liters(total)
