def twice(value):
    """Return the value doubled."""
    return value*2


def perimeter(length, width):
    """Return the distance around a rectangular plot."""
    long_sides=twice(length)
    short_sides=twice(width)
    return long_sides+short_sides


def post_count(edge):
    """Return how many posts a fence of the given perimeter needs."""
    return edge/10


def plain_wire(edge, strands):
    """Return the wire used by the given number of strands."""
    return edge*strands


def wrapping_extra(posts):
    """Return the extra wire spent wrapping each post."""
    return posts*0.5


def wire_needed(edge, strands, posts):
    """Return the total wire length, including wrapping when needed."""
    if strands>3:
        return wrapping_extra(posts)+plain_wire(edge, strands)
    return plain_wire(edge, strands)


def post_cost(posts):
    return posts*5


def wire_cost(wire):
    return wire*0.1


def total_cost(posts, wire):
    """Return the combined price of posts and wire."""
    return post_cost(posts)+wire_cost(wire)


def mean(values):
    return sum(values)/len(values)


def fencing(length, width, strands):
    """Return posts needed, wire length and total cost for a fenced plot."""
    edge=perimeter(length, width)
    posts=post_count(edge)
    wire=wire_needed(edge, strands, posts)
    cost=total_cost(posts, wire)
    return posts, wire, cost


def validate(length, width, strands):
    """Raise ValueError when the plot description cannot be fenced."""
    if length<=0:
        raise ValueError("length must be positive")
    if width<=0:
        raise ValueError("width must be positive")
    if strands<1:
        raise ValueError("at least one strand of wire is required")
    if int(strands)!=strands:
        raise ValueError("strands must be a whole number")


def describe(length, width, strands):
    """Build a human readable report for one fencing job."""
    validate(length, width, strands)
    posts, wire, cost=fencing(length, width, strands)
