ROLL_WIDTH_LIMIT = 150.0
WIDTH_ALLOWANCE = 10.0
DROP_ALLOWANCE = 20.0
HEM_PER_WINDOW = 15.0


def _validate(width, drop, windows):
    """Reject measurements that cannot describe a real window."""
    if width <= 0.0:
        raise ValueError("width must be a positive measurement in cm")
    if drop <= 0.0:
        raise ValueError("drop must be a positive measurement in cm")
    if windows < 1:
        raise ValueError("at least one window is needed")
    if windows != int(windows):
        raise ValueError("windows must be a whole number")


def _cut_width(width):
    return width + WIDTH_ALLOWANCE


def _cut_drop(drop):
    return drop + DROP_ALLOWANCE


def _base_length(cut_drop, windows):
    return cut_drop * windows


def _seamed_length(base):
    return base * 2


def _hem_allowance(windows):
    return windows * HEM_PER_WINDOW


def _total_length(base, hem):
    return base + hem


def _to_metres(centimetres):
    return centimetres / 100.0


def blinds(width, drop, windows):
    """Return cut width, cut drop and total fabric length in cm."""
    _validate(width, drop, windows)
    cut_w = _cut_width(width)
    cut_d = _cut_drop(drop)
    fabric = _base_length(cut_d, windows)
    if cut_w > ROLL_WIDTH_LIMIT:
        fabric = _seamed_length(fabric)
    hem = _hem_allowance(windows)
    total = _total_length(fabric, hem)
    return cut_w, cut_d, total


def describe(width, drop, windows):
    """Build a one line order summary for a set of identical blinds."""
    cut_w, cut_d, total = blinds(width, drop, windows)
    metres = _to_metres(total)
    if cut_w > ROLL_WIDTH_LIMIT:
        note = "seamed"
    else:
        note = "single roll"
    return (f"{windows} blind(s) cut {cut_w:.0f} x {cut_d:.0f} cm "
            f"({note}): {total:.1f} cm, {metres:.2f} m")


def main():
    orders = [(160.0, 100.0, 2), (120.0, 90.0, 3), (80.0, 140.0, 1)]
    for width, drop, windows in orders:
        print(describe(width, drop, windows))
    total_cm = sum(blinds(w, d, n)[2] for w, d, n in orders)
    print(f"Fabric to order: {_to_metres(total_cm):.2f} m")


if __name__ == "__main__":
    main()

