def validate_inputs(volume, ec, ph):
    """Reject tank parameters that make no physical sense."""
    if volume <= 0.0:
        raise ValueError("volume must be a positive number of litres")
    if ec <= 0.0:
        raise ValueError("ec must be a positive conductivity reading")
    if ph < 0.0:
        raise ValueError("ph must lie between 0 and 14")
    if ph > 14.0:
        raise ValueError("ph must lie between 0 and 14")


def salt_load(volume, ec):
    """Total dissolved salt index of the tank."""
    return volume * ec


def base_nitrogen(volume, ec):
    """Nitrogen milligrams carried by the salt load of the tank."""
    nitrogen = salt_load(volume, ec)
    nitrogen *= 2.0
    return nitrogen


def base_phosphorus(volume, ec):
    """Phosphorus milligrams carried by the salt load of the tank."""
    phosphorus = salt_load(volume, ec)
    phosphorus *= 0.5
    return phosphorus


def low_ec_boost(volume):
    """Extra nitrogen used to push a weak solution back up."""
    return volume * 5.0


def acid_demand(volume, ph):
    """Millilitres of acid required to drag the tank down to pH 5.8."""
    demand = ph
    demand -= 5.8
    demand *= 0.1
    demand *= volume
    return demand


def dosing(volume, ec, ph):
    """Return nitrogen, phosphorus and acid doses for one fertilizer tank."""
    validate_inputs(volume, ec, ph)
    nitrogen = base_nitrogen(volume, ec)
    if ec < 1.5:
        nitrogen += low_ec_boost(volume)
    phosphorus = base_phosphorus(volume, ec)
    if ph > 6.5:
        phosphorus *= 1.2
    acid = acid_demand(volume, ph)
    return round(nitrogen, 4), round(phosphorus, 4), round(acid, 4)


def format_recipe(name, volume, ec, ph, nitrogen, phosphorus, acid):
    """Build a one-line human readable mixing instruction for a tank."""
    salts = nitrogen
    salts += phosphorus
    header = "{0} ({1:.0f} L, EC {2:.2f}, pH {3:.2f})".format(name, volume, ec, ph)
    body = "N {0:.1f} mg, P {1:.1f} mg, salts {2:.1f} mg".format(nitrogen, phosphorus, salts)
    if acid < 0.0:
        tail = "add {0:.1f} mL base".format(abs(acid))
    else:
        tail = "add {0:.1f} mL acid".format(acid)
    return " | ".join((header, body, tail))


def main():
    tanks = [
        ("Leafy greens", 100.0, 1.2, 7.0),
        ("Tomato bloom", 250.0, 2.4, 6.4),
        ("Seedling mist", 500.0, 0.9, 5.5),
    ]
    acid_total = 0.0
    for name, volume, ec, ph in tanks:
        nitrogen, phosphorus, acid = dosing(volume, ec, ph)
        print(format_recipe(name, volume, ec, ph, nitrogen, phosphorus, acid))
        if acid > 0.0:
            acid_total += acid
    print("Acid drawn from the drum: {0:.1f} mL".format(acid_total))


if __name__ == "__main__":
    main()

