import math

WRAP_PITCH = 0.5
OVERLAP_RATE = 0.2
ANCHOR_HEIGHT = 2.0
ANCHOR_WRAPS = 2.0
ROLL_LENGTH = 500.0


def validate_order(pallets, height, girth):
    """Reject shipping orders that cannot be wrapped."""
    if pallets < 0:
        raise ValueError("pallet count cannot be negative")
    if height <= 0:
        raise ValueError("pallet height must be positive")
    if girth <= 0:
        raise ValueError("pallet girth must be positive")


def wraps_per_pallet(height):
    return height / WRAP_PITCH


def base_film_length(wraps, girth):
    return wraps * girth


def anchor_length(girth):
    return girth * ANCHOR_WRAPS


def plain_overlap(base):
    return base * OVERLAP_RATE


def overlap_allowance(base, height, girth):
    allowance = plain_overlap(base)
    if height > ANCHOR_HEIGHT:
        return allowance + anchor_length(girth)
    return allowance


def film_per_pallet(height, girth):
    wraps = wraps_per_pallet(height)
    base = base_film_length(wraps, girth)
    allowance = overlap_allowance(base, height, girth)
    return base + allowance


def total_film(pallets, per_pallet):
    return pallets * per_pallet


def film_on_rolls(count):
    return count * ROLL_LENGTH


def spare_film(stocked, used):
    return stocked - used


def rolls_needed(pallets, per_pallet):
    film = total_film(pallets, per_pallet)
    return film / ROLL_LENGTH


def shrinkwrap(pallets, height, girth):
    validate_order(pallets, height, girth)
    wraps = wraps_per_pallet(height)
    per_pallet = film_per_pallet(height, girth)
    rolls = rolls_needed(pallets, per_pallet)
    return wraps, per_pallet, rolls


def format_report(pallets, height, girth):
    wraps, per_pallet, rolls = shrinkwrap(pallets, height, girth)
    film = total_film(pallets, per_pallet)
    ordered = math.ceil(rolls)
    stocked = film_on_rolls(ordered)
    leftover = spare_film(stocked, film)
    lines = [f"Order: {pallets} pallets, {height:.2f} m high, {girth:.2f} m girth"]
    lines.append(f"  wraps per pallet: {wraps:.1f}")
    lines.append(f"  film per pallet:  {per_pallet:.2f} m")
    lines.append(f"  rolls needed:     {rolls:.2f}")
    lines.append(f"  rolls to pull:    {ordered}")
    if leftover > 0:
        lines.append(f"  spare film:       {leftover:.2f} m")
    return "\n".join(lines)


def main():
