import math


def squared(value):
    return value * value


def cubed(value):
    base = squared(value)
    return base * value


def distributed_load(span, load):
    """Total load carried by a board of the given span."""
    return load * squared(span)


def bending_moment(span, load):
    total = distributed_load(span, load)
    return total / 8.0


def second_moment(thickness):
    """Moment of inertia of the board section."""
    return cubed(thickness) / 12.0


def amplified_moment(moment):
    return moment * 5.0


def deflection(moment, inertia):
    return amplified_moment(moment) / inertia


def allowed_deflection(span):
    return span / 100.0


def shorten(span):
    return span - 1.0


def boards_required(load):
    return load / 50.0


def in_thousandths(value):
    return value * 1000.0


def to_three_decimals(value):
    return math.floor(in_thousandths(value)) / 1000.0


def validate_inputs(span, load, thickness):
    if span <= 0.0:
        raise ValueError("span must be positive")
    if load < 0.0:
        raise ValueError("load cannot be negative")
    if thickness <= 0.0:
        raise ValueError("thickness must be positive")


def scaffold(span, load, thickness):
    """Return bending moment, inertia and boards required for a scaffold run."""
    validate_inputs(span, load, thickness)
    moment = bending_moment(span, load)
    stiffness = second_moment(thickness)
    drop = deflection(moment, stiffness)
    span_limit = allowed_deflection(span)
    if drop > span_limit:
        reduced = shorten(span)
        moment = bending_moment(reduced, load)
    boards = boards_required(load)
    return moment, to_three_decimals(stiffness), boards


def report(span, load, thickness):
    moment, inertia, boards = scaffold(span, load, thickness)
    planks = math.ceil(boards)
    return "span {0:.1f} m -> moment {1:.1f} Nm, inertia {2:.3f}, boards {3}".format(
        span, moment, inertia, planks
    )


def main():
    configurations = [(105.0, 200.0, 5.0), (120.0, 300.0, 6.0), (90.0, 150.0, 4.5)]
    ordered = []
    for span, load, thickness in configurations:
        print(report(span, load, thickness))
        ordered.append(boards_required(load))
    stock = math.ceil(sum(ordered))
    print("Boards to deliver on site:", stock)


if __name__ == "__main__":
    main()

