import math

MASS = 500.0
RADIUS = 0.6
DISCHARGE_SECONDS = 120.0
ENERGY_CAP_THRESHOLD = 1000000.0
SAFETY_FRACTION = 0.10


def half(value):
    return value / 2.0


def squared(value):
    return value * value


def scaled_by_pi(value):
    return math.pi * value


def rad_per_second(rpm):
    return scaled_by_pi(rpm) / 30.0


def moment_of_inertia(mass, radius):
    return half(mass) * squared(radius)


def kinetic_energy(rpm):
    inertia = moment_of_inertia(MASS, RADIUS)
    omega = rad_per_second(rpm)
    return half(inertia) * squared(omega)


def safety_margin(energy):
    return energy * SAFETY_FRACTION


def usable_energy(energy):
    if energy > ENERGY_CAP_THRESHOLD:
        return energy - safety_margin(energy)
    return energy


def power_output(energy):
    return energy / DISCHARGE_SECONDS


def megajoules(joules):
    return joules / 1000000.0


def kilowatts(watts):
    return watts / 1000.0


def validate(states):
    if not states:
        raise ValueError("at least one rotational speed is required")
    for speed in states:
        if isinstance(speed, bool) or not isinstance(speed, (int, float)):
            raise TypeError("rotational speeds must be numbers")
        if speed < 0:
            raise ValueError("rotational speeds must not be negative")


def evaluate(states):
    validate(states)
    energies = [kinetic_energy(rpm) for rpm in states]
    peak = max(energies)
    fastest = max(states)
    stored = kinetic_energy(fastest)
    usable = usable_energy(stored)
    power = power_output(usable)
    return (peak, usable, power)


def format_row(rpm, energy):
    stored = megajoules(energy)
    available = megajoules(usable_energy(energy))
    return f"{rpm:8.0f} rpm  stored {stored:8.3f} MJ  usable {available:8.3f} MJ"


def main():
    states = [3000.0, 4000.0]
    for rpm in states:
        print(format_row(rpm, kinetic_energy(rpm)))
    peak, usable, power = evaluate(states)
    print(f"peak stored energy : {megajoules(peak):.3f} MJ")
    print(f"usable energy      : {megajoules(usable):.3f} MJ")
    print(f"discharge power    : {kilowatts(power):.3f} kW")
    if peak > usable:
        trimmed = megajoules(safety_margin(peak))
        print(f"safety cap removed {trimmed:.3f} MJ from the fastest state")


if __name__ == "__main__":
    main()

