from decimal import Decimal, ROUND_DOWN

MASS = 40000.0
DECELERATION = 1.2
BASE_RECOVERY = 0.6
HEAT_PENALTY = 0.05
DISTANCE_LIMIT = 100.0
JOULES_PER_MEGAJOULE = 1000000.0


def square(value):
    return value * value


def halve(value):
    return value / 2


def kinetic_energy(speed):
    return MASS * square(speed)


def stop_time(speed):
    return speed / DECELERATION


def stopping_distance(speed):
    swept = square(stop_time(speed))
    return halve(DECELERATION * swept)


def recovery_efficiency(distance):
    if distance > DISTANCE_LIMIT:
        return BASE_RECOVERY - HEAT_PENALTY
    return BASE_RECOVERY


def megajoules(joules):
    return joules / JOULES_PER_MEGAJOULE


def recovered_megajoules(speed, efficiency):
    energy = megajoules(kinetic_energy(speed))
    return energy * efficiency


def to_tenths(value):
    quantized = Decimal(value).quantize(Decimal("0.1"), ROUND_DOWN)
    return float(quantized)


def validated_speeds(speeds):
    clean = []
    for speed in speeds:
        if speed < 0:
            raise ValueError("train speeds must not be negative")
        clean.append(float(speed))
    return clean


def simulate(speeds):
    results = []
    for speed in validated_speeds(speeds):
        distance = stopping_distance(speed)
        efficiency = recovery_efficiency(distance)
        energy = recovered_megajoules(speed, efficiency)
        results.append((to_tenths(distance), to_tenths(energy)))
    return results


def main():
    speeds = [15, 20, 25, 30]
    rows = simulate(speeds)
    for speed, row in zip(speeds, rows):
        print(f"{speed:5.1f} m/s | stop in {row[0]:7.1f} m | recovered {row[1]:6.1f} MJ")


if __name__ == "__main__":
    main()

