import math

GRAVITY = 9.81
TIDAL_CURRENT = 5.0
ENERGY_CONSTANT = 1000


def squared(value):
    return value * value


def wave_speed(depth):
    """Speed of a shallow water wave, rounded to one decimal."""
    return round(math.sqrt(GRAVITY * depth), 1)


def froude_number(depth):
    speed = wave_speed(depth)
    return TIDAL_CURRENT / speed


def froude_excess(depth):
    """Froude number squared minus one."""
    fr = froude_number(depth)
    return squared(fr) - 1.0


def half_depth(depth):
    return depth / 2.0


def bore_height(depth):
    speed = wave_speed(depth)
    if TIDAL_CURRENT <= speed:
        return 0.0
    excess = froude_excess(depth)
    return round(excess * half_depth(depth), 2)


def bore_energy(height):
    return round(squared(height) * ENERGY_CONSTANT)


def validate(depths):
    checked = []
    for depth in depths:
        if isinstance(depth, bool):
            raise TypeError("depths must be numbers, got {!r}".format(depth))
        if not isinstance(depth, (int, float)):
            raise TypeError("depths must be numbers, got {!r}".format(depth))
        if depth <= 0:
            raise ValueError("depths must be positive, got {!r}".format(depth))
        checked.append(float(depth))
    return checked


def predict(depths):
    results = []
    for depth in validate(depths):
        speed = wave_speed(depth)
        height = bore_height(depth)
        energy = bore_energy(height)
        results.append((speed, height, energy))
    return results


def report(depths):
    predictions = predict(depths)
    lines = []
    for depth, row in zip(validate(depths), predictions):
        speed, height, energy = row
        text = "depth {:.1f} m: wave {:.1f} m/s, bore {:.2f} m, energy {:d} J".format(
            depth, speed, height, energy)
        lines.append(text)
    active = []
    for row in predictions:
        if row[1] > 0.0:
            active.append(row)
    total = sum(row[2] for row in predictions)
    lines.append("{:d} of {:d} sections form a bore".format(len(active), len(predictions)))
    lines.append("total bore energy: {:d} J".format(total))
    return lines


def main():
    depths = [2, 3]
    for line in report(depths):
        print(line)
    print(predict(depths))


if __name__ == "__main__":
    main()

