import math

TRAVEL_SPEED = 30.0
GAS_FLOW_RATE = 15.0
PRE_FLOW = 0.1
POST_FLOW = 0.15
SHORT_POST_FLOW = 0.2
SHORT_WELD_LIMIT = 10.0
CYLINDER_VOLUME = 50.0
RESERVE_MARGIN = 5.0


def validate(welds):
    if not isinstance(welds, (list, tuple)):
        raise TypeError("welds must be given as a list or tuple of lengths")
    lengths = []
    for position, raw in enumerate(welds, 1):
        if isinstance(raw, bool) or not isinstance(raw, (int, float)):
            raise TypeError(f"weld {position} is not a numeric length")
        length = float(raw)
        if length <= 0.0:
            raise ValueError(f"weld {position} must have a positive length")
        lengths.append(length)
    return lengths


def post_flow_for(length):
    if length < SHORT_WELD_LIMIT:
        return SHORT_POST_FLOW
    return POST_FLOW


def travel_time(length):
    return length / TRAVEL_SPEED


def overhead_time(length):
    return PRE_FLOW + post_flow_for(length)


def weld_time(length):
    return travel_time(length) + overhead_time(length)


def weld_gas(length):
    return weld_time(length) * GAS_FLOW_RATE


def cylinders_for(total_gas):
    return math.ceil(total_gas / CYLINDER_VOLUME)


def capacity_for(cylinders):
    return cylinders * CYLINDER_VOLUME


def spare_gas(cylinders, total_gas):
    return capacity_for(cylinders) - total_gas


def weld_tag(length):
    if length < SHORT_WELD_LIMIT:
        return "short bead"
    return "standard"


def calculate(welds):
    lengths = validate(welds)
    gases = [weld_gas(length) for length in lengths]
    total_gas = round(sum(gases), 2)
    return total_gas, cylinders_for(total_gas)


def format_report(welds):
    lengths = validate(welds)
    lines = []
    for position, length in enumerate(lengths, 1):
        minutes = weld_time(length)
        gas = weld_gas(length)
        tag = weld_tag(length)
        lines.append(
            f"Weld {position}: {length:.1f} cm ({tag}) -> "
            f"{minutes:.3f} min, {gas:.2f} L"
        )
    total_gas, cylinders = calculate(lengths)
    spare = spare_gas(cylinders, total_gas)
    lines.append(f"Total gas consumed: {total_gas:.2f} L")
    lines.append(f"Cylinders needed ({CYLINDER_VOLUME:.0f} L each): {cylinders}")
    lines.append(f"Spare gas in the last cylinder: {spare:.2f} L")
    return "\n".join(lines)


def main():
    job = [50, 5]
    print(format_report(job))
    total_gas, cylinders = calculate(job)
    if spare_gas(cylinders, total_gas) < RESERVE_MARGIN:
        print("Gas reserve is thin, take an extra cylinder to the site.")


if __name__ == "__main__":
    main()

