AIR_PER_CUBIC_METER = 0.5
BLOWER_CAPACITY = 30.0
HOT_CORE_THRESHOLD = 40.0
HOT_CORE_FACTOR = 1.2
HOURS_PER_DAY = 24


def required_airflow(volume):
    """Cubic meters of air per hour needed by a pile of the given volume."""
    return volume * AIR_PER_CUBIC_METER


def base_duty(volume):
    """Share of the blower capacity taken up by one pile."""
    return required_airflow(volume) / BLOWER_CAPACITY


def duty_cycle(volume):
    """Fraction of the time the blower must run for one pile."""
    if volume > HOT_CORE_THRESHOLD:
        return base_duty(volume) * HOT_CORE_FACTOR
    return base_duty(volume)


def daily_runtime(volume):
    """Hours per day the blower runs for one pile."""
    return duty_cycle(volume) * HOURS_PER_DAY


def validate(volumes):
    """Return the volumes as floats, rejecting negative or non-numeric input."""
    clean = []
    for index, volume in enumerate(volumes):
        if not isinstance(volume, (int, float)):
            raise TypeError("volume at position {} is not a number".format(index))
        if volume < 0:
            raise ValueError("volume at position {} is negative".format(index))
        clean.append(float(volume))
    return clean


def aerate(volumes):
    """Daily blower runtime in hours for each compost pile volume."""
    return [daily_runtime(volume) for volume in validate(volumes)]


def report(volumes):
    """Build a human readable aeration schedule for the given piles."""
    piles = validate(volumes)
    runtimes = aerate(piles)
    lines = []
    for volume, hours in zip(piles, runtimes):
        airflow = required_airflow(volume)
        if volume > HOT_CORE_THRESHOLD:
            status = "hot core"
        else:
            status = "ambient"
        lines.append(
            "{:6.1f} m3  {:6.1f} m3/h  {:<8}  {:5.1f} h/day".format(
                volume, airflow, status, hours
            )
        )
    total = sum(runtimes)
    lines.append("total blower time: {:.1f} h/day".format(total))
    return "\n".join(lines)


def main():
    piles = [10, 50]
    print(report(piles))
    saturated = []
    for volume in piles:
        if daily_runtime(volume) >= HOURS_PER_DAY:
            saturated.append(volume)
