GRAVITY = 9.81
SPRING_COUNT = 96
RESTING_LENGTH = 0.15
SPRING_CONSTANT = 3000.0
DYNAMIC_MULTIPLIER = 3
SAFE_LIMIT = 0.2


def validate_weights(weights):
    if not isinstance(weights, (list, tuple)):
        raise TypeError("weights must be a list or tuple of numbers")
    for weight in weights:
        if not isinstance(weight, (int, float)):
            raise TypeError("each weight must be a number")
        if weight <= 0:
            raise ValueError("each weight must be positive")


def total_force(weight):
    force = weight
    force *= GRAVITY
    force *= DYNAMIC_MULTIPLIER
    return force


def spring_stretch(weight):
    share = total_force(weight)
    share /= SPRING_COUNT
    return share / SPRING_CONSTANT


def analyze(weights):
    validate_weights(weights)
    results = []
    for weight in weights:
        stretch = spring_stretch(weight)
        extended = RESTING_LENGTH
        extended += stretch
        if extended > SAFE_LIMIT:
            flag = True
        else:
            flag = False
        results.append((extended, flag))
    return results


def count_overextended(results):
    count = 0
    for _extended, flag in results:
        if flag:
            count += 1
    return count


def format_row(weight, extended, flag):
    stretch = extended
    stretch -= RESTING_LENGTH
    usage = extended
    usage /= SAFE_LIMIT
    usage *= 100
    if flag:
        status = "OVEREXTENDED"
    else:
        status = "ok"
    template = "{:6.1f} kg | length {:.4f} m | stretch {:.4f} m | {:5.1f}% of limit | {}"
    return template.format(weight, extended, stretch, usage, status)


def main():
    weights = [50, 90]
    results = analyze(weights)
    for weight, entry in zip(weights, results):
        extended, flag = entry
        print(format_row(weight, extended, flag))
    flagged = count_overextended(results)
    safe = len(results)
    safe -= flagged
    print("safe jumpers: {} | flagged jumpers: {}".format(safe, flagged))
    if flagged > 0:
        print("Warning: reduce jumper weight or inspect the springs.")


if __name__ == "__main__":
    main()

