text_nat:
SPROCKET_TEETH = 7
CHAIN_PITCH_FACTOR = 0.019
SECONDS_PER_MINUTE = 60
EFFECTIVE_MASS = 2.5
ENERGY_THRESHOLD = 100.0
BRAKE_POWER = 5000.0


def validate_speed(rpm):
    """Return the engine speed as a float, rejecting nonsense input."""
    if isinstance(rpm, bool) or not isinstance(rpm, (int, float)):
        raise TypeError("engine speed must be a number, got %r" % (rpm,))
    value = float(rpm)
    if value < 0.0:
        raise ValueError("engine speed cannot be negative: %r" % (rpm,))
    return value


def teeth_per_minute(rpm):
    """Number of sprocket teeth passing the guide bar each minute."""
    return validate_speed(rpm) * SPROCKET_TEETH


def travel_per_minute(rpm):
    """Chain travel in metres per minute."""
    return teeth_per_minute(rpm) * CHAIN_PITCH_FACTOR


def chain_speed(rpm):
    """Chain speed in metres per second."""
    return travel_per_minute(rpm) / SECONDS_PER_MINUTE


def squared_speed(speed):
    """Square of the chain speed."""
    return speed * speed


def kinetic_term(speed):
    """Mass weighted term of the kinetic energy."""
    return EFFECTIVE_MASS * squared_speed(speed)


def kickback_energy(speed):
    """Kinetic energy of a sudden kickback, in joules."""
    return kinetic_term(speed) / 2.0


def brake_time(energy):
    """Time the chain brake needs to absorb the kickback energy."""
    if energy > ENERGY_THRESHOLD:
        return energy / BRAKE_POWER
    return 0.0


def assess(speeds):
    """Map engine speeds to (chain speed, brake stopping time) pairs."""
    results = []
    for rpm in speeds:
        speed = chain_speed(rpm)
        energy = kickback_energy(speed)
        stop = brake_time(energy)
        results.append((round(speed, 1), round(stop, 2)))
    return results


def format_row(rpm, speed, stop):
    """One line of the kickback report."""
    if stop > 0.0:
        return "%7.0f rpm: %5.1f m/s, brake stops in %.2f s" % (rpm, speed, stop)
    return "%7.0f rpm: %5.1f m/s, no brake action needed" % (rpm, speed)


def report(speeds):
    """Build a human readable report for the given engine speeds."""
    lines = []
    for rpm, pair in zip(speeds, assess(speeds)):
        speed, stop = pair
        lines.append(format_row(rpm, speed, stop))
    return "\n".join(lines)


def main():
    speeds = [2500, 8000, 12000]
    print(report(speeds))
    worst = max(stop for speed, stop in assess(speeds))
    print("Longest stopping time: %.2f s" % worst)


if __name__ == "__main__":
    main()

