text_nat:
BASE_POWER_WATTS = 4000.0
MASS_PER_PASSENGER_KG = 75.0
WALKWAY_SPEED_MPS = 0.6
GRAVITY = 9.81
ROLLING_RESISTANCE = 0.02
CROWD_THRESHOLD = 50
CROWD_FRICTION_WATTS = 500.0
OPERATING_HOURS = 12.0
WATTS_PER_KILOWATT = 1000.0


def passenger_mass(count):
    return count * MASS_PER_PASSENGER_KG


def rolling_force(mass):
    weight = mass * GRAVITY
    return weight * ROLLING_RESISTANCE


def passenger_power(count):
    mass = passenger_mass(count)
    force = rolling_force(mass)
    return force * WALKWAY_SPEED_MPS


def crowd_penalty(count):
    if count > CROWD_THRESHOLD:
        return CROWD_FRICTION_WATTS
    return 0.0


def total_power(count):
    extra = passenger_power(count)
    penalty = crowd_penalty(count)
    loaded = BASE_POWER_WATTS + extra
    return loaded + penalty


def daily_energy(count):
    power = total_power(count)
    kilowatts = power / WATTS_PER_KILOWATT
    return kilowatts * OPERATING_HOURS


def validate_count(count):
    if isinstance(count, bool):
        raise TypeError("passenger counts must be numeric")
    if not isinstance(count, (int, float)):
        raise TypeError("passenger counts must be numeric")
    if count < 0:
        raise ValueError("passenger counts cannot be negative")


def calculate(passengers):
    energies = []
    for count in passengers:
        validate_count(count)
        energy = daily_energy(count)
        energies.append(round(energy, 1))
    return energies


def average_energy(energies):
    total = sum(energies)
    return total / len(energies)


def format_report(passengers, energies):
    lines = []
    for count, energy in zip(passengers, energies):
        lines.append(f"{count:>5} passengers -> {energy:>7.1f} kWh/day")
    return "\n".join(lines)


def main():
    passengers = [0, 10, 60, 120]
    energies = calculate(passengers)
    print(format_report(passengers, energies))
    mean = average_energy(energies)
    print(f"mean daily energy: {mean:.1f} kWh")
    spread = max(energies) - min(energies)
    print(f"spread between quietest and busiest day: {spread:.1f} kWh")
    crowded = [c for c in passengers if c > CROWD_THRESHOLD]
    print(f"days above the crowd threshold: {len(crowded)}")


if __name__ == "__main__":
    main()

