WAKE_PENALTY = 1.15
SPEED_DRAG = (
    TOWING_SPEED * TOWING_SPEED
)


def validate(displacements):
    weights = []
    for index, value in enumerate(displacements):
        if not isinstance(value, (int, float)):
            raise TypeError("displacement #%d is not numeric" % index)
        if value <= 0:
            raise ValueError("displacement #%d must be positive" % index)
        weights.append(float(value))
    return weights


def static_load(weight):
    return weight * WEIGHT_FACTOR


def hull_resistance(weight):
    return static_load(weight) + SPEED_DRAG


def wake_affected(weight):
    return weight > WAKE_THRESHOLD


def apply_wake(resistance):
    return resistance * WAKE_PENALTY


def required_horsepower(resistance):
    return resistance / THRUST_PER_HP


def line_area(resistance):
    return resistance / SAFE_WORKING_LOAD


def line_thickness(resistance):
    return math.sqrt(line_area(resistance))


def tenths(value):
    return value * 10.0


def thickness_rating(thickness):
    return math.floor(tenths(thickness)) / 10.0


def estimate(displacements):
    results = []
    for weight in validate(displacements):
        resistance = hull_resistance(weight)
        if wake_affected(weight):
