import math

KILN_LENGTH_M = 50.0
KILN_DIAMETER_M = 3.0
SLOPE_DEGREES = 3.0
ANGLE_OF_REPOSE_DEGREES = 35.0
TARGET_TIME_MIN = 40.0


def repose_factor():
    """Empirical factor 1.77 times the root of the angle of repose."""
    return 1.77 * math.sqrt(ANGLE_OF_REPOSE_DEGREES)


def bed_travel():
    """Length of material travel weighted by the repose factor."""
    return KILN_LENGTH_M * repose_factor()


def kiln_resistance():
    """Geometric resistance of the shell, from diameter and incline slope."""
    return KILN_DIAMETER_M * SLOPE_DEGREES


def sweep_rate(speed):
    """How fast the shell moves material along at the given rpm."""
    return kiln_resistance() * speed


def residence_time(speed):
    """Minutes the material spends inside the kiln."""
    return bed_travel() / sweep_rate(speed)


def shortfall(time):
    """Minutes of burning still missing to reach the target time."""
    return TARGET_TIME_MIN - time


def recycle_ratio(time):
    """Fraction of the product fed back when the burn was too short."""
    if time < TARGET_TIME_MIN:
        return shortfall(time) / TARGET_TIME_MIN
    return 0.0


def validate_speeds(speeds):
    """Return the speeds as floats, rejecting values a kiln cannot run at."""
    checked = []
    for speed in speeds:
        if not isinstance(speed, (int, float)):
            raise TypeError("rotation speeds must be numeric")
        if speed <= 0:
            raise ValueError("rotation speeds must be greater than zero rpm")
        checked.append(float(speed))
    return checked


def simulate(speeds):
    """Return (residence time, recycle ratio) pairs for each rotation speed."""
    results = []
    for speed in validate_speeds(speeds):
        time = round(residence_time(speed), 1)
        ratio = round(recycle_ratio(time), 2)
        results.append((time, ratio))
    return results


def verdict(ratio):
    """Name the burning quality implied by a recycle ratio."""
    if ratio > 0:
        return "undercooked"
    return "adequate"


def describe(speed, time, ratio):
    """One readable line for a single simulated rotation speed."""
    return f"{speed:.2f} rpm: {time:.1f} min ({verdict(ratio)}), recycle {ratio:.2f}"


def format_report(speeds, rows):
    """Render the simulation output, one line per speed."""
    lines = []
    for speed, (time, ratio) in zip(speeds, rows):
        lines.append(describe(speed, time, ratio))
    return "\n".join(lines)


def mean_ratio(rows):
    """Average recycle ratio over the simulated speeds."""
    total = sum(ratio for _time, ratio in rows)
    return total / len(rows)


def main():
    speeds = [1.5, 2.5]
    rows = simulate(speeds)
    print(format_report(speeds, rows))
    print(f"mean recycle ratio: {mean_ratio(rows):.2f}")


if __name__ == "__main__":
    main()

