import math

DIAMETER = 3.2
LINK_SPACING = 15.0
TWIST_COST = 2.0
WASTE_THRESHOLD = 5000.0
WASTE_EXTRA = 50.0


def casing_radius(diameter):
    return diameter / 2


def cross_section_area(diameter):
    radius = casing_radius(diameter)
    return math.pi * math.pow(radius, 2)


def stuffed_length(volume, area):
    return volume / area


def link_count(length, spacing):
    return int(length / spacing)


def twist_allowance(links, cost):
    return links * cost


def waste_allowance(volume):
    if volume > WASTE_THRESHOLD:
        return WASTE_EXTRA
    return 0.0


def total_casing_length(stuffed, twists, waste):
    return sum((stuffed, twists, waste))


def casing_per_link(casing, links):
    return casing / links


def validate(batches):
    if not isinstance(batches, list):
        raise TypeError("batches must be a list of volumes")
    for volume in batches:
        if isinstance(volume, bool):
            raise TypeError("volumes must be numbers")
        if not isinstance(volume, (int, float)):
            raise TypeError("volumes must be numbers")
        if volume < 0:
            raise ValueError("volumes must not be negative")


def compute(batches):
    validate(batches)
    area = cross_section_area(DIAMETER)
    results = []
    for volume in batches:
        stuffed = stuffed_length(volume, area)
        links = link_count(stuffed, LINK_SPACING)
        twists = twist_allowance(links, TWIST_COST)
        waste = waste_allowance(volume)
        total = total_casing_length(stuffed, twists, waste)
        results.append((math.ceil(total), links))
    return results


def format_row(volume, length, links):
    return "{:>9.0f} cm3 {:>8d} cm {:>6d}".format(volume, length, links)


def report(batches):
    results = compute(batches)
    lines = ["   volume     casing  links"]
    for volume, pair in zip(batches, results):
        lines.append(format_row(volume, pair[0], pair[1]))
    total_casing = sum(pair[0] for pair in results)
    total_links = sum(pair[1] for pair in results)
    lines.append("total casing: {} cm".format(total_casing))
    lines.append("total links: {}".format(total_links))
    if total_links > 0:
        average = casing_per_link(total_casing, total_links)
        lines.append("casing per link: {:.2f} cm".format(average))
    return lines


def main():
    for line in report([1000, 6000]):
        print(line)


if __name__ == "__main__":
    main()

