import math

BAR_TO_PASCAL = 100000.0
BORE_DIAMETER = 0.05
ROD_DIAMETER = 0.02
STROKE_LENGTH = 0.2
STOP_REDUCTION = 0.02
FORCE_LIMIT = 1500.0
LITRES_PER_CUBIC_METRE = 1000.0


def half(value):
    return value / 2.0


def square(value):
    return value * value


def circle_area(diameter):
    radius = half(diameter)
    return math.pi * square(radius)


def to_pascal(bar):
    return bar * BAR_TO_PASCAL


def extension_force(pressure_pa, bore_area):
    return pressure_pa * bore_area


def annulus_area(bore_area, rod_area):
    return bore_area - rod_area


def retraction_force(pressure_pa, bore_area, rod_area):
    annulus = annulus_area(bore_area, rod_area)
    return pressure_pa * annulus


def effective_stroke(force):
    if force > FORCE_LIMIT:
        return STROKE_LENGTH - STOP_REDUCTION
    return STROKE_LENGTH


def swept_volume(bore_area, stroke):
    return bore_area * stroke


def to_litres(cubic_metres):
    return cubic_metres * LITRES_PER_CUBIC_METRE


def air_consumption(bore_area, stroke, bar):
    swept = swept_volume(bore_area, stroke)
    litres = to_litres(swept)
    return litres * bar


def validate(pressures):
    if not pressures:
        raise ValueError("at least one operating pressure is required")
    for bar in pressures:
        if bar <= 0.0:
            raise ValueError("pressure must be positive, got {0}".format(bar))


def analyse(pressures):
    validate(pressures)
    bore_area = circle_area(BORE_DIAMETER)
    rod_area = circle_area(ROD_DIAMETER)
    rows = []
    for bar in pressures:
        pressure_pa = to_pascal(bar)
        push = extension_force(pressure_pa, bore_area)
        pull = retraction_force(pressure_pa, bore_area, rod_area)
        stroke = effective_stroke(push)
        rows.append({"bar": bar, "extension": push, "retraction": pull,
                     "stroke": stroke,
                     "litres": air_consumption(bore_area, stroke, bar)})
    return rows


def evaluate(pressures):
    forces = []
    for row in analyse(pressures):
        forces.append((int(row["extension"]), int(row["retraction"])))
    return forces


def format_row(row):
    if row["stroke"] < STROKE_LENGTH:
        note = "stop fitted"
    else:
        note = "full stroke"
    return "{0:4.1f} bar  push {1:8.1f} N  pull {2:8.1f} N  {3:5.3f} m  {4:6.2f} L  {5}".format(
        row["bar"], row["extension"], row["retraction"], row["stroke"],
        row["litres"], note)


def main():
    pressures = [6.0, 8.0]
    rows = analyse(pressures)
    for row in rows:
        print(format_row(row))
    total = sum(row["litres"] for row in rows)
    print("total air per cycle: {0:.2f} L".format(total))
    print(evaluate(pressures))


if __name__ == "__main__":
    main()

