BASIS = 200
HANDICAP_RATE = 0.90


def validate_game(game):
    """Check that a game entry is a pair of non-negative numbers."""
    if len(game) != 2:
        raise ValueError("each game needs a scratch score and an average")
    scratch, average = game
    if scratch < 0:
        raise ValueError("scratch score cannot be negative")
    if average < 0:
        raise ValueError("average cannot be negative")
    return scratch, average


def gap_to_basis(average):
    """How far the player average falls below the 200 basis."""
    return BASIS - average


def handicap(average):
    """Ninety percent of the gap below the basis, truncated."""
    gap = gap_to_basis(average)
    if gap > 0:
        return int(gap * HANDICAP_RATE)
    return 0


def total(scratch, average):
    """Scratch score plus the earned handicap."""
    return scratch + handicap(average)


def totals(games):
    """Totals for every game, in the order the games were given."""
    results = []
    for game in games:
        scratch, average = validate_game(game)
        results.append(total(scratch, average))
    return results


def mean_total(values):
    """Arithmetic mean of the given totals."""
    return sum(values) / len(values)


def score(games):
    """Return (highest total, lowest total, average total)."""
    all_totals = totals(games)
    if not all_totals:
        raise ValueError("at least one game is required")
    highest = max(all_totals)
    lowest = min(all_totals)
    mean = mean_total(all_totals)
    return (highest, lowest, mean)


def report(games):
    """Build a human readable summary of a series of games."""
    lines = []
    for index, game in enumerate(games, start=1):
        scratch, average = validate_game(game)
        earned = handicap(average)
        lines.append(
            "Game {0}: scratch {1}, handicap {2}, total {3}".format(
                index, scratch, earned, scratch + earned
            )
        )
    highest, lowest, mean = score(games)
    lines.append("Highest total: {0}".format(highest))
    lines.append("Lowest total: {0}".format(lowest))
    lines.append("Average total: {0:.2f}".format(mean))
    lines.append("Spread: {0}".format(highest - lowest))
    return "\n".join(lines)


def main():
    series = [(150, 140), (180, 205), (120, 90), (210, 200)]
    print(report(series))


if __name__ == "__main__":
    main()

