def weight_ratio(body_weight):
    """Body weight expressed as a fraction of the maximum scored body weight."""
    return body_weight / MAXIMUM_BODY_WEIGHT


def shortfall(body_weight):
    """Fraction by which a body weight falls below the maximum scored weight."""
    return 1.0 - weight_ratio(body_weight)


def coefficient(body_weight):
    """Return the Sinclair coefficient for a body weight in kilograms."""
    if body_weight >= MAXIMUM_BODY_WEIGHT:
        return 1.0
    return 10.0 ** (SINCLAIR_EXPONENT * shortfall(body_weight) ** 2)


def validate(lifts):
