def validate_interval(distance, seconds):
    if distance <= 0:
        raise ValueError("distance must be positive, got {0}".format(distance))
    if seconds <= 0:
        raise ValueError("time must be positive, got {0}".format(seconds))


def speed_of(distance, seconds):
    return distance / seconds


def pace_per_500(speed):
    return 500.0 / speed


def is_sprint(pace):
    return pace < 120.0


def watts_from_pace(pace):
    split = pace / 500.0
    return 2.80 / (split * split * split)


def rowing(intervals):
    results = []
    for distance, seconds in intervals:
        validate_interval(distance, seconds)
        speed = speed_of(distance, seconds)
        pace = pace_per_500(speed)
        results.append((pace, watts_from_pace(pace)))
    return results


def format_pace(pace):
    minutes = int(pace // 60)
    rest = pace - minutes * 60
    return "{0}:{1:04.1f}".format(minutes, rest)


def describe(intervals):
    lines = []
    paced = rowing(intervals)
    for index, (distance, seconds) in enumerate(intervals):
        pace, watts = paced[index]
        kind = "sprint" if is_sprint(pace) else "steady"
        lines.append(
            "{0}m in {1:.0f}s -> {2}/500m, {3:.1f}W ({4})".format(
                distance, seconds, format_pace(pace), watts, kind
            )
        )
    return lines


def summarize(intervals):
    paced = rowing(intervals)
    total_distance = 0.0
    total_time = 0.0
    sprints = 0
    for index, (distance, seconds) in enumerate(intervals):
        total_distance += distance
        total_time += seconds
        if is_sprint(paced[index][0]):
            sprints += 1
    average_pace = pace_per_500(speed_of(total_distance, total_time))
    return {
        "distance": total_distance,
        "time": total_time,
        "sprints": sprints,
        "pace": average_pace,
        "watts": watts_from_pace(average_pace),
    }


def main():
    workout = [(500, 95.0), (2000, 450.0), (1000, 215.0), (250, 42.5)]
    for line in describe(workout):
        print(line)
    totals = summarize(workout)
    print("total: {0:.0f}m in {1:.0f}s".format(totals["distance"], totals["time"]))
    print("average: {0}/500m at {1:.1f}W".format(format_pace(totals["pace"]), totals["watts"]))
    print("sprint intervals: {0} of {1}".format(totals["sprints"], len(workout)))


if __name__ == "__main__":
    main()

