OPTIMUM_TIME = 85
TIME_PENALTY_PER_SECOND = 0.25
RAIL_PENALTY = 4
FAST_ROUND_TIME = 80


def validate_round(entry):
    """Check a single (time, rails) tuple and return it as (float, int)."""
    if len(entry) != 2:
        raise ValueError("each round needs a time and a rail count")
    time_taken, rails = entry
    if time_taken <= 0:
        raise ValueError("time taken must be positive")
    if rails < 0:
        raise ValueError("rail count cannot be negative")
    return float(time_taken), int(rails)


def time_penalties(time_taken):
    """Quarter of a penalty for every second beyond the optimum time."""
    if time_taken <= OPTIMUM_TIME:
        return 0.0
    seconds_over = time_taken
    seconds_over -= OPTIMUM_TIME
    return seconds_over * TIME_PENALTY_PER_SECOND


def jumping_penalties(rails):
    """Four penalties for every knocked rail."""
    return rails * RAIL_PENALTY


def total_penalties(time_taken, rails):
    """Time faults plus jumping faults for one round."""
    total = time_penalties(time_taken)
    total += jumping_penalties(rails)
    return total


def is_fast_clear(time_taken, total):
    """A clear round inside the fast time carries no penalties at all."""
    if total != 0:
        return False
    return time_taken < FAST_ROUND_TIME


def jumping(rounds):
    """Return (fast clear rounds, average total penalties) for the rounds."""
    if not rounds:
        return (0, 0.0)
    fast_clears = 0
    penalty_sum = 0.0
    for entry in rounds:
        time_taken, rails = validate_round(entry)
        total = total_penalties(time_taken, rails)
        penalty_sum += total
        if is_fast_clear(time_taken, total):
            fast_clears += 1
    return (fast_clears, penalty_sum / len(rounds))


def describe_round(entry):
    """One readable line of detail for a round."""
    time_taken, rails = validate_round(entry)
    total = total_penalties(time_taken, rails)
    label = "fast clear" if is_fast_clear(time_taken, total) else "penalised"
    return "{0:.1f}s, {1} rail(s): {2:.2f} penalties ({3})".format(
        time_taken, rails, total, label)


def report(rounds):
    """Build a full text report of the competition."""
    lines = [describe_round(entry) for entry in rounds]
    fast_clears, average = jumping(rounds)
    lines.append("fast clear rounds: {0}".format(fast_clears))
    lines.append("average penalties: {0:.2f}".format(average))
    return "\n".join(lines)


def main():
    competition = [(76.0, 0), (85.0, 0), (91.0, 1), (78.5, 2), (104.0, 0)]
    print(report(competition))
    fast_clears, average = jumping(competition)
    if average > 4:
        print("The course rode tough.")
    elif fast_clears >= 2:
        print("A speedy field of horses.")
    else:
        print("A steady day's jumping.")


if __name__ == "__main__":
    main()

