def wave_average(scores):
    if len(scores) != 5:
        raise ValueError("each wave needs exactly five judge scores")
    for score in scores:
        if score < 0:
            raise ValueError("judge scores cannot be negative")
        if score > 10:
            raise ValueError("judge scores cannot exceed ten")
    ordered = sorted(scores)
    counting = ordered[1:4]
    return sum(counting) / len(counting)


def is_excellent(average):
    return average >= 8.0


def wave_averages(surfer_waves):
    return [wave_average(wave) for wave in surfer_waves]


def heat_total(surfer_waves):
    averages = sorted(wave_averages(surfer_waves))
    best = averages[-2:]
    return sum(best)


def normalize_heat(waves):
    if not waves:
        return []
    head = waves[0]
    if head and isinstance(head[0], (list, tuple)):
        return [list(surfer) for surfer in waves]
    return [list(waves)]


def excellent_count(surfer_waves):
    return sum(1 for average in wave_averages(surfer_waves) if is_excellent(average))


def surfing(waves):
    heats = normalize_heat(waves)
    return [heat_total(surfer_waves) for surfer_waves in heats]


def format_report(waves):
    heats = normalize_heat(waves)
    totals = surfing(waves)
    lines = []
    for number, surfer_waves in enumerate(heats, start=1):
        total = round(totals[number - 1], 2)
        excellent = excellent_count(surfer_waves)
        if excellent == 1:
            label = "wave"
        else:
            label = "waves"
        lines.append("Surfer {}: heat total {} ({} excellent {})".format(number, total, excellent, label))
    return lines


def main():
    heat = [
        [[7.0, 8.0, 8.5, 9.0, 7.5], [6.0, 6.5, 7.0, 5.5, 6.5], [9.0, 9.5, 8.5, 9.0, 8.0]],
