def score_differential(gross, course_rating, slope_rating):
    """Return the slope-adjusted differential for a single round."""
    strokes=(
        gross-course_rating
    )
    scaled=(
        strokes*113
    )
    return scaled/slope_rating


def validate_round(position, entry):
    """Check that one round is a usable (gross, rating, slope) triple."""
    if len(entry)!=3:
        raise ValueError("round {} must have exactly three values".format(position))
    for value in entry:
        if not isinstance(value, (int, float)):
            raise TypeError("round {} contains a non-numeric value".format(position))
    gross, course_rating, slope_rating=entry
    if slope_rating<=0:
        raise ValueError("round {} has a non-positive slope rating".format(position))
    if gross<=0:
        raise ValueError("round {} has a non-positive gross score".format(position))
    return gross, course_rating, slope_rating


def differentials(rounds):
    """Build the sorted list of differentials for all rounds."""
    values=[]
    for position, entry in enumerate(rounds, start=1):
        gross, course_rating, slope_rating=validate_round(position, entry)
        values.append(score_differential(gross, course_rating, slope_rating))
    values.sort()
    return values


def count_used(total):
    """Return how many of the lowest differentials feed into the index."""
    if total<5:
        return 1
    return 3


def average(values):
    """Return the mean of the given values."""
    return sum(values)/len(values)


def handicap(rounds):
    """Return the handicap index computed from recent rounds."""
    values=differentials(rounds)
    if not values:
        raise ValueError("at least one round is required")
    used=count_used(len(values))
    chosen=average(values[:used])
    return chosen*0.96


def format_report(rounds):
    """Produce a short human readable summary of the handicap calculation."""
    values=differentials(rounds)
    lines=["Rounds played: {}".format(len(values))]
    for number, value in enumerate(values, start=1):
        lines.append("  differential {}: {:.2f}".format(number, value))
    lines.append("Differentials used: {}".format(count_used(len(values))))
    index=handicap(rounds)
    lines.append("Handicap index: {:.1f}".format(index))
    if index<0:
        lines.append("Index is a plus handicap.")
    return "\n".join(lines)


def main():
    early_season=[(92, 71.2, 128), (88, 70.0, 122), (95, 72.4, 131)]
    full_season=list(early_season)
    full_season.extend([
        (85, 70.0, 122),
        (90, 71.2, 128),
        (81, 69.5, 118),
        (87, 72.4, 131),
    ])
    print(format_report(early_season))
    print()
    print(format_report(full_season))


if __name__=="__main__":
    main()

