def _ratio(numerator, denominator):
    """Return the simple per-attempt share used by every rating component."""
    return numerator / denominator


def _shift(value, offset):
    """Return value reduced by offset."""
    return value - offset


def _scaled(value, offset, factor):
    """Shift a per-attempt share and stretch it onto the rating scale."""
    shifted = _shift(value, offset)
    return shifted * factor


def _clamp(value, low, high):
    """Cap a rating component to the legal window."""
    if value > high:
        return high
    if value < low:
        return low
    return value


def _validate(stats):
    if len(stats) != 5:
        raise ValueError("stats needs attempts, completions, yards, TDs, INTs")
    attempts, completions, yards, touchdowns, interceptions = stats
    if attempts <= 0:
        raise ValueError("attempts must be positive")
    if completions > attempts:
        raise ValueError("completions cannot exceed attempts")
    if touchdowns > completions:
        raise ValueError("touchdowns cannot exceed completions")
    if interceptions < 0:
        raise ValueError("interceptions cannot be negative")
    if yards < 0:
        raise ValueError("passing yards cannot be negative")


def passer(stats):
    """Compute the NFL passer rating for a tuple of passing statistics."""
    _validate(stats)
    attempts, completions, yards, touchdowns, interceptions = stats
    completion_share = _ratio(completions, attempts)
    yard_share = _ratio(yards, attempts)
    touchdown_share = _ratio(touchdowns, attempts)
    interception_share = _ratio(interceptions, attempts)
    components = [
        _scaled(completion_share, 0.3, 5.0),
        _scaled(yard_share, 3.0, 0.25),
        touchdown_share * 20.0,
        _shift(2.375, interception_share * 25.0),
    ]
    total = sum(_clamp(component, 0.0, 2.375) for component in components)
    average = _ratio(total, 6.0)
    return average * 100.0


def describe(name, rating):
    """Format one quarterback's line for the report."""
    return "{0:<18}{1:>7.1f}".format(name, rating)


def main():
    season = [
        ("Peyton Manning", (450, 305, 3739, 30, 9)),
        ("Aaron Rodgers", (520, 372, 4299, 39, 4)),
        ("Drew Brees", (658, 448, 5069, 46, 22)),
        ("Perfect Passer", (10, 8, 125, 3, 0)),
    ]
    leader = ""
    top = 0.0
    for name, stats in season:
        rating = passer(stats)
        print(describe(name, rating))
        if rating > top:
            top = rating
            leader = name
    print("Best rating: " + leader)


if __name__ == "__main__":
    main()

