BASE_COURSE_TIME = 1200.0
PENALTY_LOOP_TIME = 22.5
FATIGUE_THRESHOLD = 100.0
FATIGUE_PENALTY = 15.0
MAX_TARGETS = 5


def validate_bouts(shootings):
    if not isinstance(shootings, (list, tuple)):
        raise TypeError("shootings must be a list of (time, misses) tuples")
    for index, bout in enumerate(shootings):
        if len(bout) != 2:
            raise ValueError(f"bout {index} must have exactly two values")
        shoot_time, misses = bout
        if shoot_time < 0:
            raise ValueError(f"bout {index} has a negative shooting time")
        if misses < 0:
            raise ValueError(f"bout {index} has a negative miss count")
        if misses > MAX_TARGETS:
            raise ValueError(f"bout {index} has more misses than targets")


def total_shooting_time(shootings):
    return sum(bout[0] for bout in shootings)


def total_misses(shootings):
    return sum(bout[1] for bout in shootings)


def penalty_time(misses):
    return misses * PENALTY_LOOP_TIME


def fatigue_penalty(penalty):
    if penalty > FATIGUE_THRESHOLD:
        return FATIGUE_PENALTY
    return 0.0


def biathlon(shootings):
    validate_bouts(shootings)
    shooting = total_shooting_time(shootings)
    misses = total_misses(shootings)
    penalty = penalty_time(misses)
    fatigue = fatigue_penalty(penalty)
    return sum([BASE_COURSE_TIME, shooting, penalty, fatigue])


def format_time(seconds):
    minutes, rest = divmod(seconds, 60)
    return f"{int(minutes)}:{rest:04.1f}"


def gap_to_leader(total, leader_total):
    return total - leader_total


def race_results(athletes):
    results = [(name, biathlon(bouts)) for name, bouts in athletes]
    return sorted(results, key=lambda entry: entry[1])


def print_results(athletes):
    standings = race_results(athletes)
    leader_total = standings[0][1]
    for place, (name, total) in enumerate(standings, start=1):
        gap = gap_to_leader(total, leader_total)
        line = f"{place}. {name:<8} {format_time(total)}"
        if gap > 0:
            print(f"{line} (+{gap:.1f})")
        else:
            print(line)


