SEGMENT_LENGTH = 10.0
SLED_MASS = 210.0


def _ratio(numerator, denominator):
    return numerator / denominator


def _interval(later, earlier):
    return later - earlier


def _square(value):
    return value * value


def _half(value):
    return _ratio(value, 2.0)


def _velocity(distance, elapsed):
    if elapsed <= 0.0:
        raise ValueError("split intervals must be positive")
    return _ratio(distance, elapsed)


def _kinetic_energy(mass, velocity):
    squared = _square(velocity)
    return _half(mass * squared)


def _validate(pushes):
    if len(pushes) != 3:
        raise ValueError("expected splits at ten, twenty and thirty metres")
    previous = 0.0
    for split in pushes:
        value = float(split)
        if value <= previous:
            raise ValueError("splits must increase along the track")
        previous = value


def zone_velocities(pushes):
    t10, t20, t30 = pushes
    first = _velocity(SEGMENT_LENGTH, t10)
    second_gap = _interval(t20, t10)
    second = _velocity(SEGMENT_LENGTH, second_gap)
    third_gap = _interval(t30, t20)
    third = _velocity(SEGMENT_LENGTH, third_gap)
    return first, second, third


def bobsled(pushes):
    _validate(pushes)
    v10, v20, v30 = zone_velocities(pushes)
    max_velocity = max(v10, v20, v30)
    delta_v = _interval(v20, v10)
    delta_t = _interval(pushes[1], pushes[0])
    acceleration = _ratio(delta_v, delta_t)
    kinetic_energy = _kinetic_energy(SLED_MASS, v30)
    return max_velocity, acceleration, kinetic_energy


def parse_splits(text):
    fields = text.replace(",", " ").split()
    return [float(field) for field in fields]


def format_report(label, stats):
    top_speed, acceleration, energy = stats
    header = f"{label}: "
    body = f"vmax {top_speed:.3f} m/s | a {acceleration:.3f} m/s^2 | Ek {energy:.1f} J"
    return header + body


def main():
    runs = {"Crew A": "5.10, 8.02, 10.41", "Crew B": "5.42, 8.55, 11.20"}
    fastest_label = None
    fastest_speed = 0.0
    for label, raw in runs.items():
        splits = parse_splits(raw)
        stats = bobsled(splits)
        print(format_report(label, stats))
        if stats[0] > fastest_speed:
            fastest_speed = stats[0]
            fastest_label = label
    print(f"Best push velocity: {fastest_label} at {fastest_speed:.3f} m/s")


if __name__ == "__main__":
