def validate_routine(routine):
    if len(routine) != 3:
        raise ValueError("each routine needs difficulty, deductions and penalty")
    difficulty, deductions, penalty = routine
    if len(deductions) != 5:
        raise ValueError("each routine needs exactly five execution deductions")
    if difficulty < 0:
        raise ValueError("start difficulty cannot be negative")
    if penalty < 0:
        raise ValueError("neutral deduction cannot be negative")
    for deduction in deductions:
        if deduction < 0:
            raise ValueError("execution deductions cannot be negative")
    return difficulty, deductions, penalty


def execution_score(deductions):
    return 10.0 - sum(deductions)


def final_score(routine):
    difficulty, deductions, penalty = validate_routine(routine)
    execution = execution_score(deductions)
    score = execution
    score += difficulty
    score -= penalty
    if execution < 7.5:
        score -= 0.3
    return score


def gymnastics(routines):
    best = None
    for routine in routines:
        score = final_score(routine)
        if best is None or score > best:
            best = score
    return best


def describe_routine(index, routine):
    difficulty, deductions, penalty = validate_routine(routine)
    execution = execution_score(deductions)
    total = final_score(routine)
    lost = sum(deductions)
    if execution < 7.5:
        label = "flawed"
    else:
        label = "clean"
    return (
        f"Routine {index}: D {difficulty:.1f}, E {execution:.2f} "
        f"({lost:.2f} lost, {label}), ND {penalty:.1f} -> {total:.2f}"
    )


def main():
