VALUES = {
    "red": 1,
    "yellow": 2,
    "green": 3,
    "brown": 4,
    "blue": 5,
    "pink": 6,
    "black": 7,
}

FOUL_PENALTY = 4
MAX_BREAK = 147


def normalise(pots):
    """Clean up the raw list of potted colours and reject unknown names."""
    cleaned = []
    for index, ball in enumerate(pots):
        if not isinstance(ball, str):
            raise TypeError("pot %d is not a colour name" % index)
        colour = ball.strip().lower()
        if colour not in VALUES:
            raise ValueError("unknown colour: %r" % ball)
        cleaned.append(colour)
    return cleaned


def is_foul(colour, previous):
    """A second red straight after a red counts as a foul."""
    if colour != "red":
        return False
    return previous == "red"


def snooker(pots):
    balls = normalise(pots)
    score = 0
    previous = None
    for colour in balls:
        if is_foul(colour, previous):
            score -= FOUL_PENALTY
        else:
            score += VALUES[colour]
        if score > MAX_BREAK:
            return ("invalid break", 0)
        previous = colour
    count = len(balls)
    if count == 0:
        return (0, 0)
    average = float(score)
    average /= count
    return (score, average)


def describe(pots):
    """Build a one line summary of a break for the report."""
    total, average = snooker(pots)
    if total == "invalid break":
