    return math.sqrt(square(x) + square(y))

def average(values):
    return math.fsum(values) / len(values)

def needs_adjustment(offset):
    return abs(offset) > 2.0

def score_shot(x, y):
    distance = radial_distance(x, y)
    if distance <= 1.0:
        return 10, distance
    return 5, distance

def average_offsets(shots):
    horizontals = [shot[0] for shot in shots]
    verticals = [shot[1] for shot in shots]
    return average(horizontals), average(verticals)

def target(shots):
    if not shots:
        return 0, 0.0, False
    scores = []
    distances = []
    for x, y in shots:
        points, distance = score_shot(x, y)
        scores.append(points)
        distances.append(distance)
    total_points = sum(scores)
    max_distance = max(distances)
    offsets = average_offsets(shots)
    windage = needs_adjustment(offsets[0])
    return total_points, max_distance, windage

def format_report(shots):
