def sum_list(numbers):
    """Return the sum of all numbers in the given list."""
    total = 0
    for value in numbers:
        total = total + value
    return total


def validate(numbers):
    """Return the list unchanged, raising TypeError for non-numeric input."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("expected a list of numbers")
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("item %d is not a number: %r" % (index, value))
    return list(numbers)


def mean(numbers):
    """Return the arithmetic mean, or 0 for an empty list."""
    count = len(numbers)
    if count == 0:
        return 0
    return sum_list(numbers) / count


def running_totals(numbers):
    """Return the list of partial sums of numbers."""
    totals = []
    carry = 0
    for value in numbers:
        carry = carry + value
        totals.append(carry)
    return totals


def spread(numbers):
    """Return the difference between the largest and smallest value."""
    if not numbers:
        return 0
    low = numbers[0]
    high = numbers[0]
    for value in numbers[1:]:
        if value < low:
            low = value
        elif value > high:
            high = value
    return high - low


def format_number(value):
    """Render a number without a trailing .0 for whole floats."""
    if isinstance(value, float) and value == int(value):
        value = int(value)
    return str(value)


def report(numbers):
    """Build a multi-line summary of the statistics of numbers."""
    checked = validate(numbers)
    lines = ["values: " + ", ".join(format_number(v) for v in checked)]
    lines.append("count: " + format_number(len(checked)))
    lines.append("sum: " + format_number(sum_list(checked)))
    lines.append("mean: " + format_number(mean(checked)))
    lines.append("spread: " + format_number(spread(checked)))
    steps = running_totals(checked)
    lines.append("running: " + ", ".join(format_number(s) for s in steps))
    return "\n".join(lines)


def main():
    samples = [[1, 2, 3, 4], [], [-5, 10, 2.5], [7]]
    for sample in samples:
        print(report(sample))
        print("-" * 20)
    bad = [1, "two", 3]
    try:
        print(sum_list(validate(bad)))
    except TypeError as error:
        print("rejected: " + str(error))


if __name__ == "__main__":
    main()

