def list_intersection(list1, list2):
    """Return the common elements of two lists, preserving list1's order."""
    validate_inputs(list1, list2)
    pool = set(list2)
    seen = set()
    common = []
    for item in list1:
        if item in pool and item not in seen:
            seen.add(item)
            common.append(item)
    return common


def validate_inputs(list1, list2):
    for name, value in (("list1", list1), ("list2", list2)):
        if not isinstance(value, (list, tuple)):
            raise TypeError(f"{name} must be a list or tuple")


def list_union(list1, list2):
    validate_inputs(list1, list2)
    merged = list(list1)
    known = set(list1)
    for item in list2:
        if item not in known:
            known.add(item)
            merged.append(item)
    return merged


def list_difference(list1, list2):
    validate_inputs(list1, list2)
    excluded = set(list2)
    return [item for item in list1 if item not in excluded]


def jaccard_index(list1, list2):
    shared = len(list_intersection(list1, list2))
    total = len(list_union(list1, list2))
    if total == 0:
        return 0.0
    return shared / total


def average(values):
    if not values:
        return 0.0
    return sum(values) / len(values)


def format_list(values):
    body = ", ".join(repr(value) for value in values)
    return f"[{body}]"


def describe(list1, list2):
    shared = list_intersection(list1, list2)
    only_left = list_difference(list1, list2)
    only_right = list_difference(list2, list1)
    ratio = jaccard_index(list1, list2)
    lines = [f"{format_list(list1)} vs {format_list(list2)}"]
    lines.append(f"  common     : {format_list(shared)}")
    lines.append(f"  only left  : {format_list(only_left)}")
    lines.append(f"  only right : {format_list(only_right)}")
    lines.append(f"  similarity : {ratio:.1%}")
    return "\n".join(lines)


