import math

def geometric_mean(numbers):
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    product = 1.0
    for num in numbers:
        if num <= 0:
            raise ValueError("All numbers must be positive.")
        product *= num

    n = len(numbers)
    result = product ** (1 / n)
    return result

