STATUS_MESSAGES = {
    200: 'OK',
    404: 'Not Found',
    500: 'Internal Server Error',
}

UNKNOWN_MESSAGE = 'Unknown Status'


def check_http_status(status_code):
    """Return a descriptive string for a few well known HTTP status codes."""
    code = int(status_code)
    return STATUS_MESSAGES.get(code, UNKNOWN_MESSAGE)


def is_known(status_code):
    """Report whether a status code has a descriptive message."""
    return check_http_status(status_code) != UNKNOWN_MESSAGE


def status_class(status_code):
    """Return the coarse class name of an HTTP status code."""
    code = int(status_code)
    if code < 100:
        return 'invalid'
    if code > 599:
        return 'invalid'
    family = str(code)[0]
    if family == '1':
        return 'informational'
    if family == '2':
        return 'success'
    if family == '3':
        return 'redirection'
    if family == '4':
        return 'client error'
    return 'server error'


def parse_status_codes(text):
    """Collect the integer codes contained in a raw input line."""
    codes = []
    cleaned = text.replace(',', ' ')
    for token in cleaned.split():
        if token.isdigit():
            codes.append(int(token))
    return codes


def describe(status_code):
    """Build a one line description combining message and class."""
    message = check_http_status(status_code)
    group = status_class(status_code)
    return '{0}: {1} ({2})'.format(status_code, message, group)


def summarize(status_codes):
    """Count how many codes are recognised and how many are not."""
    known = [code for code in status_codes if is_known(code)]
    return {'known': len(known), 'unknown': len(status_codes) - len(known)}


def build_report(text):
    """Turn a raw line of status codes into a printable report."""
    codes = parse_status_codes(text)
    lines = [describe(code) for code in codes]
    counts = summarize(codes)
    footer = '{0} codes, {1} recognised, {2} unknown'.format(
        len(codes), counts['known'], counts['unknown'])
    lines.append(footer)
    return '\n'.join(lines)


def main():
    raw_line = '200, 404, 500, 401, 302, 999'
    print(build_report(raw_line))


if __name__ == '__main__':
    main()

