def update_dict(dict1, dict2):
    """Merge dict2 into a copy of dict1 and return the result."""
    if not isinstance(dict1, dict):
        raise TypeError("dict1 must be a dict, got {}".format(type(dict1).__name__))
    if not isinstance(dict2, dict):
        raise TypeError("dict2 must be a dict, got {}".format(type(dict2).__name__))
    merged_dict = dict(dict1)
    for key in dict2:
        merged_dict[key] = dict2[key]
    return merged_dict


def classify_keys(dict1, dict2):
    """Split the keys of dict2 into those that overwrite and those that are new."""
    overwritten = []
    added = []
    for key in dict2:
        if key in dict1:
            overwritten.append(key)
        else:
            added.append(key)
    return overwritten, added


def describe_merge(dict1, dict2):
    """Build a human readable summary of what merging the two dicts does."""
    overwritten, added = classify_keys(dict1, dict2)
    merged_dict = update_dict(dict1, dict2)
    lines = ["merged size: {}".format(len(merged_dict))]
    for key in overwritten:
        old = dict1[key]
        new = dict2[key]
        if old == new:
            lines.append("  {!r} unchanged ({!r})".format(key, new))
        else:
            lines.append("  {!r}: {!r} -> {!r}".format(key, old, new))
    for key in added:
        lines.append("  {!r} added as {!r}".format(key, dict2[key]))
    return "\n".join(lines)


def merge_all(dicts):
    """Fold a sequence of dicts together, later ones winning over earlier ones."""
    result = {}
    for current in dicts:
        result = update_dict(result, current)
    return result


def main():
    cases = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ({'x': 10}, {'y': 20}),
        ({'k': 'same', 'n': 1}, {'k': 'same', 'n': 2}),
    ]
    index = 1
    for left, right in cases:
        print("case {}".format(index))
        print("  first :", left)
        print("  second:", right)
        print("  result:", update_dict(left, right))
        print(describe_merge(left, right))
        index += 1
    chain = [d for pair in cases for d in pair]
    combined = merge_all(chain)
    keys = sorted(combined, key=str)
    print("chained merge over {} dicts".format(len(chain)))
    for key in keys:
        print("  {!r} = {!r}".format(key, combined[key]))


if __name__ == "__main__":
    main()

