def count_words(text):
    """Count words in text, where words are separated by runs of spaces."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    word_count = 0
    in_word = False
    for char in text:
        if char.isspace():
            in_word = False
        elif not in_word:
            in_word = True
            word_count += 1
    return word_count


def split_words(text):
    """Return the list of words found in text, ignoring extra separators."""
    words = []
    current = ""
    for char in text:
        if char.isspace():
            if current:
                words.append(current)
                current = ""
        else:
            current += char
    if current:
        words.append(current)
    return words


def average_word_length(text):
    """Mean length of the words in text, or 0.0 when there are none."""
    words = split_words(text)
    if not words:
        return 0.0
    total = 0
    for word in words:
        total += len(word)
    return total / len(words)


def longest_word(text):
    """Return the first word of maximal length, or an empty string."""
    best = ""
    for word in split_words(text):
        if len(word) > len(best):
            best = word
    return best


def format_report(text):
    """Build a one-line summary of the word statistics of text."""
    count = count_words(text)
    average = average_word_length(text)
    longest = longest_word(text)
    label = "words"
    if count == 1:
        label = "word"
    parts = [repr(text)]
    parts.append("{0} {1}".format(count, label))
    parts.append("avg length " + format(average, ".2f"))
    if longest:
        parts.append("longest " + repr(longest))
    return " | ".join(parts)


def main():
    samples = [
        "This is a test sentence.",
        "  Hello   world  ",
        "",
        "single",
        "tabs\tand\nnewlines count as separators too",
    ]
    grand_total = 0
    for sample in samples:
        print(format_report(sample))
        grand_total += count_words(sample)
    print("total words across samples:", grand_total)


if __name__ == "__main__":
    main()

