import sys
from collections import Counter


MAX_MENTION_LENGTH = 15


def _is_mention_char(char):
    if char == '_':
        return True
    return char.isalnum()


def _leading_name(part):
    name = []
    for char in part:
        if not _is_mention_char(char):
            break
        if len(name) >= MAX_MENTION_LENGTH:
            break
        name.append(char)
    return ''.join(name)


def extract_mentions(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    mentions_list = []
    for part in text.split('@')[1:]:
        name = _leading_name(part)
        if name != '':
            mentions_list.append(name)
    return mentions_list


def count_mentions(text):
    lowered = [name.lower() for name in extract_mentions(text)]
    return Counter(lowered)


def rank_mentions(counts):
    items = list(counts.items())
    items.sort(key=lambda pair: (-pair[1], pair[0]))
    return items


def _share(freq, total):
    return freq / total


def format_report(text):
    total = len(extract_mentions(text))
    if total == 0:
        return "mentions found: 0\n  (none)"
    counts = count_mentions(text)
    lines = [f"mentions found: {total}", f"distinct handles: {len(counts)}"]
    for name, freq in rank_mentions(counts):
        share = _share(freq, total)
        lines.append(f"  @{name}: {freq} ({share:.1%})")
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        texts = argv[1:]
    else:
        texts = [
            'Hello @user1, how are you @user2?',
            'No mentions here.',
            'ping @ada, @ada and @grace -- thanks @ada!',
        ]
    for index, text in enumerate(texts, start=1):
        print(f"text {index}: {text}")
        print(f"result: {extract_mentions(text)!r}")
        print(format_report(text))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

