from math import sqrt


def validate_inputs(values, weights):
    """Check that the two sequences can be combined into a weighted mean."""
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("values must not be empty")
    for weight in weights:
        if weight < 0:
            raise ValueError("weights must not be negative")


def weighted_terms(values, weights):
    """Return each value multiplied by its own weight."""
    terms = []
    for value, weight in zip(values, weights):
        terms.append(value * weight)
    return terms


def weighted_average(values, weights):
    """Return the weighted arithmetic mean of values using the given weights."""
    validate_inputs(values, weights)
    weight_sum = sum(weights)
    if weight_sum == 0:
        raise ValueError("the sum of the weights must not be zero")
    total = sum(weighted_terms(values, weights))
    return total / weight_sum


def deviations(values, mean):
    """Return the signed distance from the mean for every value."""
    gaps = []
    for value in values:
        gaps.append(value - mean)
    return gaps


def weighted_variance(values, weights):
    """Return the weighted variance of values around their weighted mean."""
    mean = weighted_average(values, weights)
    squares = []
    for gap in deviations(values, mean):
        squares.append(gap * gap)
    return weighted_average(squares, weights)


def normalized_weights(weights):
    """Return the weights rescaled so that they sum to one."""
    total = sum(weights)
    if total <= 0:
        raise ValueError("weights must sum to a positive number")
    shares = []
    for weight in weights:
        shares.append(weight / total)
    return shares


def format_report(label, values, weights):
    """Build a human readable one-line summary of a weighted data set."""
    avg = weighted_average(values, weights)
    variance = weighted_variance(values, weights)
    spread = sqrt(variance)
    shares = normalized_weights(weights)
    biggest = max(shares)
    position = shares.index(biggest)
    parts = [
        label + ":",
        "average {0:.4f}".format(avg),
        "sd {0:.4f}".format(spread),
        "item #{0} carries {1:.1%} of the weight".format(position + 1, biggest),
    ]
    return " ".join(parts)


def main():
    datasets = [
        ("grades", [10, 20, 30], [1, 2, 1]),
        ("coins", [5, 10], [0.5, 0.5]),
        ("prices", [1.25, 3.5, 2.0, 4.75], [10, 4, 6, 1]),
    ]
    pooled_values = []
    pooled_weights = []
    for label, values, weights in datasets:
        print(format_report(label, values, weights))
        pooled_values.extend(values)
        pooled_weights.extend(weights)
    overall = weighted_average(pooled_values, pooled_weights)
    print("pooled average: {0:.4f}".format(overall))


if __name__ == "__main__":
    main()

