import itertools
import random

HEADS = 'Heads'
TAILS = 'Tails'


def simulate_coin_flip():
    """Flip a fair coin once and return 'Heads' or 'Tails'."""
    toss = random.random()
    if toss < 0.5:
        result = HEADS
    else:
        result = TAILS
    return result


def flip_many(count):
    """Flip the coin `count` times and return the list of outcomes."""
    if count < 0:
        raise ValueError('count must not be negative')
    return [simulate_coin_flip() for _ in range(count)]


def tally(flips):
    """Count how often each face came up."""
    counts = {face: flips.count(face) for face in (HEADS, TAILS)}
    return counts


def longest_streak(flips):
    """Return the length of the longest run of identical outcomes."""
    runs = [len(list(group)) for _, group in itertools.groupby(flips)]
    if not runs:
