def flatten_dict(nested_dict, separator):
    if not isinstance(nested_dict, dict):
        raise TypeError("nested_dict must be a dict")
    if not isinstance(separator, str):
        raise TypeError("separator must be a str")
    flattened_dict = {}
    for key, value in nested_dict.items():
        outer = str(key)
        if isinstance(value, dict):
            for inner_key, inner_value in value.items():
                combined = separator.join([outer, str(inner_key)])
                flattened_dict[combined] = inner_value
        else:
            flattened_dict[outer] = value
    return flattened_dict


def depth(nested_dict):
    level = 1
    for value in nested_dict.values():
        if isinstance(value, dict):
            level = 2
    return level


def count_leaves(nested_dict):
    total = 0
    for value in nested_dict.values():
        if isinstance(value, dict):
            total += len(value)
        else:
            total += 1
    return total


def find_ambiguous_keys(nested_dict, separator):
    problems = []
    for key, value in nested_dict.items():
        name = str(key)
        if name.count(separator) > 0:
            problems.append(name)
        if isinstance(value, dict):
            for inner_key in value:
                inner_name = str(inner_key)
                if inner_name.count(separator) > 0:
                    problems.append(inner_name)
    return problems


def format_report(nested_dict, separator):
    flat = flatten_dict(nested_dict, separator)
    lines = ["depth: {0}".format(depth(nested_dict))]
    lines.append("leaves: {0}".format(count_leaves(nested_dict)))
    lines.append("flattened keys: {0}".format(len(flat)))
    for key in sorted(flat):
        entry = "  {0} -> {1}".format(key, repr(flat[key]))
        lines.append(entry)
    problems = find_ambiguous_keys(nested_dict, separator)
    if len(problems) > 0:
        joined = ", ".join(sorted(problems))
        lines.append("ambiguous keys: {0}".format(joined))
    return "\n".join(lines)


def main():
    samples = [
        ({'a': 1, 'b': {'c': 2, 'd': 3}}, '_'),
        ({'x': {'y': 10}}, '.'),
        ({'cfg': {'host': 'localhost', 'port': 8080}, 'debug': False}, ':'),
    ]
    for index, (nested, sep) in enumerate(samples, 1):
        header = "sample {0} separator={1}".format(index, repr(sep))
        print(header)
        print(flatten_dict(nested, sep))
        print(format_report(nested, sep))
        print("-" * 32)


if __name__ == "__main__":
    main()

