def reverse_word(word):
    """Return the characters of a word in reverse order."""
    chars = list(word)
    chars.reverse()
    return ''.join(chars)


def split_tokens(text):
    """Split text into blank runs and runs of visible characters."""
    tokens = []
    current = []
    current_blank = False
    for ch in text:
        blank = ch.isspace()
        if current and blank != current_blank:
            tokens.append(''.join(current))
            current = []
        current.append(ch)
        current_blank = blank
    if current:
        tokens.append(''.join(current))
    return tokens


def reverse_each_word(sentence):
    """Reverse the characters of every word, keeping the word order."""
    if not isinstance(sentence, str):
        raise TypeError('sentence must be a string')
    pieces = []
    for token in split_tokens(sentence):
        if token.isspace():
            pieces.append(token)
        else:
            pieces.append(reverse_word(token))
    return ''.join(pieces)


def words_of(sentence):
    """Return the tokens of a sentence that hold visible characters."""
    words = []
    for token in split_tokens(sentence):
        if not token.isspace():
            words.append(token)
    return words


def longest_word(sentence):
    """Return the first word of maximal length, or '' when there is none."""
    best = ''
    for word in words_of(sentence):
        if len(word) > len(best):
            best = word
    return best


def mean(values):
    """Return the arithmetic mean of a non-empty list of numbers."""
    return sum(values) / len(values)


def format_report(sentence):
    """Build a multi-line report about a sentence and its reversal."""
    lines = []
    lines.append('original : ' + sentence)
    lines.append('reversed : ' + reverse_each_word(sentence))
    count = len(words_of(sentence))
    lines.append('words    : ' + str(count))
    longest = longest_word(sentence)
    if longest:
        lines.append('longest  : ' + longest)
        lines.append('flipped  : ' + reverse_word(longest))
    return '\n'.join(lines)


def main():
    samples = ['hello world', 'Python is fun', '  ragged   text  here ']
    counts = []
    for sentence in samples:
        print(format_report(sentence))
        print('')
        counts.append(len(words_of(sentence)))
    total = sum(counts)
    average = mean(counts)
    print('total words: ' + str(total))
    print('average words per sample: ' + format(average, '.2f'))


if __name__ == '__main__':
    main()

