def extract_numbers_regex(text):
    digits = re.findall(r'\d', text)
    result_string = "".join(digits)
    return result_string

def extract_numbers_optimized(text):
    numeric_string = ""
    for char in text:
        if char.isdigit():
            numeric_string += char
    return numeric_string

def extract_numbers_list_comprehension(text):
    extracted = [char for char in text if char.isdigit()]
    final_result = "".join(extracted)
    return final_result

