import collections

def calculate_mode(numbers):
    if not numbers:
        return None

    counts = collections.defaultdict(int)
    for num in numbers:
        counts[num] = counts[num] + 1

    max_count = 0
    mode_value = None

    for num, count in counts.items():
        if count > max_count:
            max_count = count
            mode_value = num
        elif count == max_count and mode_value is None: # handle first element in case all counts are equal
            mode_value = num

    return mode_value

