def normalize_rectangle(x1, y1, x2, y2):
    """Return the rectangle corners ordered as left, bottom, right, top."""
    left = min(x1, x2)
    right = max(x1, x2)
    bottom = min(y1, y2)
    top = max(y1, y2)
    return left, bottom, right, top


def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    """Return True when (px, py) lies inside or on the border of the rectangle."""
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    if px < left:
        return False
    if px > right:
        return False
    if py < bottom:
        return False
    return py <= top


def is_point_on_border(px, py, x1, y1, x2, y2):
    """Return True when the point sits exactly on one of the rectangle edges."""
    if not is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return False
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    if px == left:
        return True
    if px == right:
        return True
    if py == bottom:
        return True
    return py == top


def axis_gap(value, low, high):
    """Return how far value falls outside the closed interval [low, high]."""
    if value < low:
        return low - value
    if value > high:
        return value - high
    return 0


def manhattan_gap(px, py, x1, y1, x2, y2):
    """Return the grid distance from the point to the nearest rectangle point."""
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    dx = axis_gap(px, left, right)
    dy = axis_gap(py, bottom, top)
    return dx + dy


def describe_point(px, py, x1, y1, x2, y2):
    """Build a readable line about how a point relates to the rectangle."""
    corners = normalize_rectangle(x1, y1, x2, y2)
    if is_point_on_border(px, py, x1, y1, x2, y2):
        relation = "on the border of"
    elif is_point_in_rectangle(px, py, x1, y1, x2, y2):
        relation = "strictly inside"
    else:
        relation = "outside"
    gap = manhattan_gap(px, py, x1, y1, x2, y2)
    return "({}, {}) is {} {} (gap {})".format(px, py, relation, corners, gap)


def main():
    rect = (0, 0, 5, 5)
    probes = [(3, 3), (6, 2), (0, 0), (5, 1), (-2, 7)]
    covered = 0
    for px, py in probes:
        if is_point_in_rectangle(px, py, *rect):
            covered += 1
        print(describe_point(px, py, *rect))
    print("{} of {} probes covered".format(covered, len(probes)))
    print("coverage {:.0%}".format(covered / len(probes)))


if __name__ == "__main__":
    main()

