def validate_interval(start, end, label):
    if not isinstance(start, int):
        raise TypeError("{} start time must be an integer".format(label))
    if not isinstance(end, int):
        raise TypeError("{} end time must be an integer".format(label))
    if start < 0:
        raise ValueError("{} cannot start before hour 0".format(label))
    if end > 24:
        raise ValueError("{} cannot end after hour 24".format(label))
    if start >= end:
        raise ValueError("{} must start before it ends".format(label))


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    validate_interval(task1_start, task1_end, "task1")
    validate_interval(task2_start, task2_end, "task2")
    latest_start = max(task1_start, task2_start)
    earliest_end = min(task1_end, task2_end)
    return latest_start < earliest_end


def overlap_hours(task1_start, task1_end, task2_start, task2_end):
    if not has_overlap(task1_start, task1_end, task2_start, task2_end):
        return 0
    latest_start = max(task1_start, task2_start)
    earliest_end = min(task1_end, task2_end)
    return earliest_end - latest_start


def gap_hours(a_start, a_end, b_start, b_end):
    if b_start >= a_end:
        return b_start - a_end
    return a_start - b_end


def format_hour(hour):
    return "{:02d}:00".format(hour)


def format_interval(start, end):
    return "{}-{}".format(format_hour(start), format_hour(end))


def describe(task1, task2):
    a_start, a_end = task1
    b_start, b_end = task2
    left = format_interval(a_start, a_end)
    right = format_interval(b_start, b_end)
    shared = overlap_hours(a_start, a_end, b_start, b_end)
    if shared > 0:
        return "{} and {} overlap by {} hour(s)".format(left, right, shared)
    gap = gap_hours(a_start, a_end, b_start, b_end)
    return "{} and {} do not overlap (gap of {} hour(s))".format(left, right, gap)


def find_conflicts(schedule):
    conflicts = []
    total = len(schedule)
    for i in range(total):
        for j in range(i + 1, total):
            first = schedule[i]
            second = schedule[j]
            if has_overlap(first[1], first[2], second[1], second[2]):
                conflicts.append((first[0], second[0]))
    return conflicts


def main():
    print(has_overlap(9, 12, 11, 14))
    print(has_overlap(9, 10, 10, 12))
    print(describe((9, 12), (11, 14)))
    print(describe((9, 10), (13, 15)))
    schedule = [("standup", 9, 10), ("review", 9, 11), ("lunch", 12, 13)]
    for name_a, name_b in find_conflicts(schedule):
        print("conflict: {} vs {}".format(name_a, name_b))


if __name__ == "__main__":
    main()

