class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        if not self.items:
            return None
        return self.items.pop(0)

def main():
    my_queue = Queue()

    print(f"Dequeue from empty queue: {my_queue.dequeue()}") # Expected: None

    my_queue.enqueue(10)
    my_queue.enqueue(20)
    my_queue.enqueue(30)

    print(f"Queue after enqueues: {my_queue.items}") # Expected: [10, 20, 30]

    first_item = my_queue.dequeue()
    print(f"Dequeued item: {first_item}") # Expected: 10
    print(f"Queue after first dequeue: {my_queue.items}") # Expected: [20, 30]

    second_item = my_queue.dequeue()
    print(f"Dequeued item: {second_item}") # Expected: 20
    print(f"Queue after second dequeue: {my_queue.items}") # Expected: [30]

    if len(my_queue.items) > 0:
        remaining_item = my_queue.dequeue()
        print(f"Dequeued item: {remaining_item}") # Expected: 30
        print(f"Queue after third dequeue: {my_queue.items}") # Expected: []

    another_item = my_queue.dequeue()
    if another_item is None:
        print(f"Queue is empty, another dequeue returned: {another_item}") # Expected: None

if __name__ == "__main__":
    main()

