def parse_url_params(query_string: str) -> dict:
    params = {}
    if not query_string:
        return params

    pairs = query_string.split('&')
    for pair in pairs:
        if '=' in pair:
            key_value = pair.split('=', 1)
            key = key_value[0]
            value = key_value[1]
            params[key] = value
        else:
            params[pair] = ''
    return params

if __name__ == '__main__':
    result1 = parse_url_params('name=John&age=30')
    expected1 = {'name': 'John', 'age': '30'}
    print(f"Test 1 Passed: {result1 == expected1}")

    result2 = parse_url_params('q=python+programming')
    expected2 = {'q': 'python+programming'}
    print(f"Test 2 Passed: {result2 == expected2}")

    result3 = parse_url_params('')
    expected3 = {}
    print(f"Test 3 Passed: {result3 == expected3}")

    result4 = parse_url_params('param1=value1&param2&param3=value3')
    expected4 = {'param1': 'value1', 'param2': '', 'param3': 'value3'}
    print(f"Test 4 Passed: {result4 == expected4}")

    result5 = parse_url_params('a=b=c&d=e')
