def parse_url_params(query_string: str) -> dict:
    params={}
    if not query_string:
        return params

    pairs=query_string.split('&')
    for pair in pairs:
        if '=' in pair:
            key_value=pair.split('=', 1)
            key=key_value[0]
            value=key_value[1]
            params[key]=value
        else:
            params[pair]=''
    return params

