from collections import deque, namedtuple

Average = namedtuple("Average", "index value")
Spread = namedtuple("Spread", "index gap")


def validate_inputs(data, window_size):
    """Check that the data series and window size can produce an SMA."""
    if isinstance(window_size, bool) or not isinstance(window_size, int):
        raise TypeError("window_size must be an integer")
    if window_size < 1:
        raise ValueError("window_size must be at least 1")
    for index, value in enumerate(data):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("data[{0}] is not numeric".format(index))
    if window_size > len(data):
        raise ValueError("window_size exceeds the number of data points")


def sma_series(data, window_size):
    """Yield each complete window's average with the index where it ends."""
    window = deque(maxlen=window_size)
    for index, value in enumerate(data):
        window.append(value)
        if len(window) == window_size:
            yield Average(index, sum(window) / len(window))


def calculate_sma(data, window_size):
    """Return the simple moving averages of data over a sliding window."""
    validate_inputs(data, window_size)
    averages = []
    for point in sma_series(data, window_size):
        averages.append(point.value)
    return averages


def signs_differ(first, second):
    """True when two gaps sit on opposite sides of zero."""
    if first < 0:
        return second > 0
    if first > 0:
        return second < 0
    return False


def sma_spreads(data, short_window, long_window):
    """Gap between the short and the long average at each shared index."""
    fast = {point.index: point.value for point in sma_series(data, short_window)}
    spreads = []
    for point in sma_series(data, long_window):
        spreads.append(Spread(point.index, fast[point.index] - point.value))
    return spreads


def crossover_points(data, short_window, long_window):
    """Indices where the short average crosses the long average."""
    validate_inputs(data, long_window)
    if short_window >= long_window:
        raise ValueError("short_window must be smaller than long_window")
    crossings = []
    spreads = sma_spreads(data, short_window, long_window)
    for before, after in zip(spreads, spreads[1:]):
        if signs_differ(before.gap, after.gap):
            crossings.append(after.index)
    return crossings


def format_report(data, window_size):
    """Table of each window's final value and its moving average."""
    validate_inputs(data, window_size)
    lines = ["index    value      sma"]
    for point in sma_series(data, window_size):
        lines.append("{0:5d}  {1:7.2f}  {2:7.3f}".format(
            point.index, float(data[point.index]), point.value))
    return "\n".join(lines)


def main():
    print(calculate_sma([1, 2, 3, 4, 5], 3))
    print(calculate_sma([10, 20, 30, 40], 2))
    prices = [12, 15, 14, 18, 22, 19, 17, 21, 25, 24, 20, 18]
    print(format_report(prices, 4))
    labels = [str(index) for index in crossover_points(prices, 2, 5)]
    print("crossovers at indices: " + ", ".join(labels))


if __name__ == "__main__":
    main()

