def is_perfect_number(number: int) -> bool:
    if number <= 0:
        return False

    divisor_sum = 0
    limit = int(number ** 0.5) + 1

    for i in range(1, limit):
        if number % i == 0:
            divisor_sum = divisor_sum + i
            if i * i != number and i != 1:
                divisor_sum = divisor_sum + (number // i)

    return divisor_sum == number

