    char_count = {}

    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    n = len(s)

    i = 0
    while i < n:
        char = s[i]
        count = char_count[char]
        if count == 1:
            return i
        i = i + 1

    return -1

