import math

def geometric_mean(numbers):
    if not numbers:
        return 0.0

    product = 1.0
    count = 0

    for num in numbers:
        if num <= 0:
            return 0.0
        product = product * num
        count = count + 1

    if count == 0:
        return 0.0

    mean = product ** (1 / count)
    return float(mean)

