def convert_temperature(value, unit_from, unit_to):
    celsius_value = 0.0

    if unit_from == 'C':
        celsius_value = value
    elif unit_from == 'F':
        celsius_value = (value - 32.0) * (5.0 / 9.0)
    elif unit_from == 'K':
        celsius_value = value - 273.15

    result = 0.0

    if unit_to == 'C':
        result = celsius_value
    elif unit_to == 'F':
        result = celsius_value * (9.0 / 5.0) + 32.0
    elif unit_to == 'K':
        result = celsius_value + 273.15

    return result

