import re

def reverse_words_with_punctuation(sentence):
    if not sentence:
        return ""

    words = re.findall(r"\S+\s*", sentence)
    if not words:
        return ""

    reversed_words = []
    for i in range(len(words) - 1, -1, -1):
        word = words[i].strip()
        trailing_space = " " if i > 0 and words[i - 1].endswith(" ") else ""
        reversed_words.append(word + trailing_space)

