def find_divisors(n):
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    divs = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i = i + 1

    divs.sort()
    return divs

