def is_valid_isbn10(isbn):
    if len(isbn) != 10:
        return False

    total_sum = 0
    for i in range(9):
        char = isbn[i]
        if not char.isdigit():
            return False
        digit = int(char)
        total_sum += digit * (i + 1)

    last_char = isbn[9]
    if last_char.isdigit():
        last_digit = int(last_char)
    elif last_char == 'X' or last_char == 'x':
        last_digit = 10
    else:
        return False

    total_sum += last_digit * 10

    if total_sum % 11 == 0:
        return True
    else:
        return False

