def justify_text_simple(words, max_width):
    if not words:
        return ""

    num_words = len(words)
    total_length = sum(len(word) for word in words)
    spaces_needed = max_width - total_length

    if num_words == 1:
        return words[0].ljust(max_width)

    # Calculate base spaces and extra spaces
    base_spaces = spaces_needed // (num_words - 1)
    extra_spaces = spaces_needed % (num_words - 1)

    result = []
    for i in range(num_words):
        result.append(words[i])
        if i < num_words - 1:
            current_spaces = base_spaces
            if i < extra_spaces:
                current_spaces = current_spaces + 1
            result.append(" " * current_spaces)

    final_string = "".join(result)
    current_length = len(final_string)
    if current_length < max_width:
        final_string = final_string + " " * (max_width - current_length)

    return final_string

