    sorted_numbers=sorted(numbers)
    n=len(sorted_numbers)

    if n%2==1:
        middle_index=n//2
        return sorted_numbers[middle_index]
    else:
        mid_right_index=n//2
        mid_left_index=mid_right_index-1
        median_value=(sorted_numbers[mid_left_index]+sorted_numbers[mid_right_index])/2.0
        return median_value

