def is_valid_us_zip_code(zip_code):
    """
    Validates a US zip code.

    A valid zip code is a string of exactly 5 digits.
    """
    if not isinstance(zip_code, str):
        return False

    if len(zip_code) != 5:
        return False

    for char_index in range(len(zip_code)):
        current_char = zip_code[char_index]
        if not ('0' <= current_char and current_char <= '9'):
            return False

    return True

