def censor_text(text, bad_words):
    censored_text = []
    words = text.split()
    for word in words:
        cleaned_word = ''.join(char for char in word if char.isalnum())
        suffix = ''.join(char for char in word if not char.isalnum())
        if cleaned_word.lower() in [bw.lower() for bw in bad_words]:
            censored_word = '*' * len(cleaned_word) + suffix
            censored_text.append(censored_word)
        else:
            censored_text.append(word)
    return ' '.join(censored_text)

