ALPHABET_SIZE = 26
LOWER = "abcdefghijklmnopqrstuvwxyz"
UPPER = LOWER.upper()
COMMON = "etaoin"

from collections import Counter


def _rotate(alphabet, index, shift):
    position = index + shift
    position %= ALPHABET_SIZE
    return alphabet[position]


def _shift_char(char, shift):
    index = LOWER.find(char)
    if index < 0:
        index = UPPER.find(char)
        if index < 0:
            return char
        return _rotate(UPPER, index, shift)
    return _rotate(LOWER, index, shift)


def caesar_encrypt(text, shift):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(shift, int):
        raise TypeError("shift must be an integer")
    encrypted = [_shift_char(char, shift) for char in text]
    return "".join(encrypted)


def caesar_decrypt(text, shift):
    return caesar_encrypt(text, -shift)


def letter_frequencies(text):
    counts = Counter()
    for char in text.lower():
        if char in LOWER:
            counts[char] += 1
    return counts


def _common_ratio(counts):
    total = sum(counts.values())
    if total == 0:
        return 0.0
    hits = sum(counts[letter] for letter in COMMON)
    return hits / total


def guess_shift(text):
    best_shift = 0
    best_score = -1.0
    for shift in range(ALPHABET_SIZE):
        candidate = caesar_decrypt(text, shift)
        score = _common_ratio(letter_frequencies(candidate))
        if score > best_score:
            best_score = score
            best_shift = shift
    return best_shift


def format_report(text, shift):
    cipher = caesar_encrypt(text, shift)
    recovered = caesar_decrypt(cipher, shift)
    guessed = guess_shift(cipher)
    lines = [f"plain:     {text}"]
    lines.append(f"shift:     {shift}")
    lines.append(f"cipher:    {cipher}")
    lines.append(f"recovered: {recovered}")
    lines.append(f"guessed:   {guessed}")
    if recovered == text:
        status = "ok"
    else:
        status = "mismatch"
    lines.append(f"status:    {status}")
    return "\n".join(lines)


def main():
    samples = [("ABC", 1), ("Hello, World!", 3), ("The quick brown fox jumps over the lazy dog", 13)]
    total_letters = 0
    for text, shift in samples:
        print(format_report(text, shift))
        print("-" * 40)
        total_letters += sum(letter_frequencies(text).values())
    print(f"letters processed: {total_letters}")


if __name__ == "__main__":
    main()

