def mean(values):
    """Arithmetic mean of the given values, or 0.0 when there are none."""
    if not values:
        return 0.0
    total = 0.0
    for value in values:
        total += value
    return total / len(values)


def validate_ratings(movie_ratings):
    """Return the ratings dictionary, raising errors for malformed input."""
    if not isinstance(movie_ratings, dict):
        raise TypeError("movie_ratings must be a dictionary")
    for title, ratings in movie_ratings.items():
        if not isinstance(title, str):
            raise TypeError("movie titles must be strings")
        if not isinstance(ratings, (list, tuple)):
            raise TypeError("ratings for {0} must be a list".format(title))
        for rating in ratings:
            if isinstance(rating, bool) or not isinstance(rating, (int, float)):
                raise TypeError("rating values for {0} must be numbers".format(title))
            if rating < 0:
                raise ValueError("rating {0} for {1} is negative".format(rating, title))
            if rating > 10:
                raise ValueError("rating {0} for {1} is too large".format(rating, title))
    return movie_ratings


def get_average_movie_rating(movie_ratings):
    """Map each movie title to the average of its ratings (0.0 when empty)."""
    validate_ratings(movie_ratings)
    averages = {}
    for title, ratings in movie_ratings.items():
        averages[title] = mean(ratings)
    return averages


def rating_spread(ratings):
    """Difference between the highest and lowest rating, or 0.0 if empty."""
    if not ratings:
        return 0.0
    highest = max(ratings)
    lowest = min(ratings)
    return float(highest - lowest)


def rank_movies(averages):
    """Titles sorted by average rating, highest first, ties broken by name."""
    order = sorted(averages)
    order.sort(key=averages.get, reverse=True)
    return order


def format_report(movie_ratings):
    """Build a human readable ranking table for the given ratings."""
    averages = get_average_movie_rating(movie_ratings)
    order = rank_movies(averages)
    width = 0
    for title in order:
        if len(title) > width:
            width = len(title)
    lines = []
    place = 1
    for title in order:
        ratings = movie_ratings[title]
        spread = rating_spread(ratings)
        padded = title.ljust(width)
        lines.append("{0}. {1}  avg={2:.2f}  votes={3}  spread={4:.1f}".format(
            place, padded, averages[title], len(ratings), spread))
        place += 1
    return "\n".join(lines)


def main():
    catalogue = {
        'Movie A': [5, 4, 5],
        'Movie B': [3, 2],
        'Movie C': [],
        'Movie D': [10],
    }
    averages = get_average_movie_rating(catalogue)
    print(averages)
    print(format_report(catalogue))
    rated = [averages[title] for title in catalogue if catalogue[title]]
    print("Average of rated movies: {0:.3f}".format(mean(rated)))


if __name__ == '__main__':
    main()

