import sys

SEPARATORS = ("-", " ")
GROUP_SIZES = (3, 3, 4)
DIGIT_COUNT = 10


def strip_separators(text):
    """Return the text with hyphens and spaces removed."""
    kept = [char for char in text if char not in SEPARATORS]
    return "".join(kept)


def separator_positions(text):
    """Return the indexes at which a separator character appears."""
    positions = []
    for index, char in enumerate(text):
        if char in SEPARATORS:
            positions.append(index)
    return positions


def expected_positions():
    """Return the only indexes where separators may legally sit."""
    positions = []
    cursor = 0
    for size in GROUP_SIZES[:-1]:
        cursor += size
        positions.append(cursor)
        cursor += 1
    return positions


def is_valid_us_phone_number(number):
    if not isinstance(number, str):
        return False
    digits = strip_separators(number)
    if len(digits) != DIGIT_COUNT:
        return False
    if not digits.isdigit():
        return False
    found = separator_positions(number)
    if not found:
        return True
    return found == expected_positions()


def format_report(number):
    """Describe one candidate number as a single report line."""
    if is_valid_us_phone_number(number):
        verdict = "valid"
    else:
        verdict = "invalid"
    return "%-20s %s" % (repr(number), verdict)


def main(argv):
    candidates = argv[1:]
    if not candidates:
        candidates = ["123-456-7890", "123 456 7890", "1234567890",
                      "(123) 456-7890", "12-3456-7890", "123-456-789"]
    failures = 0
    for candidate in candidates:
        print(format_report(candidate))
        if not is_valid_us_phone_number(candidate):
            failures += 1
    print("checked %d, invalid %d" % (len(candidates), failures))
    if failures:
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

